/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180514-9","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"文教委員会","time":"午後 １時００分～午後 ３時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度新入学学校別増減要因一覧","agenda":"平成３０年度新入学学校別増減要因一覧","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最初に、今回の増減の傾向といいますか、どういった形で増減しているのかというところを教えていただければと思います。","respondent":"篠田学務課長","answer":"それともう１つは、現在、学校の改築が大分進んできておりまして、その改築による影響も若干見られるように感じております。例えば、城南小学校ですとか、芳水小学校、こちらは、実は昨年、かなり大きく減っているのですけれども、今年度少し戻してきているような形があります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そこで、選択制と指定校変更の役割の違いを伺いたいと思います。指定校変更している方の理由についても、あわせて伺いたいと思います。","respondent":"篠田学務課長","answer":"学校選択制と指定校変更の役割ですけれども、学校選択制はそもそも１年生、７年生で１０月１日にお住まいになられているお子さん方が、小学校あるいは義務教育学校（前期課程）もしくは中学校や後期課程に進学するに当たって。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"一応役割の違いは、機会も含めてあるということで、チャンスが２回あるというわけではないということは私もわかっているつもりですけれども、これまで共産党としては、選択制は地域とのつながりも弱め、地域の教育力を弱めていくというところで廃止にすべきだと言ってきましたけれども、指定校変更で選択できる権利を確保することができるのではないかと考えているのですが。","respondent":"篠田学務課長","answer":"これに対して指定校変更というのは、さまざまな事情に応じた実務的な制度という位置づけがありますので、現状としましては、基本的に学校選択制をきちんと運用していく中で品川の教育を高めていきたいというふうに考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"選択制は教育的観点からやっているというお話ですけれども、やはり地域からもつながりが弱まっているという声も出ているわけですから、そういったところはしっかりと受けとめていっていただきたいと思うのです。","respondent":"篠田学務課長","answer":"ご質問のあった教育的な観点の部分としても、これまで学校が内に閉じこもって、なかなか外との接触もなくてという中で、積極的に学校の取り組みを外に対してアピールしていく、また、保護者の方、あるいは児童・生徒ご本人も含めて。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"意見","question":"こういった今回の実際の入学の人数を見ましても、ちょっと言葉は不適切かもしれませんけれども、人気校と不人気校というところで格差が出てきてしまっているという状況になってきておりますので、やはり選択制はやめていくべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"去年１０月１日の登録者数と、減要因の希望（実）という数字を見比べたときに、その割合が、３０％を超えている学校が９校あります。浜川小は４４％、第四日野小は４６％です。中延小にいたっては７６％が選んでいない。はほぼ同じような状況で３０数％、４０％台というところがあるのです。そういう点で教育委員会はどう思っているのか、まず、その２点を伺いたいと思います。","respondent":"篠田学務課長","answer":"今後も引き続きそういった形の取り組みは続けてまいりますので、小規模校に関しては、それぞれの地域の皆様方から選ばれるような学校にしていただくような形で取り組んでいくということで、学校自体をなくしていくということを考えているものではございません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"学校自体をなくしていくものではないということが今あったので、それはそれとして伺い、一部安心もするのですけれども、１００％安心することはとてもできないと私は思います。そういう事実が過去にあるわけですから、いずれこの中延小学校もそういう事態になってしまうのではないかと思うのです。やっぱりそれをどういうふうに見るのかというところを伺っておかないといけないと思います。いかがでしょうか。","respondent":"篠田学務課長","answer":"あの中身はどういったものかと言えば、学校に対する支援や、地域との結びつき等も含めて、さまざまな形で考えられるもの、あらゆる可能性を追求していく必要があるだろうという意味での対応策ということになってありますので、教育委員会としましても。","voiceIndex":16,"id":"exchange-007"},{"speaker":"南委員","kind":"意見","question":"どういうふうに支援をしていくとか言っているけれども、現実的に中延小学校で支援しても効果があらわれていないと言ったら言い過ぎかもしれないけれども、現場の先生方には大変申しわけない、ショックな表現になってしまうかもしれないけれども、あえてそういうことを言わせていただくと、効果があらわれていないというふうに言わざるを得ないと思うのですけれども。","respondent":"篠田学務課長","answer":"昨年度の１６名から今年度９名ということで、７名減ってしまったわけですけれども、逆に言えば、昨年度は７名多かったですので、どうしてもそれぞれの年度に応じまして、それぞれご事情を抱えている方、ご家庭がありますから。","voiceIndex":18,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"事情を抱えている家庭が中延小学校周辺で、よその地域より多いということは考えられないのではないでしょうか。やっぱりきちんとした支援をするべきだし、それから、本当に先生方の努力、少人数の教員配置しかできないという状況だからこそ先生たちがさらに大変になるのだろうと思うのです。そのやる姿勢があるのかどうか、そこを含めてこの質問は終わりにしたいと思います。","respondent":"篠田学務課長","answer":"したがいまして、そういった状況から脱却するために、教育委員会としましても引き続き最大限、今まで以上に支援を続けていきたいと考えているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"支援を最大限にしていくというところは、ぜひ私もしっかりと受けとめていきますので、よろしくお願いしたいと思いますけれども、やっぱり小規模校になったから自然淘汰されていくのだという、そういう考え方だけはとらないでいただきたいと思います。その点、答弁を聞きたいと思います。","respondent":"篠田学務課長","answer":"教育委員会の基本的な考え方として、子どもの数が少なくなっていくので、学校をなくす方向で整備をしていくということを前提とした取り組みは今後もしていく予定はございません。","voiceIndex":22,"id":"exchange-010"},{"speaker":"渡部委員","kind":"意見","question":"選択制によって人数がどうこうというのでなく、現状、実際に子どもがどれぐらいいるのか、その地域にどれぐらいいるのか、歩いて何分で学校へ通えるのかというのは、精査して、やはり地域に対して、これから１０年後、２０年後において、品川区の学校はこういうふうに必要になっていくのだということまで示していくべきではないかと思う。選択制によって少なくなったから学校を潰すのではないです。","respondent":"篠田学務課長","answer":"今後、当面は今のところ、私どもがつかんでいる範囲では、お子さんの数は、当面１０年、あるいはそれ以上にわたって増えていくというふうに認識していますので、そういった中では。","voiceIndex":24,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういった中で建て替えをしていくとなると、当然、これからの建物はまた６０年とかもつわけですから、果たして６０年後に必要なのかと言ったら、それはわからないですね。当然、よその自治体とかもそうですし、私たちも会派として要望をずっと入れていますけれども、例えば転用可能なつくりにしておくだとか、さまざまその辺は考えて、これからも進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"}]},{"id":"topic-02","title":"平成３１年度品川区立学校教育職員採用候補者選考日程","agenda":"平成３１年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"品川区固有教員については予算書では１０月の段階の数字だったのですけれども、４月１日で変わっていなければ何人かということと、あと、管理職の先生が１人いらっしゃるのですけれども、主幹と主任の先生が何人いらっしゃるか。主幹と主任のところは、なぜお尋ねしたかというと、学校の運営に一生懸命意欲を持ってなされるような立場になられる方がどれぐらいいらっしゃるか知りたいからです。","respondent":"熊谷指導課長","answer":"昨年度は、品川区固有教員は２７名おりました。今年度は２７名ということで予定しておりましたが、１名、年度末に、親御さんの介護が急に入りまして、平成２５年採用の教員が長崎に帰ってしまいました。ですので、今年度は１名減の２６名でのスタートとなっております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"いろいろな事情があって主幹や主任を受験される方もいらっしゃると思いますけれども、さっきもお話ししたように、学校の中のリーダーになっていこうと思われる方が多いように伺っているのですが、そういうところもお話ししていただければと思いました。","respondent":"熊谷指導課長","answer":"ですので、こちらは単に筆記試験、それから面接試験が通ったというよりも、日ごろの教育活動の中でしっかりと主幹として活躍できるか、主任として活躍できるのか、そういったことも加味しながら、育成をしながら次の主幹教諭、主任教諭。","voiceIndex":33,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどもお話ししたように、学校の中のリーダーになっていっていただける先生方と思うので、引き続き、育成などについて、教育委員会のほうでもバックアップしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"}]},{"id":"topic-03","title":"品川区立公共図書館・学校図書館システム再構築による休館","agenda":"品川区立公共図書館・学校図書館システム再構築による休館","exchanges":[{"speaker":"南委員","kind":"質問","question":"システムを変更する目的というか、使い勝手をよくするだとか、そういうところがよくわからなかったので、何のためのシステム再構築なのかを教えてください。","respondent":"横山品川図書館長","answer":"なので、新しいシステムに替えて、現在の状況に合わせるとともに、ＩＣタグであるとか、新しい技術を取り入れた図書館システムに対応するための準備も兼ねまして、利用者の利便性が図られるよう構築を進めたいと考えています。","voiceIndex":40,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"利便性が高くなるというふうに期待をして待っていればいいということですか。","respondent":"横山品川図書館長","answer":"そのようなシステムになるように調整をしてまいります。","voiceIndex":42,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"休館は学校のほうはまだ１４日まで休館するというのは決まっていないということでいいかということと、あと、利用者への周知ですけれども、いつごろからやるのでしょうか。あわせて、休館のときには全て利用できなくなるということになる。というのは、返却ポストとか、そういったところは利用できるのか、そこも伺いたいと思います。","respondent":"横山品川図書館長","answer":"町会の集まり等でも、できる限りご案内を差し上げる予定です。返却ポストにつきましては、機器とはまた別ですので、こちらのほうで返却をお受けする予定です。","voiceIndex":45,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の方が間違えて来ないようにしっかりと周知をしていただきたいと思います。システム再構築ということで、先ほども少しご説明があったのですが、まだ設計中で決まっていないということでしたけれども、利用者の目線ではどのような変更が予想されているのか、また検討されているのかを伺いたいと思います。","respondent":"横山品川図書館長","answer":"利用者の方の利便性につきましては、例えば今までですと、検索しても本の書名と作者しかわからなかったのが、表紙の絵が出てくるだとか、少しわかりやすいような表示にできると予定しています。こちらも確定しましたら、またご案内できればと思ってあります。","voiceIndex":47,"id":"exchange-019"}]},{"id":"topic-04","title":"平成３０年４月入園申込状況等","agenda":"平成３０年４月入園申込状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最初の資料の１ページ目のところで、申込み等の状況ということで書かれておりますけれども、前回の委員会で不承諾通知書の発送数を聞いたときに、８７８名という報告があったと思ったのですけれども、今回、不承諾数で見ると、７０６名ということで、なぜ減ったのか、理由を伺いたいと思います。","respondent":"大澤保育支援課長","answer":"不承諾数から差し引く数ですが、まず既に保育園を利用していて、転園希望を出された方が１４９名、求職活動の要件で申し込みをされ求職をやめた方が４３名、認証保育所と認可保育園以外の保育施設を利用される方が２６８名。","voiceIndex":54,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"不承諾数が二次と比べて減ったというところで、繰り上げて入園したというのはどういったことなのか、ちょっとよくわからなかったので、そこをもう少しご説明いただければと思います。内訳のところで、認証等の方が２６８名というお話でしたけれども、認証に行った方、企業型に行った方、認可外に行った方がどれだけいらっしゃったのかお伺いします。","respondent":"大澤保育支援課長","answer":"辞退の方は、一次、二次合わせて、今回も３３１名いらっしゃいましたので、入園が決まった方の割合から考えますと、１割以上が辞退ということで、そういう中で数としてかなり大きな動きが出てくるです。","voiceIndex":56,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"それをお伺いいたします。というところで、今回、待機児童数が昨年よりも２００人減ったということは、一定、評価したいと思います。待機児童数が少なくなったことについて区の分析を伺いたいと思います。昨年は１０園だったと思うのですが、認可保育園を増設したのですけれども、１７８人から２１９人に待機児童数が増えてしまいました。昨年と今年の違いは何だと考えているのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"国の定義の変更につきましては、大きく変わったところはございませんけれども、育児休業の方につきましては、一定期間延長することが決まっている方を、今回、待機児童から除いたというところが変更点です。","voiceIndex":58,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"今回、区の計算上は０歳児の待機児童がゼロになる見込みだったと思うのですけれども、ゼロにならなかった原因を伺いたいと思います。地区別の待機児数を見て私は意外だったのですけれども、もう少しばらけるのかと思っていたのですが、東大井・八潮地区と、五反田地区のみという結果になっていますけれども、この２つの地区で待機児童が発生した要因をどのように考えているのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"０歳児がゼロにならなかったということですけれども、先ほども申し上げましたように、認証を含めますと受け皿としては用意できておりますので、全ての方、それぞれ状況がありますし、お考えもありますので、そういう意味では、全てのニーズにこたえることは難しいですけれども。","voiceIndex":60,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"子どもたちは４月に生まれるわけではなくて、１年間の中で生まれていきますから、ある程度余裕を持った増設が必要だと思いますけれども、いかがでしょうか。既に申し込みから１カ月あまりたっているわけですけれども、この１９名の待機児童となった方々が、その後どうされているのか、どういった対策をとってきたのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"ただ、申し込みされた方がどうしても認可でなくてはいけないか、認証ではいけないのかという話になりますと、今年度につきましても、不承諾になった方の半数以上は希望園として３園までしかお書きになっていないということで、もし近くの認可に入れなければ。","voiceIndex":62,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"やはり待機児童となった方たちの、今回、４月時点で１９名ということでゼロにできませんでしたということで終わらせずに、しっかりと支援をしていくということが必要なのではないかと思いますけれども、今後の入園も含めて、手立てをどう考えていらっしゃるのか伺いたいと思います。やはり待機児ゼロを目指していくということであれば、入れなかった方々への支援も必要だと思いますので、伺いたいと思います。","respondent":"大澤保育支援課長","answer":"認証保育所や、地域によっては認可保育園に空きがありますので、そのような情報が漏れなく伝わるように周知を図っていきたいと考えています。","voiceIndex":64,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"ちょっと重なるところもあるかもしれませんけれども質問したいと思います。この品川区子ども・子育て計画によりますと、今年の４月に３号認定で０歳の子どもの枠は７９８人となっています。でも、実際に入園した数は８７０人ですね。今年の４月のこの数字、それから、これからの待機児の需要予測、その辺についてどういうふうに考えているのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"０歳から２歳児の申込数ですが、予測としては４％前後増加するのではないかという見込みを立てていたのですけれども、実際のところは２.６％の増ということで、少し増加率としては下がってきているのではないかというふうに考えております。","voiceIndex":66,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"実際は７９８人の枠しかなかった。しかし、８０人ぐらい、これはこの資料の最後のほうに出てきている各保育園の在籍状況のところを見て、定数を大きく超えているところが随分あるのではないかと思っているので、その辺で弾力化で吸収できたという認識でいいのでしょうか。","respondent":"大澤保育支援課長","answer":"０歳児につきましては、７９８人というのは、認可保育園の枠だと思うのですけれども、結局、受入枠というのは、認可だけではなくて、認証も含めて品川区子ども・子育て支援計画を立てることになっておりますので。","voiceIndex":68,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、私は保育園が一番強い要望かと。そのほかにも大規模なマンション、民間の開発があちこちでされるのではないかと思うのですけれども、私が見回してどうなのかと調べた時点で、千五、六百のマンションがかなり増えるということで、そこだけ見ても、来年度は保育園のところでは９０６人という計画なのですが、そして保育園の園数としては１２園ぐらいつくるという予定なのでしょうか。","respondent":"大澤保育支援課長","answer":"今後も認可保育園を中心に進めてまいります。東大井のマンションにつきましては、私どもも３３５戸の予定と聞いておりまして、そちらにつきましては、昨年度の品川区子ども・子育て計画の改訂時にその部分を組み込んだ人数で計画を立てております。","voiceIndex":70,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"ずれ込むということはあり得るのですけれども、少なくとも１２園の開設を進めていただきたいと思います。ですから、その辺について伺いたいのですが、とりわけ心配なところは、五反田保育園の３歳未満の定数が４２人に対して５６人入っています。こういう保育園は、保育士の配置はもちろん基準どおりになっているのだろうかと思うのですけれども、その辺について教えていただきたいと思います。","respondent":"佐藤保育課長","answer":"こちらに関しましては、国が定める部屋の広さと保育士の担当としての人数は間違いなく配置をしています。国のほうも待機児童対策ということで、できる限り定員の弾力化を進めるようにということもありますので、私どもとしては、安全を確認してそのように対応しています。","voiceIndex":72,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"例えば、０歳、１歳、２歳、この３クラス、この２つの園でいいですから、有資格者が何人、正規なのかどうか、その辺の資格も含めて何人配置しているのかを具体的に数字で教えていただきたいと思います。","respondent":"佐藤保育課長","answer":"個別の詳しい内容は、申しわけありませんけれども、担任表を持ってこないとわからないので、各園そのぐらいの人数になっているところです。","voiceIndex":74,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"これ、３対１ですから、少なくとも４人は職員配置されていなければいけないと思うのです。２歳児は６対１ですから、３人プラス１で、４人という配置で、しかも有資格なのか、正規なのか、その辺を具体的に教えていただかないと、先ほど、弾力化で国の指導もしているというふうなことできちんと配置しているということでは、私は了解できませんので、具体的な数字を教えてください。","respondent":"佐藤保育課長","answer":"別途、国の保育士の加算の人数と、都の加算の人数、また区でも独自に加算をしていまして、有資格の非常勤に関しましても１０名程度配置をし、また、シフトの関係で無資格の非常勤に関しても配置をしています。","voiceIndex":76,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"全体的に有資格が１０人とか言われてもわかりません。さっき言ったように、年齢別に正規なのかどうか、それぞれで教えてください。正規でいるとは言っているけれども、有資格の１０人というのがどういう配置になっているのかわからないので、そこについて個別にお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"私が求めているのは、年齢別に、正規なのだということはわかりました。少なくとも０歳、１歳、２歳は全員が正規なのだということはわかったのですけれども、加配分はそのうち何人いるのか、あるいは、有資格者の１０人がクラスにどういうふうに配置されているのか、そこまで答弁を求めたいのです。ですから、ぜひ答弁を、どういう形でだったらしていただけるのでしょうか。そこまで求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"今、資料を持っていなければ、それはしようがないから、どういう形でなら教えていただけますでしょうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"それを約束をしていただきたいのです。私は委員長にお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひよろしくお願いします。数の２２名という数の適正性について、弾力化を国が求めているので、それにこたえているのだということだけでなくて、やっぱり子どもの最善の利益というところで見たときに、本当に２２人という数を、区として、保育課としてどういうふうに認識しているのか、そこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"ですので、五反田保育園の１歳児だけすごく狭い空間で少ない保育士で見ているということではありません。どこの保育園に関しましても大体同じような広さで、待機児童対策としてめいっぱい定員弾力化し対応しています。","voiceIndex":93,"id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、さっきも紹介したように、少人数のグループに分けて保育をしているのだろうというふうに想像するのですけれども、しかし、１クラス２２人という数字を見たときに、私は子どもにとっても大変だし、保育士にとっても、正規で有資格者であったとしても非常に大変ではないかと思うので、最善の利益をきちんと確保していただきたいというふうにあえて強く要望しておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-037"},{"speaker":"こんの委員","kind":"質問","question":"同じように、五反田も空いているけれども０歳児の待機児が出ているというのは、利用者が望む園がなかったというマッチングの問題なのかと想像するのですけれども、まずそこをお聞きしたいと思います。","respondent":"大澤保育支援課長","answer":"これは、そのご家庭のお考えで、認証が空いていてもやはり認可にこだわりがあるとか、そういうことなのだと思います。","voiceIndex":96,"id":"exchange-038"},{"speaker":"こんの委員","kind":"意見","question":"あくまでもご家庭のご希望なので、では、仕方ないですね、認可しか選ばれないのであれば仕方ないですねというふうにしてしまうのか、その辺のやりとりは、窓口あるいは申し込まれたときのやりとりはどのようにされていますか。","respondent":"佐藤保育課長","answer":"そちらに関しましては、各職員、世帯状況を見まして、勤務先であったり、最寄りの駅であったり、もしくは昨年度の先ほど説明いたしました指数の低いところの傾向とかもきめ細かく周知いたしまして、その方ができるだけ認可保育園に入れるように対応しています。","voiceIndex":98,"id":"exchange-039"},{"speaker":"こんの委員","kind":"質問","question":"あくまでもご希望で、通える範囲でしょうか、大体選んでいらっしゃる方は希望園として、第１希望から第３希望までの３園が多く、第８まで希望されているというよりは、この不承諾数の中には、希望園を３園ぐらいまでしか書かれていないという方もいらっしゃる。やっぱり近いところが多いのか、それとも範囲を広げて選ばれることが多いのか、その辺の傾向はどうでしょうか。","respondent":"佐藤保育課長","answer":"その辺を考慮して、窓口で実際に行ける範囲の園を書いてくださいと言っていることも事実ですが、私どものほうで強く縛ったりはしませんけれども、窓口のほうで適切にさまざまなアドバイスをして対応しています。","voiceIndex":100,"id":"exchange-040"},{"speaker":"こんの委員","kind":"質問","question":"なぜこういうふうな質問をしたかというと、結局、空いている園があって、一方で入れない方がいるというここが、これからも増やしていくのですけれども、増えたところには園児数がいなく、増やせなかったところに、いわゆる再開発等で人口が増えていく、なかなかうまく子どもが増える場所に園を増やすということがなかなか難しいではないですか。","respondent":"大澤保育支援課長","answer":"通える範囲というのも、例えば、今、国のほうだと３０分未満を通える範囲というふうに決めていますけれども、それは個々の状況で、いや、１５分でも無理ですという方もいれば、実際にあったのですけれども。","voiceIndex":102,"id":"exchange-041"},{"speaker":"こんの委員","kind":"質問","question":"おっしゃることはよくわかります。自転車に乗れない場合もある。だけれども、空いている園があって、何かの手立てがあればそこに通園してもいいという、あるいは、それをそのままにしておいて、一方でどんどんつくっていくというよりは、空いているところを何とか活用しながら保育需要にこたえていくという考え方は、今後必要ではないかと思いますけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"どこまで認可保育園に入りたいご希望が強いかというのは、やっぱり人によって違うのですけれども、どうしても入れなければ困るという方については、どうにかして入れるような方策は必要だというふうには考えています。","voiceIndex":104,"id":"exchange-042"},{"speaker":"こんの委員","kind":"確認","question":"調整指数の５番です。それから、やっぱりばらばらにそれぞれのお子さんを通園させるのは、親の負担はかなりありますので、できるだけこういう負担をなくすように、これだけの園ができていますので、ばらばらになるような状況はなるべくつくらないようにすることが必要かと思いますけれども、５番、６番の指数のあり方みたいなものはどのようにお考えでしょうか。","respondent":"佐藤保育課長","answer":"１２番の夜間保育に関する調整指数ですが、こちらに関しましては、「平成３０年４月入園選考から廃止する」ということで、委員のほうからも若干ご指摘いただきましたけれども、ここまで加点をしなくても、基本的にどこの保育園も、私立も含めて、夜遅いといいますか。","voiceIndex":106,"id":"exchange-043"},{"speaker":"こんの委員","kind":"質問","question":"というのは、これだけ園をつくっていただいて、空きも出てきている状況の中で、少しそうしたことも加味し、できるだけ一緒の園で、できるだけ希望にかなう園でというところをここは調整指数というところで考えていく必要があるのではと思うのですけれども、いかがでしょうか。","respondent":"佐藤保育課長","answer":"ただ、委員ご指摘の点も理解できますし、国からも一定そういった形で通知も来ていますので、今後さまざまな検討をして、保護者の方に提言できるようにしていきたいと思います。","voiceIndex":108,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"確認","question":"ひろまち保育園は平成２８年４月から５年ということですから平成３２年まで、ひがしやつやま保育園は１年ずれているから平成３３年までということなので、今年入られた方が数年後には移らなければいけない状況になるわけですが、その辺は昨年度からやられていると思いますけれども、入園される方への確認の徹底と、逆に、５年という当初の予定でしたけれども、５年ではなく。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"初めに、１歳児の定期利用ですけれども、こちらは１４園で実施しまして、３８人の受け入れを４月１日でしております。ひろまち保育園、ひがしやつやま保育園ですけれども、原則は５年の入園期間と考えておりまして、期間満了後はその後の転園先を確保するという形で検討しています。","voiceIndex":111,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、まず１歳児のほうは、３８人を受け入れていただいた。これは要望です。もう１つは、後半の部分が質問のところだったのですけれども、やはりもう現時点では５年ということを動かさないというような状況か、それとも、先ほど、１０年は人口がある程度増えていくという状況の中で、その先のことについても検討されているのかどうかという点をお尋ねします。","respondent":"吉田保育施設調整担当課長","answer":"ひろまち保育園の件ですけれども、現状の場所での稼働期間を５年と考えておりまして、その後は、在園児については、どちらかへの転園等につきまして検討しています。","voiceIndex":114,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"わかりました。今後のことですので、難しいところがあると思いますが、現状では、転園等についてのお話をきちんとして、５年で閉じた場合はそういった細かい配慮をしながら転園先を見つけていただくということをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-047"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"２番目のはぐはぐキッズ中延の設置者ですが、プリメックスキッズ株式会社ということで、これは区内では初めて開設されるのか、そこのところを確認させていただきたいと思います。あわせて、会社の離職率や、人件費率などがわかれば伺いたいと思います。","respondent":"大澤保育支援課長","answer":"２３区のほかの区において、認可保育園の運営を既にやっております。プリメックスキッズにつきましては、離職率が１２％、人件費率が５１％というふうに聞いております。","voiceIndex":121,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問","question":"小規模では区内でやっているということですね。あわせて、各園に園庭があるのかどうか伺いたいと思います。ない場合、代替園庭はどこになるのかということもご答弁いただければと思います。やはり最近、認可保育園が増えておりますので、公園が保育園の子どもたちでいっぱいになっていることが多々ありますので、そういった点も含めて、区のお考えはどうなのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"次に園庭です。１番のチャイルドマインダー小山台東につきましては、水遊びスペースの設置を調整しています。２番のはぐはぐキッズにつきましては、園庭はございません。３番、空のはねこども園はたのだいにつきましては、屋上園庭があります。","voiceIndex":123,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"公園のところでは、今、やはり保育園が増えている中で、公園に子どもたちがあふれかえっているというところを区としてはどうされるのか、いろいろ園同士でうまく調整をしてもらうということもあるとは思うのですけれども、やはり区として抜本的な対策が必要なのではないかと思うのですけれども、そういったことを考えていらっしゃるのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"公園が増えればそれに越したことはないのですけれども、なかなかそれは難しい問題がありますので、できるだけ既存の施設を活用することを考えておりまして、例えば、公立保育園の園庭ですとか、今、学校の校庭等を日常的に保育園でお借りしているケースも増えておりまして。","voiceIndex":125,"id":"exchange-050"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお聞きしたいのですけれども、来年度開設のご報告をいただいて、先ほどの待機児の話と関連するのですけれども、いわゆる東大井方面の開設の見通しは今後どうなのでしょうかというところを１点お聞きしたいと思います。","respondent":"大澤保育支援課長","answer":"東大井地区につきましては、今日、まだご報告をできる段階ではないのですが、今、２園調整してございまして、おそらくこのままうまく開設までこぎつけるであろうとめどが立っておりますので、実現するように調整してまいります。","voiceIndex":127,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"新しく開設園５園の紹介だけだったのですけれども、以前、荏原医師会の隣の土地にできると報告いただいた園が、今回出てこないのは何かまだ出せない事情があるのかどうか、その辺を教えていただきたいのが１つです。屋上園庭を園庭とカウントしないで、保育者の目が届く場所、そういう位置にある園庭がある保育園はどこか、何カ所か、それを伺いたい。","respondent":"大澤保育支援課長","answer":"園庭につきましては、今、資料を手元に持ってきていないので、正確な数値がわかりかねます。","voiceIndex":129,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"さっきの保育園の職員のことと同じでいいのですけれども、あとで教えていただきたいとお願いをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"３番目の旗の台の保育園ですけれども、幼児教育部門があるということなのですが、募集のときの人数、保育園として募集するのは、資料にあるとおり３歳が１４人、４歳が１４人、５歳が１４人となるのでしょうか。幼児教育部門の意味もお尋ねします。","respondent":"大澤保育支援課長","answer":"空のはねこども園はたのだいですけれども、保育認定をとって区で利用調整をして利用される方が７３名で、そのほかに就労とかの要件ではなく、保育認定をとらずに、園と直接入園のお約束をして利用される方が、３歳児、４歳児、５歳児の合計で３名ということになります。","voiceIndex":133,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、区の保育認定のルートとは違ったルートになるということですね。保育園そのものとやるということ。そうすると、保育園という扱いでよろしいのですか。それとも、もちろんこれは株式会社だから幼稚園ではないと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"私、３０年前に保育園にいたときは、園庭は本当に猫のひたいほどだったのですけれども、それでも少しはあり、６００m2前後の敷地面積だったと思うのです。必要であれば園庭確保分の補助金を出すことも含めて、本当に前向きに園庭確保に取り組むべきだと思うのですけれども、その辺の認識はどうでしょうか。","respondent":"大澤保育支援課長","answer":"園庭につきまして、もちろんお子さんのためにはあったほうがいいとは思いますけれども、それだけの土地を獲保できるかというと、なかなか難しくて、どうしても既存施設のフロアを使ったりという保育園もありますので。","voiceIndex":139,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"開設時期が延びた不動前えほん保育園の理由が、先ほど、工事と保育士の確保というお話があったのですけれども、これまで区の答弁だと、品川区は保育士の確保をしやすいというお話だったと思うのですが、今回、できなかった理由と、それとあわせて区がどういった支援をやってきたのかということを伺いたいと思います。","respondent":"大澤保育支援課長","answer":"不動前えほん保育園ですけれども、こちらは新築ではなくて、既存施設の改修を行い認可保育園にするものですので、本来ですと内装工事のみの予定でございまして、早い時期に開設できるという見込みだったのですが、保育施設の避難口が当該建物の駐車場に面しているために。","voiceIndex":142,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、直接的には保育士の確保が要因で時期がずれたということではないと。どちらかといえば、４月開園のほうが確保がしやすいということで延期となったということで、区の保育士確保のしやすさに変わりはないということでよろしいでしょうか。","respondent":"大澤保育支援課長","answer":"平成３０年４月に１６園開設いたしましたけれども、保育士につきましては全園できちんとそろいましたので、特に保育士確保が理由で９月に開設できないということではなくて、ベストの時期を事業者が判断してございましたので、平成３１年４月にさせていただいたです。","voiceIndex":144,"id":"exchange-058"},{"speaker":"南委員","kind":"質問","question":"簡単に。今の説明だと、席に余裕があるので当日来てもいいとおっしゃってくださったのですけれども、私も行きたいと思いますので、このチラシに書いて申し込みをした方がいいのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"お書きいただかなくても、できれば電話を１本はいただければと思います。当日でも結構ですが、前のほうのお席は事前にお申し込みがないと空いていない可能性があるということだけです。","voiceIndex":150,"id":"exchange-059"},{"speaker":"つる委員長","kind":"質問","question":"続きまして、私からご挨拶申し上げます。１年間、この委員の皆さん、また理事者、そして書記のお二人のもとで、今、副委員長からもありましたけれども、実りある委員会、質疑ができたかと実感しております。各委員、また理事者、書記の皆さん、本当に１年間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":42797,"voices":161}},{"id":"h30-20180514-5","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"総務委員会","time":"午後 １時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度区政モニターの委嘱","agenda":"平成３０年度区政モニターの委嘱","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"特に１８歳で選挙権を持つことになった、この年齢の問題とか、あと、先日区議会で議会報告会があったのですが、若い方が参加されていたので、聞いてみたら、たまたま今日、僕は年休なので、あいていたので、どんなことがされているのか来てみましたとおっしゃった方が、帰り際に、土曜日とか日曜日とか夜間とか、働いている人も出られるような体制にしていただけたら助かります、ということを。","respondent":"中元広報広聴課長","answer":"ただ、集会を行っている中で、皆さん意見交換などをされて、それはそれで効果的な部分もあるのですが、やはり若い方の部分について、申し込み方法については電子申請等も入れておりますが、そこは課題と感じておりますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"若い方たちの発想もいろいろ受けとめる機会が大事だと思いますので、よろしくお願いします。説明の中で、地区推薦の方の枠は、実際に年代別・職業別のところでどこに入っているのか、その辺の区別はつくのでしょうか。そこを教えてください。","respondent":"中元広報広聴課長","answer":"町会推薦で応募していただいて委嘱した方というのは、町会推薦で更新をされた方が既に８人いらっしゃいます。新規で町会推薦で入って来られたのが１３人、全体の中で５０人のうち２１人が地域からの推薦をいただいた方ということになっております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、町会推薦の方と言ったら、やはり年齢的には高い方が多いということですかね。","respondent":"中元広報広聴課長","answer":"委員おっしゃるとおり、やはり町会で活動されている方ですと、どうしても５０代、６０代の方も、お二人いらっしゃるとやはり６０代以上の方が多くなっております。","voiceIndex":11,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"来てはいけないということではないのですけれども、なぜ来てくださったのかなということで伺ったら、議会で何をやっているのか、ふだん知る機会がないので、いい機会だからということで、お嬢さんのほうがお母さんに一緒に来てもらったという形だと思うのです。もし何かお考えがあったら教えていただきたいと思います。","respondent":"中元広報広聴課長","answer":"ですので、そういうところにつきましは、いろいろ連携、所管課とも相談しながら今後検討していきたいと考えています。","voiceIndex":13,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区としてはぜひ品川区の区政に参加していただきたいという視点が大事だと思うのですけれども、やはり政治参加を促すということであれば、どこの区であっても、何も品川区に限るという考え方ではなくても可能なのではないかなと思います。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"若い方という話だったと思うのですが、まず、どのように募集をかけているのか教えていただきたいのと、年齢別の表を見て、区としてはどう現状を考えているのかというのを、まず教えてください。","respondent":"中元広報広聴課長","answer":"こちらの年齢別の表ですが、やはり２０代から４０代の方の人数が少ないというところは課題として捉えておりまして、どうしても平日の午前や午後に開催しておりますので、なかなか参加が難しいのかというのは、課題として考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"夜間開催も、そういった工夫もしていると言うけれども、結局そこがあるから若い人は、若い人と言うか、いわゆる働いている世代にはなかなかハードルが高くて参加がしにくい状況だと思うので、ここはやはり時間帯もそうですし、仮にどうしてもその時間帯しかできないというのであれば、例えば中小企業との連携などで、休暇と言うか、こういった区の会議に参加する場合には、会社にもお願いをして。","respondent":"中元広報広聴課長","answer":"企業との連携の仕組みを、少し調べてみたのですけれども、やはりなかなか、委員おっしゃるように個々に独自でアプローチをしてお願い、ご相談をしてということはできるかもしれないのですが、法律上なかなか休暇などは各企業の判断になってくるので。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆるＣＳＲもやっていて、各企業ともいろいろ連携をしていこうというふうに区は発信をしていて、実際に具体的に幾つかそういった取り組みというのを各企業とも行われているわけではないですか。例えば今、五反田には若くて有能な、いわゆるベンチャー企業の社長さんたちも多く会社を構えている中で、では例えばそういう方にアプローチをするとか。ぜひ、進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"であればそこに、少し重くなるけれども、そのアンケートを、絞ってもいいですから、同封して送って返信用の、はがきでできるのかどうかわかりませんけれども、そのときに一緒に返信いただければありがたいということで、多くの方に回答をいただける、お考えをお聞かせ願うという工夫も、私はそろそろ、今の時期ではそういうふうにやっていかなければいけないかと思うのですね。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"}]},{"id":"topic-02","title":"平成３０年度わ！しながわ魅力発信事業について","agenda":"平成３０年度わ！しながわ魅力発信事業について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"目的が、「区民とともに進めるシティプロモーションの一環として、品川区の魅力を区内外に発信する区民・団体等の取り組みを支援する」、区と一体になって品川区の魅力を発信していただく、それに支援をするということで、平成２７年から４年目で、今回は助成金がないというところが、まず第一になぜなのかと思ったのと、いまひとつ支援内容がわからないのですが、ロゴマークを使ってもいいよとか。","respondent":"木村報道・プロモーション担当課長","answer":"実際に、ある程度の実績と言いますか、この３年でキックオフというイメージで、まず事業を立ち上げて行っていただくという意味合いのような部分である程度実績が見られたということと、観光や協働の事業のほうでの補助事業でありますとか。","voiceIndex":26,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まだわからないのですが。あまりイメージが湧かないのですが、そこのところを教えていただきたいのと、５の(3)のところで、「区で審査を行った上、参加決定通知書の発送をもって開始とする」と書いてあるのですけれども、この区の審査というのはどなたがされるのか、メンバー、基準があるのかどうか、どういう基準で選定をするのか、その辺も教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"審査に関しましては、基本的に考えているのは区の内部で、実際の基準といたしましては３の対象事業にそぐうものであるかどうか、こちらを判断いたしまして決定したいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、区民の方々から品川区の魅力を発信したいという参加の申し込みがあって、作品ができるのかよくわからないのですが、それに対して区で要件にかなったという判断をされたのであれば、そこからいろいろ発信をしていくところをお手伝いしていくということなのですね。済みません。これにかかる予算というのは具体的に、助成はしなくても予算はどれくらいかかるのでしょうか。教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"これに関しての、いわゆる事業予算的なものとしてはとってはおりません。人件費だけです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"割とこの魅力発信事業、いろいろ苦心しながら、きちんと発信につながるようにということで、毎年変えてきたという印象があるのですけれども、結局、もうある程度そういう発信をしていく事業は、採算などは自分たちの活動の中でしてくださいということで、もう一定そういう見込みが立って、今までの経緯からこういうふうになったのかなと思うのですが、その辺のこれまでの評価と。","respondent":"木村報道・プロモーション担当課長","answer":"こちらに関しましては、当初からですけれども、基本的には助成は初年度、あとは継続されるところで、その間に採算をとるような形を、いわゆる申請される方もそういう頭で来られているところでして。","voiceIndex":32,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"それは方向としてはいいかなと思うのですけれども、一方で、継続の方たちはそれでいいのですけれども、今までにない発想で新規でこういう魅力発信事業をしていきたいという方たちがあらわれたときには、その辺についてはどのようにお考えか教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"全く今まで考えもしなかった新たな取り組みという部分も、実際には今まで助成した中でも出てきているところでして、そういう意味では、そこで実際に見まして、これはおもしろいね、これはやってみようかというあたりで、可能性に賭けてみるという部分も正直ありますので。","voiceIndex":34,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"そういうところであっても、基本的には事業についてはもう自分たちで採算をとっていく。ですから、そういう意味で広報にこういういろいろな媒体が使えるということについては一つ確かに支援になると思うのですけれども、基本は事業については参加費なり何なりで自分たちで採算をとっていくということが今後前提になっていくという理解でよろしいですか。","respondent":"木村報道・プロモーション担当課長","answer":"そのご認識でよろしいかと思います。","voiceIndex":36,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問","question":"今、さまざま区民１人１人がいろいろな形で発信をされていると思うのですね。例えば自分の生活の一部、例えばこんなものがありますよとＳＮＳにアップしたり、いろいろ発信方法があります。例えば、公園などで撮影をする場合は許可をとってらっしゃいますよね。映画の撮影やドラマの撮影で、写真集などの撮影も確か、登録か何かをしますよね。区としてその辺の認識というのはどうなのでしょうか。","respondent":"中元広報広聴課長","answer":"今後とも、その辺のところは内部でも調整しながら、個人の部分の基準をまだあまり詰めておりませんでしたので、その検討・調整をさせていただきたいと思います。","voiceIndex":38,"id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問","question":"今、いろいろなものがあって、なかなか区民も判断できなくて困っている場合もあるのかなと思うので、その辺をあらためて、例えばその例であればどうなるのかというのを教えてください。","respondent":"中元広報広聴課長","answer":"とりあえず区の施設であれば、まずはフィルムコミッション担当の窓口もありますので、そちらか、もちろん広報、シティプロモーション担当のほうでも結構ですので、区の魅力発信に寄与するものを行うのだよということであれば。","voiceIndex":40,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、このわ！しながわ魅力発信事業、今年で４年目に入るのですが、この事業の成果は何を基準にして、またどのような数字をもって成果が出たとか出ないとか、もっとやらなければいけないのだとか、何をもって判断するのか、ご見解をお聞かせください。","respondent":"木村報道・プロモーション担当課長","answer":"こちらに関しましては、なかなかそれを受け取って何かのアクションにつながったというところを把握するのは、正直難しいところがありますけれども、どれだけ発信したものを見ていただいたかという統計はとれるのですね。","voiceIndex":42,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回事業もいろいろ変わってはきましたけれども、あくまでコマーシャル、皆さんに見てもらう、聞いてもらうということなのでしょうけれども、その成果などをやはり、こういう事業を行っている以上は、何かこれで結果が出たのですよということは、やはり報告はしなければいけないし、また難しい問題ではないですか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。平成３０年度シティプロモーション推進の資料の中で、業務推進、６月から、わ！しながわのキャンディーでしたか、あれはすごく人気があると伺ったことがあるのですが、今年度もそれも含めてどのように行っていくのかお知らせいただきたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"その他の部分についても、これからまた検討してまいります。","voiceIndex":45,"id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、品川区の魅力を発信ということで行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"しながわというロゴをつくって、不動麗子さんの動画であるとか、さまざまな幾つかの試行錯誤、そういう言い方をしていいのかどうかわかりませんけれども、いろいろなものを試されてきて、今年度は区民に焦点を、当初から区民に焦点は当てていると思うのですけれども、特に区民にというところになると思うのですが、そこのＷＥＢマガジンというところについて、この地域プレーヤー。","respondent":"木村報道・プロモーション担当課長","answer":"基本的には、その方は今までずっと活動されてきた方ということなので、その方をキーにして、考えているのはその次世代と言うのですか、今、若い方が直接そういうまちづくりにかかわってらっしゃるとか。","voiceIndex":48,"id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問","question":"そのアイデアはいいのかなとは思うのですけれども、例えば区外の方がそれを見たときに、品川区が魅力あるなと思うコンテンツになるのかどうかというところで、それは捉え方次第だと思うのですけれども、品川区は元気のいい若手の方がいるんだなとか、こういうところだったら住んでみたいと思えるものが、果たしてつくれるのかどうかというところでの、もう一言、意気込みを伺いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"一番伝えたいところは人の魅力と言うのですか、その人そのものの発するパワーであるとか、魅力があれば、周囲を巻き込んで何かをやっていく上で、その町が、行ってみれば楽しそうだななどというところを感じていただくというところが一番ポイントかと考えていますので、ぜひ。","voiceIndex":50,"id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"意見","question":"今までもそういう番組をケーブルテレビで、品川区はいいところだなと、ああ、こんな人がいるんだということで、私も拝見したことが何度もあるのですけれども、今度は区外の人が見ても、ああ、品川区はすごいなと思っていただけるような、そういう番組づくり、１つでも２つでも、口で言うのは簡単なのですけれども、大変なことだと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-024"}]},{"id":"topic-03","title":"男女共同参画のための品川区行動計画 第５次等の策定について","agenda":"男女共同参画のための品川区行動計画 第５次等の策定について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"少しずつでも前進しているなという面で応援をしていきたいと思っているのですけれども、内容的に、これからこの基礎資料、アンケートをとった基礎資料を中心に計画策定検討委員会の中でもんでつくっていくというところにおいて、意見を幾つか言いたいと思っているのですが、１つ、学識経験者、先ほど立正大学の川眞田先生が委員長ということだったのですが、この辺の学識経験者の選び方。","respondent":"島袋人権啓発課長","answer":"その後の委員に関する募集ですが、品川の広報３月１日号、こちらにマイセルフ品川プラン策定検討委員会区民委員募集の案内を出しまして、申請書のほうはホームページからもダウンロードできるという形で募集をさせていただきました。","voiceIndex":57,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"そういった中で、品川のこの計画が品川区民の男女の差別や格差をどう改善していくのかというすごく重要な意味を持っているので、重点的な取り組みとここに書いてありますけれども、やはり国から来る大きな問題をどの程度品川区がその辺を改善していかれるのかという、その辺のところ、大もとのところを一つお伺いしたいと思うのですが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"新たにこの女性活躍推進法は、働く職場における女性ということをうたっている部分が多いのですけれども、よくよく読んでみますと、地域における女性の活躍という部分もございまして、この中には、例えば防災関係で、避難所生活における女性支援。","voiceIndex":59,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"セクシュアルマイノリティのところは、この間、かなり自治体でも進んでいますし、先日、東京都においても差別のところですか、ＬＧＢＴ差別禁止へヘイト抑止ということで、条例案提出へということで、これは差別に対しての取り組みで条例ができるということと、あとは同性者のパートナーシップの問題も、この間、渋谷、世田谷、中野など、具体的に進んでいるのですが。","respondent":"島袋人権啓発課長","answer":"その中からまたお声をいただきながら、どういったものが区として進めなければいけないところがあるのかを研究しながら進めてまいりたいと考えています。","voiceIndex":61,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当にここの中身で、マイノリティへの考えで、実際的に公平に接することはできないと回答した人が女性で９.９％いますとか、２２.３％男性がいますというあたりも、本当に率直なデータになると思うので、こういうところからも本当に具体策がいろいろ考えられるなと思っているので、ぜひこのアンケートを活用して、施策に生かしていただきたいと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"先ほど、答弁もれがございました各区との連携、あるいは都の条例の件に関しましては、やはり動きを注視しつつ、区としても対応が可能なものに関しましては実施していく形になるかとは思っておりますし、策定委員会の中でもそのように進めていくというふうな予定でおります。","voiceIndex":63,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"確認になるのですけれども、６月にこのアンケートの冊子がまとまるということで、ぜひ生かしていただきたいというふうに今、飯沼委員もおっしゃいましたけれども、当然、この策定委員会の第１回の委員会での議論の中で、このアンケートの内容というのは、それを前提としたものになるというふうに理解してよろしいでしょうか。その辺の確認させていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"委員のおっしゃるとおりで、そのようにさせていただきたいと思います。報告書の概要版に関しましては、ホームページ上でもでき上がり次第アップを予定しているところです。","voiceIndex":66,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"この割合で言えば当然そういうことは想定すべきで、そういった方たちに何か、そういう方たちへの配慮というのも、区役所も事業所の１つとして、今後計画ができた後になるかもしれませんけれども、アンケートをとった当事者として、民間の事業所とか、そういった区民に先駆けて工夫をしていっていただきたいと思うのですけれども、その辺についてのお考えがあれば教えてください。","respondent":"島袋人権啓発課長","answer":"概要版の７ページの性的マイノリティの設問の件ですが、下のところに説明書きを書かせていただきまして、その件に関してのアンケートでしたので、今回はこのような形をとらせていただいております。","voiceIndex":68,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、その辺の配慮を進めていただきたいと思います。ですから、進んでいるようなところでも、当事者の人たちにしてみたら、なかなかやはり今の社会状況では難しいのかなと思います。ぜひ、基本、そういうふうに悩んでいる方がいらっしゃるのではないかということを前提に、区内でもそういう施策を進めていただきたいと思いますので、その辺は要望でとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-031"},{"speaker":"須貝委員","kind":"意見","question":"このたびの区民意識・事業所状況調査、済みません、詳しくは全部見られなかったのですが、特に事業所状況調査は、本当に企業によって意識の格差が相当出ていると、そういうこともこういうふうに差としてはっきり見られるということは、すごくいい資料ではないかと思います。いろいろ漏れているところもあるかと思いますけれども、よく行われたのではないかなというふうに思いました。以上、感想だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-032"}]},{"id":"topic-04","title":"総合庁舎エレベーター改修工事請負契約について","agenda":"総合庁舎エレベーター改修工事請負契約について","exchanges":[{"speaker":"飯沼委員","kind":"確認","question":"契約方法のところなのですが、理由として、再利用するものは利用してということで、日立ビルシステムにということで、業者推薦随意契約というのはそういうものなのですか。初めてこういう言葉に出会ったので。こういうことは、今のエレベーターは５基とも日立製で、そこの関係で行っていくということでいいのか、確認させてください。","respondent":"立木経理課長","answer":"エレベーターのほうですが、５基とも日立ビルシステム製のものでして、全て撤去して新しいものをということであれば競争入札という形になりますが、できる限り、先ほど申し上げました理由のとおりでございまして、短工期、それから低予算という形で再利用していくという形では。","voiceIndex":76,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"国が定める仕様に適合していなかったということなので、日立のどこの製品がどうなのかというのはわからないのですけれども、ニュースでそういうふうに載っていて、日立グループとしては事態を重く受けとめ、再発防止に向け取り組んでいきたいとコメントを寄せていますという記事が、たまたまインターネットを調べていたら日立というので出てきたのですが、このことと今回の工事の関係があるのかないのか。","respondent":"立木経理課長、小林施設整備課長","answer":"日立製に限らず、ときどきそういったことで不適合という報道が出ることがありますが、今回、工事をするに当たりましては、きちんとそういったものが正しく適用されるような工事管理、そういった契約もしますので。私のほうから少し補足なのですが、今、委員がおっしゃった１２月の報告というものにつきましては、品川区の中ではそういうエレベーター、該当しているものはございません。","voiceIndex":78,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"わかりました。大丈夫ということなので、きちんと行っていただきたいと思います。裏面の工事内容のところで、制御盤等は更新するけれども、今までの使える部分は使っていくというあたりなのですけれども、これは全体をとりかえた場合と今回の工事との費用のかかり具合は試算をされているのか、その辺を教えていただきたいと思います。","respondent":"立木経理課長","answer":"今回のものが、できるだけ再利用で、今回はほぼ再利用で、部品供給が停止になってしまった巻き上げ機というものが主な更新なのですが、こちらが今回の１億５,０００万円ということになっております。","voiceIndex":81,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"今回、このように改修工事をすると、今後どのぐらい耐用年数、もつのか教えてください。以上で終わります。","respondent":"立木経理課長","answer":"今回は製造中止以降、２０年以上経過したもので部品供給がとまるという形になりますので、適切なメンテナンスさえ行っていれば、その程度、今回更新があった程度、大体２０年から３０年ぐらいの間になると思いますが、それぐらいは耐久性というのはあると考えております。","voiceIndex":83,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"こうして契約を結ぶに当たって、契約書に書く内容であるとか、こういった中身でという契約書を交わされるのかどうか。その契約書にどのようなことを書いて仕事を依頼するのかどうか、その辺を教えてください。","respondent":"島袋人権啓発課長","answer":"テーマといたしましては、人権・平和に関する憲法１１条の基本的人権のこと、あるいは１４条の法の下の平等など、差別されない権利や、人間らしく生きる権利についてということをもとに構想をしているところです。","voiceIndex":89,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30280,"voices":93}},{"id":"h30-20180516-14","meetingId":"h30-cm05","date":"2018年5月16日","dateIso":"2018-05-16","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時２１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年陳情第７号、羽田新ルート計画","agenda":"平成３０年陳情第７号、羽田新ルート計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここをちょっと具体的に伺いたいのですけれども、環境影響等のできる限りの軽減というのはどういうことなのか。そして、安全対策、これは何を求めたのか、地元への丁寧な説明、これはこの間区も求めていると思うのですけれども、住民の皆さんは教室型説明会を求めていますけれども、そういうことも求められたのか。そして、地元へのメリットの創出、これも具体的に何なのかを教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"今ご質問いただきましたそれぞれについてですが、当日この一つ一つの内容について具体的に、例えば住民への丁寧な説明、これはどういったことかというような具体的な申し入れはしてございませんが、例えば環境影響等のできる限りの軽減につきましては、一つは。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、すごく雑駁にといいますか、求めて要望されたということなのでしょうか。そういったもうちょっと具体的な中身があったのか、全くなかったのか、本当に区の記録がないわけですから、そして全容を区民に明らかにしてほしいという陳情ですので、ぜひもし具体的にもっとあるのであれば答えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"記録資料にありますように、トータルのやりとりが１５分程度という中で、非常に短い中でのやりとりです。例えば、今委員からお話がありましたが、地元へのメリットの創出を何か区のほうから具体的にこうしてほしい、ああしてほしいということを申し出たことは一切ございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、これを出したことで品川区への配慮事項が出たのだということで、当時課長がおっしゃっていたのですけれども、ではこの４月１８日に要望したことの成果が品川区への配慮事項だというふうに受けとめているのでしょうか。","respondent":"鈴木都市計画課長","answer":"さらにさまざまな対応を今後も求めていくという受けとめ方です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのために、何をどう区が区民の代表として求めているのかが全くわからないのです。国の政策、国策ですね、これが品川区民の暮らしに大きな影響を及ぼす、それに対して区長が要望を伝えに行ったわけです。それなのに、何も残さずに区が求めた、そしてこれで終わりではない、そうしたことも今後記録なり区の方針として残していくという考えはないということなのでしょうか。","respondent":"鈴木都市計画課長","answer":"今回に当てはめるとどうだですが、内容的には何か区の政策をしっかり求めるとか、区の態度を表明するとか、そういった形ではございませんで、まず環境影響への配慮、区民の方が一番心配している落下物対策、丁寧な説明、これをしっかりその場で求めるということでございまして。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区民が一番心配していることについて、区長が要望しているわけですから、その中身は何なのか、何を区長は区民のために言ってくれたのかと区民が思うのは当然のことだと思うのですね。部長にそういう権限があるのでしょうか。しかも、区のトップの区長が国土交通省に出向いて要望しているわけですよね。このレベルのものの記録は必要ないということなのでしょうか。もう一度お願いします。","respondent":"鈴木都市計画課長","answer":"ただ、今回の羽田の件に関して国に出向いて伝えた内容が軽いことかということを申しているわけではなくて、伝えるべきことが明確で、その伝えるべきことが非常に重要なことであって、それが正確に伝わったと、もし仮に議事録をとるとすれば、今私が申し上げた環境影響への配慮。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"どうしても記録があると言えない、区民に公表できないものがあるのではないかなと疑わざるを得ないのです。区としてはどうお考えなのか。それと、やはりこの重大な問題をほかの会派の皆さんはどうお考えなのかというのを委員会ですので、ぜひ意見をお聞きしたいなと思います。自民党、公明党、民進党の、この記録のないことについてのご意見等々を伺えたらなと思うのですが、お願いします。","respondent":"鈴木都市計画課長","answer":"資料として持たなくても、これは区として再三再四お伝えしている内容ですので、その場で口頭でお伝えをして、仮にその場で国の方が、いやいやそれはこれで対応は十分なのですよとか、これ以上やる必要がないですよとか、そういうお話があれば。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどから質疑を伺っていて、まさに公文書のあり方のことを質問されていらっしゃるのだと思います。後ほどちょっとこの内容についても質問したいのですけれども、そういうお時間はとっていただけるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"かなり長い今質疑をされていらっしゃいますけれども、私どもも質問させていただきたいのですけれども、よろしいでしょか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回のこの件も、２年間にわたって明かされてこなかったわけです。区長が国土交通省に出向いて、そしてこの内容、昨年の１１月のタウンミーティングで初めて明かされたわけで、本当に重大な問題だと私は思っていますので、ぜひ皆さんにもその認識を持っていただきたいなと思って伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この不動産価値の低下、私も第４フェーズの説明会に行きましたけれども、これが実際に、私はないとは言いません、ないと言っているわけではないのですけれども、ただ実際にこういうことが起きているのかどうか、不安の声に答えるという意味でも、たしか国土交通省の説明だと因果関係がないとか、そういうちょっと、はっきり言えば余り丁寧ではない説明だったのですが、ここについて区としてどういう。","respondent":"鈴木都市計画課長","answer":"不動産価値の下落につながるのではないかというところで、国の考え方の一端をご紹介いただいたようなところがございましたが、国の考え方とすれば、不動産価値、これは一般的にはさまざまな要因によって決定されるものだというところと、あと具体的には伊丹。","voiceIndex":27,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"確認","question":"一応私が調べたところによると、その不動産会社の方は、アメリカの米国連邦航空局というところの報告書を根拠として、その報告書自体もあくまでケーススタディーであって、これによって不動産価格の下落を立証することはできないと結論づけている報告書なのですが、その報告書の計算式をもとに、しかもその計算方法は、それにのっとっていない、１日の平均ではない、まさに最高点の騒音のところをもとにした。","respondent":"鈴木都市計画課長","answer":"しかしながら、国のほうは公の資料として、検証した内容はこうで、おかしい点があるよというところは示していますので、それを広く区民の方に知っていただく、あるいは区内の不動産関係の方にご説明していただくと、そういうことは申し入れとして必要ですし。","voiceIndex":29,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"意見","question":"先ほど申し上げたとおり、今回の問題が不安をあおっているという部分もあると思うのです。不安をあおられてしまう部分もあると思うのですが、不安を少しでも、もしこれが誤解とか、もしくは意図的に誤ったことを伝えている、そういうことであるならば、これは区民の不安を少しでも軽減する必要があると思いますので、ぜひそういったことはお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、ちょっと内容なのですけれども、陳情の項目で、やりとりの全容を区民に詳しく報告してくださいとありますけれども、やはりこれだけ重要な問題でのトップ会談ということになりますので、全容というのをつぶさに報告するのは当然だなというか、そういうふうに区民の方が求めるのも当たり前だなと思うのですけれども、区としてはこのやりとりの内容を区民に報告するという考えがあるのかどうか。","respondent":"鈴木都市計画課長","answer":"区長ということで、副区長を含めてですけれども、この２回以外に国土交通省に出向いたということはございません。","voiceIndex":32,"id":"exchange-013"},{"speaker":"安藤委員","kind":"確認","question":"それと、この４月１８日、５月１７日以外に区として公にといいますか、区として国土交通省に出向いたことはないということでしたので、これは、ではこの２回のみなのかということの確認ですね。それと、２回に分けて行った理由というのをちょっと伺ったので、何で２回に分けて行く必要があるのかがちょっとわからなかったので、そこもあわせてお伺いします。","respondent":"鈴木都市計画課長","answer":"２回に分けて行った理由ですが、事務次官ですと事務方のトップと、審議官ですとナンバー２でしょうか、非常に国の上の方に区の考えについてしっかり説明あるいは伝えるということの重要性を認識しておりましたので、最初から２回に分けて行きましょうかというところ。","voiceIndex":34,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"それぞれ４月と５月の中身なのですけれども、国には記録が残っているという紹介がありましたけれども、箇条書きなのですけれども、先ほどのやりとりの中で、地元へのメリットの創出の部分の質疑がありましたが、何か先ほどの答弁ですとデメリットを軽減することがメリットですみたいな話でしたけれども、これは明確に地元ヘのメリットの創出と書いてあるので、これは先般の予算特別委員会の総括質疑の中でも。","respondent":"鈴木都市計画課長","answer":"やはり区全体に、何か例えば来訪者の方が区に滞在するとか、何かその場で、具体的に区が何かこういうことをやってくださいとかということをお伝えしているわけではなくて、そういった区のことをしっかり見据えて、国のほうで考えていただくというのが区のスタンスでございまして。","voiceIndex":36,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ちょっとそこら辺は認識をちょっと改めていただきたいと思います。５月のほうの国の記録なのですけれども、少し具体的にお伺いしますが、ここでは区長は事務次官に向けてインフラや空き家対策について国土交通省を挙げて品川区に目を向けているというメッセージがあるとありがたいというふうなことを述べているという記録があります。","respondent":"鈴木都市計画課長","answer":"５月１７日の事務次官とのやりとり、国の記録の中のインフラ、空き家対策ですが、こちらのほうも非常に短時間の中でのやりとりというところでございまして、何か区長が特定の場所のインフラ整備をということでは全くございません。","voiceIndex":38,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとそこら辺はもう一度お伺いしたいのと、それと、ちょっと今品川区長の当日の何か発言みたいなもの、引用みたいな感じの答弁もあったような印象があったのですけれども、一緒に考えていただきたいと述べましたみたいな、それは何かやはり品川区の中に当日の記録があるということなのですか。私たちはそれを出してほしいと言っているのですけれども、そこら辺はいかがなのか。","respondent":"鈴木都市計画課長","answer":"何か一緒に考えていただきたいというのを、私が何かを読んでこの場で発言したわけではございません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"安藤委員","kind":"確認","question":"その打ち合わせの記録の資料などは、これは当然残っているのではないかと思いますけれども、当日持っていかなかった、そんなことはあり得ないと思いますけれども、あるいは向こうに渡す文書はつくらなかった、そういうこともなかなか考えにくいですが、仮にそうだったとしても、事前の打ち合わせの記録資料というのは、つくらなかったのかどうか、それは残っていると思うのですけれども、いかがでしょうか。","respondent":"小林環境課長、鈴木都市計画課長","answer":"私のほうからは、環境騒音調査の実施についてのご説明をしたいと思います。昨年度の予算の中で、約８００万円使用いたしまして、環境騒音調査を実施しております。打ち合わせの内容につきましては、基本的には区のスタンスというのは、これは早い段階から決まっていたというか、スタンスはありましたので、それに対するそれまでの区の対応ですとか、あるいは都の方に聞いたりしながら。","voiceIndex":42,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"あくまでそういう文書は作成していないですが、なかなか物がないから何とも言えないのですけれども、もう一点伺いたいのは、これは何度も言っているように、トップレベルの直接交渉なので、しかも時間も１０分から１５分ですので、普通は要望を事前に国土交通省に文書として送りますよね。お願いします。","respondent":"鈴木都市計画課長","answer":"ただ、当然ながら、こういう今までお伝えしてきたことをしっかりお伝えしたいというところは事務レベル、担当レベルではあったのではないか、これは私の想定ですが、あったのではないかというふうに考えてあります。","voiceIndex":45,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"事務レベルでは何か事前にやりとりしていたというのは、そこら辺はちょっともう少しどんなやりとりをして下準備をしていたのか伺いたいというのが一つです。直接会えばいいというものでもないわけですよ。ですから、そこのちょっと何度伺っても会うことが重要だと答えられるその意味、そこにどんな意味を持たせていたのか、考えを伺いたいというのが２点目です。","respondent":"鈴木都市計画課長","answer":"それを何か文書でこういう内容をお伝えしますということはございませんでした。私は決して会うことが重要だというふうに先ほどから申しているわけではございませんで、直接会って、区の考えをしっかりお伝えすると、当然そのお伝えする内容も重要です。","voiceIndex":47,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"会いたいということを事前に伝えていったという事ですけれども、国はどんな考えなのですか、ちょっと文書で送ってくださいとも言わなかったと。地元中の地元の品川区が来るといったら構えますよね。この判断、決定そのものが、この羽田の新ルートという問題の重要性やこの行政運営上からいっても、重大な間違いだと思うのですけれども、いかがでしょうか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"文書をつくらないという決定権が部長にあるのか、それでいいのかですが、それはその場に参加した部長あるいは課長が、やはり区がお伝えしたことに対して何か国のほうで、先ほども申し上げましたが、それはもう違いますとか。","voiceIndex":49,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"部長に基本的には任せているということでしたけれども、当日区長からこれを記録しておいてねという指示はなかったということなのですかね。これは指示がないこと自体がちょっとどうなのかなと思わざるを得ないのですよ。そこら辺はどうだったのでしょうか。区長の判断という点では、当日何もなかったのか、記録を残してほしい、残すべきだ、残しておいてねという指示はなかったのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当然ながら同行した者が、それは職責ある者が同行していますので、その判断は職責ある者が判断をして、これが後で、あのとき、あの事務次官はどういう発言をしたかなと聞かれたときに、わかりませんとか記憶にないような内容あるいは長時間の内容であれば。","voiceIndex":51,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長がタウンミーティングでは、約束していただいたというふうに言っているのですよね。そういうことを言っているのですが、この国の記録を見ると、ご要望については勉強したいとか、５月のほうですね、インフラ云々のときは勉強したい、４月は事務的によく調整させてほしいと、ちょっとニュアンスが若干変わってくるわけなのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"安全対策のところで、騒音、落下物というようなお話がありました。この落下物対策ですけれども、国土交通省が３月に出しました落下物対策の強化策として、落下物対策総合パッケージというのをホームページにも出しております。これについての区の評価、またもし課題があるなと思うのであれば、それを教えてください。","respondent":"鈴木都市計画課長","answer":"基本的にはそれまで落下物についてはある意味特に海外の航空会社については、会社ごとに任せていると言ったら変ですけれども、それぞれで取り組みをしていただいていたというようなところをしっかり同じ内容で日本の航空会社。","voiceIndex":54,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"しかし、落下物をゼロにしていただきたいというのが区の思いだということでしたけれども、私たちも国土交通省に行きまして、この説明を受けました。そこら辺は区のほうは改めて国土交通省にこの対策のもうちょっと細かな、具体的なところを聞き取っていただいて、これでは危険過ぎるし、安全対策とは言えないということをぜひ言っていただきたいなと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"それを進めていく中では、やはりどこかが必ずやらなければいけないところ、どこの部分を航空会社にしっかりやっていただくかというのは当然あろうかと思いますので、先ほど申した、これからもさらなる安全対策を求めていくというところは。","voiceIndex":56,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"確認","question":"それでも、これは落下物対策ですから、落下物がゼロにならないと飛んでもらっては困るわけですよね。目指してもできないところもありますね。なので、この対策で落下物がゼロにできるということにならなければ、幾ら対策を講じられても飛んでもらっては困るわけですので、それぐらいの認識が区にしっかりあるのかどうか、ちょっと確認させてください。","respondent":"鈴木都市計画課長","answer":"この案に基づいて、当然ながら区としても落下物がないようにさらに取り組みを進めていただきたいというところは今委員がおっしゃったとおりです。","voiceIndex":58,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ国土交通省に、ゼロを目指す対策ではだめなのだということを、落下物ゼロを目指すのではなくて、ゼロを実現させていただかないと飛んでもらっては困りますということをしっかり言っていただきたいのです。区民の皆さんはみんなそれを望んでいるのです。ぜひお願いします。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"安全対策、落下物対策についてのさらなる取り組みについては、これからもしっかり求めていきたいと思います。","voiceIndex":60,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほど我が会派のほうから、不動産の価値についてちょっと質問をしたのですが、その後安藤委員のほうから、豊中市のいわゆる固定資産税の軽減策、これも私も聞いた覚えがあるのですけれども、これが豊中市の不動産価値が下落をしているということにどうつながっているのかというのはちょっと引っかかるので、私もこの不動産価値の下落については、さっきあくつ委員も同じことを申し上げたのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"私自身ももう少し都議会でやりとりがあった豊中市のことに関しては、ちょっとまだ不勉強なところがあるので、それはしっかりとさらに研究をしていきたいと思いますけれども、そうした質疑が行われたということと、現地での調査で私が確認した事実をもって、これは極めて資産価値に対して影響がある事業だと判断せざるを得ないのではないかと、そのほうが自然なのではないかと私は認識していると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-029"},{"speaker":"若林委員","kind":"意見","question":"いわゆる土地の価格が下がると、当然固定資産税が少なくなると、その場合、何で軽減策をわざわざ自治体がするのかなということは、あまり安藤委員がおっしゃるような、これからまた勉強されるということなので、またその成果を見てみたいと思いますが、なかなかこういう場で何か本当に個人的な意見で極めて関連性が高いというご意見はわかるような気もするのですけれども、その程度のお話かなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"引き続きちょっとそちらに関しては、重大な関心事ですので、研究もしていきたいと思います。それで、私がお伺いしたいのは、ちょっと記録がないものですから、結局今ある記録といったら区長のタウンミーティングの発言なのですよね。伺いたいのは、デメリットと言っていますけれども、改めて区長が言うところのデメリットしかないというのは何なのかというのをちょっとお伺いしたいというふうに思います。","respondent":"鈴木都市計画課長","answer":"それで、この話の流れの中で、やはり非常に影響がこの件は大きいというところは、国のほうにも、タウンミーティングの場でも話させていただいたわけで、そういった非常に影響が大きい品川区に対して、しっかり国のほうでも目を向けていただいて。","voiceIndex":65,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと確認したいのですけれども、容認したわけではないと。前回ですかね、行財政改革特別委員会の質疑の中でも、当時の課長が新ルートのほかに機能強化で品川の上を飛ぶ以外のルートというのは何か提示されているのですかというような旨の質問に対して、いやこれしかありません的な、そういうことも言っていたと思うのですよ。何かほかにあるのですか。それをちょっとお伺いしたいなと改めて思います。","respondent":"鈴木都市計画課長","answer":"それで、基本的に国際競争力を強化していく、海外とのつながりを強めていく、インバウンドを増やして、日本国として経済を発展させていくと、そういう必要が今後ありますという国の考え方、ここについは一定理解をするというところは繰り返し述べてきたわけでございまして。","voiceIndex":67,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"私としましては、国が言う機能強化というのは、国際便の増便だというふうに、イコールだと理解していたものですから、今のご答弁ですと、それはまた別だと。私が伺ったのは、増便と機能強化がイコールなのか、そこら辺を後で説明してもらいたいのですけれども、それは違うのだと。それがあり得ないでしょうと。そういう二重的な表現があり得るのですか。ぜひ答弁をお伺いしたい。","respondent":"鈴木都市計画課長","answer":"国のほうから示されているのは、その機能強化、国際競争力を勝ち抜くための方策として、新ルート案が示されているわけでございまして、先ほど来からお話ししている、区のほうで増便についても、新ルート案についてもあわせて理解をしていますというところは、そこは違いますよと。","voiceIndex":69,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"飛んでも終わりではない。求め続けるのでしょうけれども、まず飛ばないための努力をすべきなのではないですか。それをやらないで、これまでも、これからも安全対策を求め続けていくなんて、それはちょっと、私がやるべきことであると区長は言っていましたけれども、区はやるべきことをやっていないですよ。しっかりとここまで出されたら納得するというものがはっきりあるのかどうか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"それが、いつの間にかというか、終始一貫して品川区または区長にこういう対応をしなさいとか、こういう対応をしろとか、そういう何か区と委員間のやりとり、要望、要請、意見陳述みたいな、そういう審査はもうそろそろこれで終わりにして、効率的な委員会運営に移っていただければというふうに申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員長、質問します。よろしいですか。これが委員長だと私は思っています。ですから、そこのところをしっかりと配慮していただいて、先ほど若林委員から申し上げたこと、これをしっかりと委員長、ぜひ心に真っ正面に受けとめていただいて、円滑な運営を今後も行っていただきたい、このように申し上げたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員長","kind":"質問","question":"議会というのは、言論の府です。委員というのは、区民の代表としてこの場に参加をして、区民の意見を代表として発言をするという使命を持っているわけですから、そういう思いで、さまざま準備をしながらこういう質疑を進めているわけですから、しかも今回の今の質問に対しては、この陳情から外れるものでも全くないと考えています。しかも、まだあれですよ、２時間もたっていないわけですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-037"},{"speaker":"渡部委員","kind":"質問・要望","question":"同じ内容の繰り返しになっていると私は感じておりますし、たぶん今あくつ委員からの発言についてもそのような様子が多く見られてのことだと思いますので、それはどなたでもわかることですので、ご留意いただきたい。改めて傍聴人より不規則な発言ならびに物音がした際には、速やかに注意をいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、結局私が求めているのは、国にこのルートを飛ばさない、実行させないための行動を、区は何をしてくれるのかと、この中では、やはり国との交渉では、飛ぶことが前提の条件闘争なのですよ。それと、この協議会に向けて、品川区は飛ばさないための努力、区はどんな意思を、どういうふうに反映させるべく行動するのか、この協議会に向けて何をしてくれるのか、これを教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"国がやるべきことは、やはり区民の方が不安に思っていることについてしっかり区に対して説明していただいて、少しでも不安を払拭していただくというところが区の役割なのかなです。","voiceIndex":86,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"区もこのまま進めることに納得していないと言っているわけですよ。ですから、納得していないという立場であるにもかかわらず、次回協議会で地元の理解を得たというふうになりかねないという問題があるのです。この場に、区のこのまま進めることは納得しないと、そういう意思というのはどのように反映してくれるのですか。そこら辺は大事な問題なので、きちんと伺わせていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"これも繰り返しになりますが、今区が基本的スタンスとして、あるいは区の考えとして、国のほうにお伝えしているのが、落下物対策と騒音影響の軽減、区民への丁寧な説明ですので、これまでもしてまいりましたが、今しっかり区として行うのは。","voiceIndex":88,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"区が求め続けている落下物ゼロの対策は出てこないでしょう。この協議会というのは、区が参加していませんから、別に何もしないということなのですか。でも、国はその協議会の確認をもって地元の理解を得たというふうにやるおそれがあるのですよ。ここはどうなのか、品川区はその協議会に向けて何をしてくれるのですか。何もしないのですか、そこら辺はどうなのですか、お伺いします。","respondent":"鈴木都市計画課長","answer":"今お話になった協議会を次回、いつぐらいにやりますということではなくて、区の要望に対して地域へのさらなる丁寧な説明を行っていきますということを国から聞いてありますので、やはり区としてもしっかり先ほどの３点について国に伝えていきたいです。","voiceIndex":90,"id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"羽田新飛行ルートについてというよりも、首都圏空港の機能強化について理解をする、それは当然私たちも同じ意識でございまして、インバウンド、また観光資源をこれからどうしていくかですとか、やはり訪れていただく方々、日本の国としてこれから国力をつけていくことは重要なことですが、それは羽田の新飛行ルートとは別ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"結論を出すで、お願いします。１番については、昨年の第４回定例会以降さまざまな委員会質疑、代表・一般質問等で区当局からご説明がたくさんされたということで、報告がされているのだろうという認識で理解をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"２００４年にも浦安市で同様のことがあり、市長は保守的な方でしたが、立場は関係なく、この市街地ルートに反対を表明し、市議会もしっかりと反対をし、海上ルートに変えさせたということがありますので、やはり議会としても意見書という話もありますが、しっかりとした意思表示を、反対の意思表示をすることがどれだけ今の品川区民の皆さんの不安の解消、そして財産、命。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-044"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す。理由といたしまして、１に関しては、先ほども、前回も理事者より国土交通省との会話の内容に関して十分な説明がされているのかなと、我が会派としてはそうした理解をしております。２番に関しましては、まだ十分に区民に説明、また周知がされていない現状がありまして、また議会としても総意として２回意見書を提出している立場があります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-045"}]},{"id":"topic-02","title":"区有施設・公有地等活用に関すること","agenda":"区有施設・公有地等活用に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"介護施設ということで、介護施設というのはどのような、具体的にどういうものがあるのかというのと、あと定期借地というのは何年かというのは向こうから来ているのでしょか、そこがわかれば教えてください。","respondent":"柏原企画調整課長","answer":"こちらの国のほうの方針といいますか、今回のパターンで言いますと、平成２７年の秋に「介護施設整備に係る国有地活用について」ということで、方針が財務省のほうから出てあります。","voiceIndex":104,"id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"はい、わかりました。現時点として、区としては周辺住民にどんなニーズがあるかというのは把握されているでしょうか。","respondent":"柏原企画調整課長","answer":"具体的に言いますと、例えば空地といいますか、広場といいますか、という使い方ができないかというのは実際地元の町会の方であるとかというところからのお声は聞いているところです。","voiceIndex":106,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり、貴重な土地ですので、この間も課長から行政需要というのが、いろいろ言葉が出されますけれども、本当にたくさんあると思うのですね。ですので、町会の方だけでなくて、住民が参加する公有地活用検討会みたいなものも立ち上げて、地域住民をはじめ、多様な区民の要望を反映した活用を検討していただきたいなと思うのですけれども、ご検討いただけないでしょうか。","respondent":"柏原企画調整課長","answer":"ニーズの把握といいますか、どのような施設が望まれるかというのは、区としてもこれは大切な意見といいますか、施設を決める上では大切なことであるというふうに思ってあります。手法はさまざまあると思いますので、やり方というのは検討したいと考えています。","voiceIndex":108,"id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"今の質疑にも関連するのですけれども、売却で取得すると、購入するというふうになったときに、いろいろな使い方ができるのだよという話でございましたけれども、取得するに当たっても、いろいろ国とか都の補助金みたいなものが活用できる場合とか、丸々区の一般会計でみたいな話とか、そういうことというのは、用途によって考えなければいけないところというのはあるのではないかなと思ったりするのですが。","respondent":"柏原企画調整課長","answer":"その部分でうまく都の補助制度が使えないかであるとか、それから防災の観点で土地を購入する際に、国費が入ることがあるのですけれども、それが使えないかというような検討はしております。","voiceIndex":110,"id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっといろいろなところでの検討がどういうふうにしていくのかというところであるかと思うのですけれども、やはりもちろん我が会派からも予算特別委員会の総括質疑でしたか、取り上げさせていただいたところですし、地元の要望というのはその際にもどういったものがあるかということで紹介をさせていただいたところですので、そういったことをよくよく検討の中に入れていただきながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-050"},{"speaker":"大沢副委員長","kind":"意見","question":"副委員長を１年やらせていただきました。いろいろと羽田の問題、そして今日の審議、いろいろと皆様方には活発なご議論をいただき、意義深い委員会ができたと思います。これもひとえに委員長の名采配のおかげ、賜物だと考えています。皆さん、非常にご協力いただきましたことを改めて御礼を申し上げます。理事者の皆様方、ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6048#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":40513,"voices":121}},{"id":"h30-20180517-18","meetingId":"h30-cm05","date":"2018年5月17日","dateIso":"2018-05-17","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"小学校や中学校での上映、そして、今後、できれば、ビーチュウ、シナカモン、やたたまに声をあてて、その動画を流せばいいのではないかと思うのです。これはお金がかかることなので、すぐにはできないのかもしれないけれども、せっかく３つのキャラクターで応援しているわけですから、声をあてていただければと思いましたので、お願いしておきます。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"リンク等をはることにつきましては、私ども、今のところ考えておりますが、よりいろいろな方に見ていただけるように、先ほど言い忘れたのですが、区のツイッターもありますので、２分程度のものですと、ツイッターとかフェイスブックにちょうどいいので。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"ホスピタリティハウスの誘致","agenda":"ホスピタリティハウスの誘致","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"それとも、そのときに、私、ここの施設の説明を聞いて、３年間限定でということにはなっておりますけれども、もし万が一この３年限定の中で、このスポーツエンターテインメント施設がかなり人気が出て、３年ではなく、引き続きやっていきたいとなるかもしれません。そうしたことを踏まえて、ほかの場所の目星を区は別途つけていらっしゃるのか、その辺をお聞かせいただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと、今のところ決まっていることは、この場所がわりと広い土地になるのですが、そこの一画の２,０００m2程度を、２０２０年の１年間、有償でお貸ししましょうということだけ回答していただいているところです。","voiceIndex":13,"id":"exchange-002"},{"speaker":"新妻委員","kind":"意見","question":"ありがとうございました。全面的に誘致をするという方向で、ぜひ取り組みをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、現状、誘致活動としてどれくらい動かれているのでしょうか。それから、区はどういう国をターゲットにしているか、その辺のことについて教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どのぐらいの国に打診をしているかということと、どんな国を、ターゲットと言ったら変なのですけれども、来ていただきたいという気持ちがあるかということなのですが、動いている回数としましては、直接的にここにホスピタリティハウスはどうですかということではなくて。","voiceIndex":16,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、進捗状況としては、取りかかってきたという感じで、これから本格的に動いていくのか。それから、もう幾つかの国からオファーというか、いい返事が来ているのか、その辺の進捗状況はどうでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どもとしても遅れることなく、いろいろなところにアンテナを張り情報を集めていきたいと考えています。","voiceIndex":18,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"それが１つ。は大井ふ頭中央海浜公園が競技会場になる。それは区が打つのではなくても、その場所を借りるということができれば、区がプロポーザルでいろいろ提案をしてもらって、誘致をしてもいいわけですよね。そういうものがまるっきり我々見えないから、いろいろと提案しているのだけれども、区の方針が見えないと、ではどういうふうにしていきましょうと、お互いにそういう話ができないではないですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"キャンプ地のことなのですが、３月の国際大会のときに、幾つかお声かけはさせていただきました。実はその後、特にいいレスポンスが今のところないので、また引き続きこちらのほうも進めて、お声をかけていきたいと考えています。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すごい人出でした。だから、そこをどうやるかというのも、お金の問題も確かにあるけれども、あれだけの集客が図れるというのは、相当魅力があることであって、それはある程度行政判断がないとできないではないですか。今の答弁を聞いていても、これでは決まらないなと思っているのが私の印象なので、お考えをぜひまとめていただきたいという要望というか、お答えがあればお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、イベント等を打つとかいうお話も、競技会場周辺のことに関しましては、大会組織委員会等との協議も必要となりますし、あわせて競技委員会とも相談をしながら、ぜひ盛り上げていきたいと思っていますので、どうぞよろしくお願いいたします。","voiceIndex":22,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、先ほどから誘致の話が出ているので、ホスピタリティハウスの話では、区もいろいろ動けるのかなと思うのですけれども、東京２０２０大会のエンブレムとかは、あまり区が自由に使えないという話があったのですが、ホスピタリティハウスについては、どういったことができるのかということをお聞きしたいのですけれども、東京都。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"相手国と設置場所の行政等との関係でと聞いております。それから、２,０００m2ありきなのかということなのですが、そういうことではございません。","voiceIndex":24,"id":"exchange-008"},{"speaker":"つる委員","kind":"確認","question":"あそこが東京２０２０大会後、ホッケーの日本における聖地にしていくのだというのが、協会の考えですし、区としても当然それを直接的にも間接的にも支援していくというようなことが、この間、この委員会の中でもあったかと思いますけれども、そこの部分について改めて確認をさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホッケー協会の方からも、オリンピックが終わった後も、そこを聖地として、ホッケーができる場所としてほしいということは伺っておりまして、それは私どもも了解しています。ただ、ホッケーだけということではございません。多目的に使えるようにというのは考えているところです。","voiceIndex":26,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"今、一番最後の部分というのは、これは区民全体とか、東京都からみれば、都民とか、そういう意味では、野球の話もありましたけれども、野球も含めて、幅広くさまざまなスポーツができるような場所を確保していくというのは、この委員会の中でも当然それは求めてきたところなので、それはそれで別の話なのですが、要は、あそこをホッケーの聖地とするのだと。何かあれば、改めて伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いろいろなイベントでホッケー体験をやりますと、今までよりも多くの子どもが集まるような状況になっております。ですので、今後も地道に学校やすまいるスクール等ともタイアップしながら、ホッケーの普及というのはやっていきたいと考えております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"私もこのオリンピック・パラリンピック推進特別委員会に４年いる中で、やはりもう少しアクセルを踏みこんでというのでしょうか、大会組織委員会や東京都との確認とか、ご答弁で二言目、三言目に出てくる部分を区としてアピールできるところを目一杯やっていくということを出していく必要性があると思うのですけれども、改めてそこをお願いします。","respondent":"安藤文化スポーツ振興部長","answer":"２年しかありませんけれども、一丸となって気運醸成に取り組んだり、また、先ほど石田秀男委員のおっしゃったような、人の集まるようなイベントも含めて考えて、盛り上げていきたいと考えています。","voiceIndex":30,"id":"exchange-011"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"最初、品川ハウスという言葉が出ていたので、品川区全体でつくると言っていたような記憶があったのですが、そこは品川区としてはつくらないけれども、この場所に誘致するという考えでいいのか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"誘致にあたり、相手国にはスペースの一部に、品川ハウスを併設することを条件にするつもりでおります。そこでは、品川区のいろいろな案内だとかを行うことを、そこから区内の観光に繋げていくような仕掛けができたらと考えています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"品川ハウスという言葉がずっと出ていた中で、品川ハウス自体のイメージを区とし持っていただいて、新しく誘致していただいたところで活用していただきたいということを、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"強くなればやるみたいな話だけれども、そういう問題があるではないですか。聖地、なおかつ多目的というのなら、ある程度考えて動いていかないと、聖地にしますよと口ではいいことを言ってしまっても、その後、今度、多目的ですよとしたときに、これでは使えないよとか、いろいろな話が出てきてしまうではないですか。この辺の整理は、やっていくべきだと私は思っているのですがどうお考えなのでしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"大井ホッケー場の芝の部分につきましては、いち早く我々、大会組織委員会ならびに東京都の課長たちと膝詰めで、多目的と言葉で言うけれども、多目的と言うには、非常に難しいと。","voiceIndex":35,"id":"exchange-014"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"１年間、ありがとうございました。１年間の成果をまとめさせていただいたのと、それから、大会組織委員会には持ち込むことができなかったのですけれども、要望書をまとめさせていただきました。これを次の委員会でも活かしていただいて、しっかりとオリンピック・パラリンピックに向けて活動していっていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":14174,"voices":42}},{"id":"h30-20180521-10","meetingId":"h30-cm05","date":"2018年5月21日","dateIso":"2018-05-21","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"委員会室の変更についてなのですけれども、建設委員会が第１委員会室、厚生委員会が第２委員会室のほうに変わるというところに対してはそれで賛成なのですけれども、例えば、厚生委員会でたくさんの傍聴者が来るということはここ数年ないので、そういうことは余り想定が今のところないのですけれども、状況によってまたいろいろな運動が起きて広がり、傍聴者がたくさんになったときに、その点は柔軟に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結構です。","respondent":"久保田区議会事務局長","answer":"こちらにつきましては、第１回臨時会におけるオリンピック・パラリンピック推進特別委員の選任についてです。少しご説明をしますが、特別委員会の設置につきましては、臨時会で設置動議を提出し、設置するものということが基本とされております。","voiceIndex":10,"id":"exchange-002"}]},{"id":"topic-02","title":"第１回臨時会におけるオリンピック・パラリンピック推進特別委員の選任","agenda":"第１回臨時会におけるオリンピック・パラリンピック推進特別委員の選任","exchanges":[{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ確認なのですが、聞き漏れていたらすみません。今、所属している委員がそのまま来期も所属をする場合は、辞任届は出さなくていいのですか。","respondent":"久保田区議会事務局長","answer":"引き続かれる方もいらっしゃるのですけれども、正副委員長等の互選の関係等もありますので、一度、現委員の方には皆さん辞任していただきまして、新たに選任をさせていただきたいと事務局のほうでは考えております。","voiceIndex":14,"id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"これまでの流れの確認等、この議長会の要望についてなのですが、ここ最近、いわゆる議員の年金について、いろいろ全国市議会議長会からなのですか、要望が上がったとか上がっていないとかいうような話があったと思うのですが、その辺は現状どのようになっているのかというのを議長にお伺いしたいのと、あと、そういったものというのは、基本的にいろいろな議会からここに上げて。","respondent":"松澤議長","answer":"年金問題についてはいろいろ議長会でも出ることがありますけれども、これは経過を見ましょうということになっています。その件について事務局から何かありますか。いいですか。","voiceIndex":33,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"確認","question":"議会に関することで議長に確認をしたいことがありますので、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"議長候補として推薦する前提条件として、会派の意見として、その当時は消防団長の兼務はしない、任期は１年として３期３年はやらないという意見に対しまして、今の現議長も会派全員の前で自ら、「消防団長は就任後直ちに辞職をする」、また、「議長の任期は前回の議長が１期１年だったため、自分も３期３年はだめと考えている」と、やらないと考えているので、「１期１年、計２期２年で辞職するので。","respondent":"松澤議長","answer":"消防団長としての話については、その後、１２月３１日で辞任をいたしました。それまでの経緯につきましては、いろいろ消防団内部のこと、あるいは私も東京都の役員をやっているということから、いろいろ留意されたりという中で、そのような形で進んだわけです。","voiceIndex":43,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"しかしながら、状況が変わったのでということで、我々は理解をしているが、改めてそこについては、もう一度お答えをいただきたいのは、会派は我々会派にいらっしゃったわけで、我々会派で推薦をさせていただいたわけで、条件つきというのも、先ほど来申し上げましたとおり、我々が言ったわけではなく、自らご発言になったわけでありますので、その発言をされたこと。","respondent":"松澤議長","answer":"ですから、２年目についても、もう１年やらせてくれという意味の言葉を述べる会派というものがありませんので、私は１人会派ですので、自分の会派の意思としてはもう１年しっかりと議長として任期を全うしていきたいというふうに思っているところです。","voiceIndex":45,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"議長として崩壊状態にあるこの議会をこのままでいいとお考えになっていらっしゃるのか。信頼関係改善に向けた行動は、今のところ我々にはありません。関係改善をすることを考えられているとするのであれば、どのようにお考えなのかということを伺いたいと思いますが。その関係改善と、議会が今信頼関係が崩壊している状態、こういうことをどういうふうに捉えているのか伺いたいと思います。","respondent":"松澤議長","answer":"しかし再度言われたので、１０月にもう一度、消防署・東京都とお話をして、こういう事情になっているので、東京都あるいは消防庁の考え方では、当時の議長会の議長も消防団長をやられていながら議長会の議長をやっていらっしゃる。","voiceIndex":47,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"議長が、こういう信頼関係が今崩壊している状況をどう捉えて、それを議会の中でしっかり関係改善をされていくというのは、議長の、私は仕事だと考えていますし、職務だとも思っております。競馬議会の一般質問で議長が質問をされました。質問内容について、議長個人のお考えで質問をされたのか、議会の考えを、品川区議会議長という立場ですので、議会の考えを代表されて質問されたのか伺います。","respondent":"松澤議長","answer":"競馬議会の中で、厩務員の官舎、宿舎が大変に老朽化して、東日本大震災のときに大きな亀裂が入っているのですけれども、ここの建直しができないということを訴えられましたので、品川区の議長として一般質問を行いました。","voiceIndex":49,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確認をします。だけれども、ここは競馬議会でありますので、そこで一般質問をするときに、どういうことを質問をされても構わないのですが、確認をさせていただきたいのは、議長個人としてそのような陳情を受けたりいろいろなことで質問をされたのか、議会の議長という立場で、それを代表してしっかり質問をしてきたのか、そこだけを明確にお答えいただきたいと思います。","respondent":"松澤議長","answer":"なぜ文京区の議長がと思いましたら、あそこにｏｆｆｔ後楽園があるものですから、そのような関係から、文京区の議長にも騎手のほうから話が出たというお話を伺ったところです。大変に喜ばれました。以上がお答えになります。","voiceIndex":51,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のお話をまとめると、厩務員、確かにそういうご意見はよく品川区議会の中でも個人的に、林元議員などもご質問をされたり、我々にも直接厩務員の方々、建替えの問題、そういうことは話は伺っています。品川区の立場で代表されて議長で質問を公の場でするのであれば、私はやはりその辺の調査・調整はしてから質問をするべきだったと思いますが、その辺のところはどう把握をされているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"今、何か議長を個人的に、私の印象ですけれども、つるし上げるような形でのやりとりに聞こえます。非常によくないことだと思います。それで、議長は厩務員の皆さんから要請があってそれを質問に取り上げたと、これはあっていいのではないかと私は思います。幾ら議長会とか競馬組合の報告だと言っても。ここでこれ以上そういう時間は使わないでいただきたい。議事進行動議も含めて出したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"今、委員長の発言で。今、そういうふうに発言していただきたいとおっしゃったけれども、でも、先ほど私が申し上げたように、議長に対して個人的にどういう発言をしたかということを言わせたり、自分はこう思うと、２人の間のやりとりにしか聞こえませんよね。ここは先ほども言ったように、議長会であるとか、競馬組合であるとか、清掃組合の報告を受けるところで、いろいろなやりとりはあるかもしれません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"今、石田秀男委員が投げかけているやりとりは、議会運営にかかわることですので、議長の報告について意見を言ったり指摘をしたり、それは議会運営委員会でやるべきことだと思います。ただ、松澤議長が競馬議会での一般質問で、その敷地内で建替えをというふうに私は理解したのですね。私、個人的に品川区議会本会議で、一般質問で大井競馬場に敷地内にホテルを誘致するべきだと取り上げたことがあります。","respondent":"松澤議長","answer":"どちらにするのか私はいろいろと、今質問をされた方たちは、あそこの中で花火を打ち上げたりするときに馬が驚くのでなかなかできないよという中で、移転ということも考える、そういう中で、「お前、先にそういう質問をしたのか」というふうにもとれますけれども。","voiceIndex":57,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それを競馬議会の中で、公の場で、品川区の議長というのは公の代表ですから、その代表が今もそうですが、後のいろいろな話の中で調査、例えばいろいろな調査をしたり、どういう形で確認をされて行政はどう考えているのだ、東京都競馬株式会社は今どういうことを考えてらっしゃるのか、それからＴＣＫはどういうことを考えているのか、もしご質問したのであれば、その後いろいろなことがおわかりであれば。","respondent":"松澤議長","answer":"今、そういうふうに言われましたけれども、私は質問をして、それについて回答をいただき、それは厩務員の方たちにお話をいたしました。","voiceIndex":59,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"質問をすることは構いません。立場として。公の場で。それは構いません。そうするのであれば、それはやはりその事後でも、きちんとしっかり自分でそれは調査をされて、大きなことを言ったのであれば、それはそれで、皆さんに行政に対しても調査をして、皆さんにわかりやすく説明をするのが、私は議長の職務であり役目だと思いますので、それはつけ加えておきます。","respondent":"松澤議長","answer":"もしこういうお話があるのでしたら、前もって、議長こうだよというお話をいただければ、それなりの考えができて答弁ができたのかなと思いますけれども、今、押し問答になってしまって、何か私が悪い質問をしたような。","voiceIndex":61,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議長が議運の報告をされたときに、私も発言をさせていただきました。覚えてらっしゃるかどうかわからないけれども、それはいろいろなお考えがあるので、きちんと確認をしてくださいということは、そのとき議運で言いました。それだけはつけ加えします。今ここで言われて、初めてのようにおっしゃるけれども、あのときでももう既にそう言っていたということは、よくご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"もう、こういう議論はやめていただきたいと思います。議運の品性をおとしめてしまいますよ。それで、どういう内容で移転しようとか改築しようとか、選択するのは向こうの側ですよ。したがって、もうこの議論はやめていただきたい。こういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-018"},{"speaker":"渡部委員長","kind":"確認","question":"委員長として申し上げます。先ほどから申し上げているとおり、議会の運営にかかわることで聞いておりまして、個人攻撃ではなく、確認をさせていただいているような発言ととれていますので、それはその部分であれば続けします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"この質疑はもうこれで終わりにしていただきたいと思います。委員長の運営も、やはり個人的な、そういうことはないと思いますよ、ないと思いますけれども、そういうことはやはり本当に公正に、公平に運営をしていただけるように心していただきたいということをお願いさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今、議論をしている中であったので、質問をするのと、大井競馬場の件については、ここで私は質問のよしあしというのは触れないですけれども、議会を代表して何か大枠を公の場で発言するときには、できれば少し丁寧にできる部分があるのであれば、丁寧にしていただければ、我々としてもどういった意見があるのかというのはできる限りお伝えできるのかなと思うので、その点は今後の、誰がどうとか。","respondent":"松澤議長","answer":"関係構築は、私は当然ながらできるものならやっていきたいと考えています。","voiceIndex":68,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど競馬のことは終わりにすると言いましたのでやめておきますが、もう１つお聞きしたいのは、西本議員の政務活動費について、締まっていないというのは、もちろん締まっていないのは知っていますが、それから１年たった。現在どのようになっているのかというのをご説明いただければと思います。","respondent":"松澤議長","answer":"政活費の問題というのは議長が調査事項で見ておりますので、ここでそれをあからさまにしていいのかどうか、これは微妙なので、局長、何か意見ありますでしょうか。","voiceIndex":70,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今のお話で、我々も政務活動費のことは基本的に議長が最終的に話を伺って、当人といろいろな形でする。そうなってくると、議長が今お話しをされたということで確認をさせていただきたいのは、区長のところにもう行くということは、議長が何度もお話をされたときに、西本議員はこの件に関しては返還をしないというふうに明言をされているのでしょうか。","respondent":"松澤議長","answer":"ですから、これは今後の問題として、この次の議運か何かで報告をしようかという話を局長としていたところですが、局長、それについて少し補足は何か言うことありますかね。どういうふうに答えていいのか、私も、個人の問題ですので、あからさまに言えない部分がありますので。","voiceIndex":74,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"もしフォローがあったら言ってください。それで、そういうふうに明言をされているのですかというのをお聞きしたいわけですね。それがそうなのか。こういうことを踏まえたら、議長もその辺のところを、先ほども言いましたけれども、法的なことを踏まえて、具体的にどういう理解をされて区長部局にどういうふうに話をされているのかというのをお聞きしているのです。お答えがないから聞いているのです。","respondent":"松澤議長","answer":"政活費の問題で、議員の資格にかかわる問題なので、大変に難しい問題、取扱いが難しい。","voiceIndex":78,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"そう考えるなら、訴訟案件であるならば、余計に区長部局で答えを待つのではなくて、あり方検討会をもう一度立ち上げるべきだったのだろうと思っています。それについての議長の考え方をお聞きしたいのが１つ。この第三者委員会も、このようなときのために設置するべきであったと、私は考えています。改めて、議長はこの第三者委員会の設置目的、これはどういうことで設置しようとされていたのか。","respondent":"松澤議長、久保田区議会事務局長","answer":"今そういうご意見をいただきましたので、第三者委員会を立ち上げるのがいいのかどうか、これからしっかりと議論していきたいと思っています。局長のほうともお話をしながら詰めていきたいと考えています。局長から何か補足はありますか。議長のほうが来週お話ししようと言っていたのは、年に一度、政務活動費のあらまし等についてホームページで公開する際に、議運にかけておりますので、それについて来週、毎年のタイミングですと臨時会前の議運で話をしていますので。","voiceIndex":80,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"確認","question":"ですから、今の報告のとおりで、多分返還しないと言っているのでしょうということ。それから、区長部局にも、今、訴訟を含めて確認をしているということでしょう。だから、設置目的はどこですかということは、我々が第三者委員会をつくるときに、政務活動費をしっかりやりましょう、それはまさに設置目的に、オープンにする、もちろんプラスの部分もある、中身をもう一度精査する。今年議長になられて。","respondent":"松澤議長","answer":"１年間、とにかくもうここで任期が終わってしまうので、西本議員のほうと話をしてしっかり決めたいと、お互い西本議員も議員ですので、それぞれ傷つくことなく円満に解決したいということで、いろいろ苦労してきたところです。","voiceIndex":83,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の発言はちょっとあれだと思いますね。それはほかにできているところがあるわけで、これは調べると言っても、どういう経緯でどういう形でそういう第三者委員会ができたのかというのは、まさにこれは議長案件で、そういうことをこの１年間全くお考えではなかったという、今、理解でいいのでしょうか。","respondent":"松澤議長","answer":"その件については、立ち上げるということは考えていなかったと言われれば考えていなかったですね。","voiceIndex":85,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"この件は最後にします。それから最後に、議場の傍聴者の拍手・発言について、議場が今、本会議の傍聴者の拍手・発言の現状があります。これについて、議長は仕方がないと考えてらっしゃるのかどうか伺います。","respondent":"松澤議長","answer":"暴言についてはしっかりとそれは注意をしているつもりです。","voiceIndex":87,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"傍聴規則、我々もこう言うからには必ず全部読んでいます。注意ですね。議長はまずこの傍聴規則を踏まえて、そういう行動をおとりですか。もし、最初からそういう気持ちがあるのならば、最初にそのとき幹事長会なり何なり、それからこういう場でも、オブザーバーとして発言をさせてくれというような形で言うのが、私は議長としてのそれが職務だと思っていますが、その辺のところを改めて伺いたいですね。","respondent":"松澤議長","answer":"しかし、どこでどうしていいのかわからずじまいで、それは局長にも聞いていただければ、そういうお話をしていたということがわかると思いますので、局長、ひとつお答えいただけますか。","voiceIndex":89,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"まさに議長、それは悪いのですけれども、それは局長は議長を支えるための局長であって、それは局長がしっかり議長を支えていただいている。そこで答弁を求めるなどというのは。議長がしっかりそれは、簡単なことではないですか。それはだから職務怠慢ではないですかと聞いているわけでありまして……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"私は、局長が補足があればどんどん言っていいと思いますよ。それは当然言っていただきたい、聞きたいです、私は。ですから、そういうことをしていけばきちんと運営がされていくと思うのですよ。やじの部分を含めて。ですから、ぜひそういう方向で考えていただいて、この場はそういう方向に、それはもっともだということで一致できると思いますので、そういうふうに采配をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"石田秀男委員がおっしゃるのは、議長に対して個人的な攻撃をしているようにどうしてもとれてしまうのです。それは傍聴者だけではないですよ。いいですね、それは、心していただきたいと思っているのですが、だから、そういう状況が多々あるので、だから議長として、そういう状況をやはりなくしていく上で、正副委員長会等を必要に応じて開く。今は１回か何回ぐらいしか開いていないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"いろいろ長々、４項目にわたって質問をさせていただきましたけれども、我々としてはそういう主張の中で、全体の中でいろいろなこと、こういう混乱を招いていること、信頼関係が崩壊していること、こういうことで考えるのであれば、やはり辞職をしていただくべきだと思っていますので、それはよく、意見だけ述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30555,"voices":99}},{"id":"h30-20180524-8","meetingId":"h30-cm05","date":"2018年5月24日","dateIso":"2018-05-24","committee":"建設委員会","time":"午前１０時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ副委員長","kind":"意見","question":"長きにわたり、本当に委員会の円滑な進行にご協力いただいて、本当にありがとうあります。所管事務調査においては、また引き続きやっていくべきことはしっかりやっていって、住みやすい品川区をつくるため頑張っていきたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":1872,"voices":10}},{"id":"h30-20180528-10","meetingId":"h30-cm05","date":"2018年5月28日","dateIso":"2018-05-28","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":6669,"voices":29}},{"id":"h30-20180529-10","meetingId":"h30-cm05","date":"2018年5月29日","dateIso":"2018-05-29","committee":"議会運営委員会","time":"午後 １時４５分～午後 ６時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年第１回臨時会","agenda":"平成３０年第１回臨時会","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"現議長は、会派全員の前で自ら、消防団長は就任後直ちに辞職する、議長の任期は前回が１期１年であり、自分も３期３年はやらないと考えているので、１期１年、計２期２年で辞職するので、何としても会派の中で候補者にしてほしいと発言をしました。次に、議長は競馬議会の一般質問で質問をしました。「なぜですか？皆様にもご理解を頂き、議長不信任動議を可決して頂きますことをお願いし、提案説明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはご確認いただきたいと思います。我々もそれはしっかり確認した上で、今、この話をさせていただいています。厩舎地区のことについては、必ずここで計画の早期実現に向けていきますとか、何度もこの前もお話ししましたが、議長ですから質問をすることは全然権利がありますし、構いませんと何度も言っています。ですから、それはきちんとその後も指摘させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"私どもの、自民党から出されたこの内容についての見解を申し上げたいと思います。以下、理由を申し上げたいと思います。自民党は、議長職２年２期をかなり繰り返して主張しておりますけれども、これは自民党のルールにすぎません。議会との信頼関係が崩れていると主張して、不信任の理由にしておりますけれども、信頼関係が崩れているのは、自民党会派であり、その関係だけではないのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"ほかの点は見解の違いもあるので、それは言いませんが、１つだけ、最初の２期２年にこだわっているということは、我々が言ったわけでも何でもなく、議長自らがこの発言をされて、３年目はやらないので、候補としてほしいとおっしゃった。それは我々から言ったことではないということだけをつけ加えさせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"今おっしゃいましたので、また手を挙げざるを得ませんでしたけれども、それも議長が自民党・子ども未来の会派に属しているときの話です。全然今は関係ないではありませんか。こんなルールを持ち込まないでいただきたいと思います。","respondent":"松澤議長、久保田区議会事務局長","answer":"私も反省することは反省、やはりなかなか皆さんに相談しづらいところがあったのは事実ですけれども、今後、これから皆さん方とともに、今度新しくこういう機会を得ましたので、そんな意味では、皆さん方とともにいろいろお話をしながら。追加議事日程(3)についてご説明いたします。本日、動議が出されましたので、この後、直ちに追加議事日程(3)を本日の議題に追加し、日程を変更の上、お諮りをしていただきたいと思います。","voiceIndex":24,"id":"exchange-005"}]},{"id":"topic-02","title":"ほかにございますでしょうか。よろしいでしょうか。 それでは、議事の進行につきまして、追加議事日程(3)","agenda":"ほかにございますでしょうか。よろしいでしょうか。 それでは、議事の進行につきまして、追加議事日程(3)","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほどの件に戻らせていただきたいのですが、１点だけ議長に確認をさせていただきたいのですけれども、よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"改めて議長に確認をしたいのが、これまで第１会派自民党と関係改善をしてほしいといった中で、関係の改善がなされないまま今日に至ったといった中で、先ほど自民党内の会派のルールというか、お話も聞かせていただきましたが、１年おきに皆さんと話をされているといった中で、昨日の自民党会派の幹事長との話の中で辞表の話が出て、それを拒否をされたといった中で、会派は違えど、あくまで先日の議運でも。","respondent":"松澤議長","answer":"これは、もう１年やってもいいですよという証左だと考えています。自民党の会派の中では、松澤さん、これで２年やれますよという方もいらっしゃいました。名前は言えないですけれども。そんな意味で、私はもう１年、しっかりと品川区議会、頑張ってまいりたいと思います。","voiceIndex":31,"id":"exchange-007"},{"speaker":"本多委員","kind":"確認","question":"ただいまの事務局長の報告につきまして、議長に確認をしたいと思います。全てにおいて議会で取り上げる事件が議決をされたという重みについてどうお考えか、それと、今の出されました議長の不信任に関する動議が可決されたということにつきまして、辞職の考えはないのか、改めてその点をお聞かせいただければと思います。","respondent":"松澤議長","answer":"議決されましたこと、本当に私としても、青天の霹靂なのですけれども、これは議会意思がそうなったということで、これはしようがないと考えていますけれども、議長としては、１年しっかりと頑張って、議会の運営に努めてまいりますので、よろしくお願い申し上げます。","voiceIndex":40,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":14088,"voices":51}},{"id":"h30-20180611-6","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"区民委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"戸籍住民課では証明交付係が３名増えている。商業・ものづくり課では中小企業支援係が４名増えて、就業担当が４名減っているということになっておりますけれども、この配置の考え方というのですかね、配置でどういった施策を、どういったことをやっていきたいかという、進めていくという、今年の主な施策というのですか、配置にかかわって伺いたいと思います。","respondent":"伊崎地域活動課長、山崎商業・ものづくり課長、提坂戸籍住民課長","answer":"今年度主要施策として進めていきたいものにつきましては、今、るる担当のほうから説明したところですが。就業担当につきましては、就業ですので、区民の方がいろいろな企業に就職したいという人に対しての支援の部分、それから、昨年度までは中小企業のほうが今。証明交付係が３名増えているということでございまして、内訳としましては、平成２９年度の組織改正を受けて、その実態を精査した上で。","voiceIndex":35,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そのほかに、東京都に派遣している方が１１名いらっしゃるとなっているのですけれども、これは、昨年は多分ゼロ人だったと思うのですけれども、これが一気に１１名になったということの、配置の関係でお聞きしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"職員配置の中の派遣の部分のご質問ですが、昨年度までは人事課付で、人事課の派遣という形になっておりましたが、あと２年ともう迫っている中で、より品川区の当課と派遣者との連携を深めて進めていこうということで。","voiceIndex":47,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、人数は昨年も１１名で変わらないと考えてよろしいのでしょうか。２年ということで、施策反映に向けても、今年新たに力を入れたということになるのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの区役所に勤務する者としては、正規職員２名と非常勤１名の３名が増えております。派遣者に関しては、変わりはないです。","voiceIndex":49,"id":"exchange-003"}]},{"id":"topic-02","title":"品川区文化芸術フォーラムの開催","agenda":"品川区文化芸術フォーラムの開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"関係団体というのは何団体なのかちょっと伺いたいと思います。それと今回パネルトークをやられるということで、寺田倉庫というのが、ほかのを見ているとちょっと異質な感じがするのですけれども、伺いたいと思います。品川区の文化芸術振興協議会というのは、オール品川で取り組んでいくということですけれども、まだ登録されていないところが新たに登録することはできるのでしょうか。","respondent":"立川文化観光課長","answer":"１点目、関係団体の数ですが、こちらは昨年度準備会を実施しておりまして、そちらに約３０の団体が参加していただいているところですので、今回協議会につきましては、昨年準備会に参加していた団体プラス、また参加をお願いしている団体もありますので。","voiceIndex":58,"id":"exchange-004"}]},{"id":"topic-03","title":"平成３０年度文化センター等工事による休室予定","agenda":"平成３０年度文化センター等工事による休室予定","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"荏原文化センターに関してなのですけれども、何年か前にプールの改修工事をしましたね。今回するのとは別だと思うのですが、そのときに空調の改修とかは一緒にできなかったものなのでしょうか。こういうのは計画的にやっていったほうがいいと思うので、その辺についてはいかがでしょうか。","respondent":"立川文化観光課長","answer":"今回のプールの空調機の改修ですが、これを改修することによりまして、現在湿度調整というのがなかなかうまくいかないところをかなり改善できるです。","voiceIndex":64,"id":"exchange-005"},{"speaker":"藤原委員","kind":"意見","question":"私の記憶違いかもしれないのですが、たしか荏原文化センターが終わって視察に行ったときに、当時の課長がプールをずっと歩いて説明、プールの中、中というのは泳いだという意味ではないですよ。プールのところに入って、更衣室とか、プール内とかを、たしか視察に行ったような、そうしたら、記憶違いですね。今のご説明だと、当時はプールに関して一切何もしていないのですものね。わかりました。","respondent":"立川文化観光課長","answer":"平成２７年度についても耐震化改修をしている。平成２８年度は、プールの消毒装置交換等工事を実施しているものです。平成２９年度は、プール水槽内の塗装工事をしているものです。ということでございまして、空調につきましては、今回実施するです。","voiceIndex":66,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"一般感覚でいえば、毎年工事をやっていると、その間制限がかかる。普通に、一緒にできないかというのは、必ず地域感覚で出る話だと思うのです。ここまではしようがないとして、これからこういうことはあり得るのですか。来年とか、「何だ、去年一緒にできたではないか」とか、そういうことがあるかないか、これは多分地域の関心事なので、その辺だけコメントをください。","respondent":"立川文化観光課長","answer":"設備によっては、突発的に故障することもございまして、計画的に改修ができない部分もあります。ただ、委員がご指摘のとおり、改修についてはなるべくまとめて実施することが、利用者の皆様のためということで、そういった方向で考えていきたいと思います。","voiceIndex":68,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"もう一点だけ、これはこの案件に限ったことではないのですが、所管の施設全般で、結局庁舎などを例にしても、部分改修、部分改修で、小規模、中規模を重ねていくことが、本当の意味で効率的なのかどうかという疑問は、この例からも出ると思うのです。こういうことは現在議論の中にあるのか、少しでもあるのか、ないのかだけ教えてください。","respondent":"安藤文化スポーツ振興部長","answer":"それも施設整備とか、そこら辺と計画的に毎年やってはあります。この間耐震化とか、非構造部材とか、そういうのは実施しますけれども、その都度、その都度、まだ大丈夫なところはもう少しもたせようとか、そういう考えでもって、計画的にやっているところです。","voiceIndex":70,"id":"exchange-008"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"自民党として２点リクエストというか、提案したいと思います。１つは、都市型観光、これは毎年続きますが、あまりに対象も広いので、そしてまた２０２０大会に向けて関心事、これはもう必須だと考えています。それが１つです。これも２０２０大会に向けて、生活安全の観点、あるいは消費者センターの観点と両方あるかと思っていますので、その２点をリクエストしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-009"},{"speaker":"浅野副委員長","kind":"意見","question":"中小企業支援という観点でできないかと考えています。時々個人でやっている、また、二、三名でやっている企業に顔を出したりしているのですけれども、相当疲弊しているなという感じがありまして、品川区の中でも中小企業を今後もしっかりと育てて、育成していかなければならないのかなという気持ちになっておりますので、中小企業支援はどうかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-010"},{"speaker":"のだて委員","kind":"意見","question":"いただいた所管事務調査の資料を見ると、スポーツのことについての所管事務調査があまりなかったので、オリンピック・パラリンピック推進特別委員会との仕切りの問題はありますが、そこを日常的なスポーツということでできないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"それは大雨か何かで飛行機が、台風でしたか、やはり９月の初めとかであるならば、まだわからないですけれども、その辺で台風がまた来そうかなというのがあるので、私はなるべく飛行機でないほうがいいのかなという、委員長、いいのですよね、思いは、場所というよりも、どういう手段で行くかといったときに、その時期、台風の時期ですから、飛行機はあまり。","respondent":"本多委員長","answer":"続きまして、日程について確認します。行政視察は例年第３回定例会後に行っておりますが、今年は９月３０日に区長選挙が予定されている関係で、第３回定例会前の９月３日の週、または９月１０日の週、どちらかでの実施が濃厚であります。","voiceIndex":78,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2810#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":37047,"voices":81}},{"id":"h30-20180611-7","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"厚生委員会","time":"午後 １時００分～午後 ４時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"福祉部の事務事業概要の組織図、９ページで、福祉計画課の派遣というところです。前回質問したときに、策定委員会が５月ぐらいにということで、先ほどの説明の中で、もう第１回をやられたということでしたので、この策定委員のメンバーを伺いたいのと、策定委員会の公開も求めてきたのですけれども、これがされるのかどうなのか、そして、議会への報告はいつごろされるのかというのを伺いたいと思います。","respondent":"大串福祉計画課長、松山障害者福祉課長、矢木生活福祉課長","answer":"その委員長からの強い要望で、今申し上げましたように３７名の方が一堂に会するといったところで、個別のお話がなかなか聞きづらいといったところで。なので、１名が基幹相談支援センターと障害児の計画相談支援の業務を兼務しているという状況になってあります。ケースワーカーの人員の増員の件ですが、こちらは区全体の人員配置のこともございまして、なかなかすぐに増ということにはなってこないですが、ただ。","voiceIndex":51,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。そうしたら、地域福祉計画は３７名でということで、全体でやるときは、公開される感じになるということでいいですね。わかりました。これは、支援計画なので、一番大事なところだと思うのですけれども、そこが組めないと、サービスにつながらないというところにもなってくるので、そこが２名だけになっているという現状を、区としてはどう考えているのかというのを改めて伺いたいと思います。","respondent":"松山障害者福祉課長、矢木生活福祉課長","answer":"今後、区だけではなく、民間の事業所等も含めまして、広い視野で相談を丁寧に行っていきたいと考えています。ただ、私どもも手をこまねいているわけではございませんで、例えば週に１度の係長会で最新の技術、情報等を共有していますし、こうした委員会等の情報につきましては逐一、朝会等で情報提供するといった形で。","voiceIndex":55,"id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林委員","kind":"意見","question":"大変細かいこともあるかもしれませんけれども、とりあえず書き出しましたので、お伝えします。高齢福祉については、参考までにということで、住宅確保について、生活支援策について、認知症対策について。それから健康については、３歳児の視力検診について、子どもの歯科矯正について。障害児者については、福祉タクシーについてなどです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"障害者、当事者の方からも、ここの充実を求める声が強い分野かと思っていまして、必要とする支援が提供される体制、サービスの支給量とか、そういったことを調査できたらと。品川独自の独特なやり方というところでは、それがどのように地域包括ということになっていけているのかというところが、なかなか見えてこないので、そういったところも調査研究していきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-004"},{"speaker":"若林委員","kind":"意見","question":"さっき漏らしたところもありまして、今回、７名の委員のうち５名が２期連続という、これを長所と捉えて、前回の調査項目をさらに深めるという観点もあっていいのではないかと思いますので、障害者福祉については、やはり相談支援を引き続き深めていきたいということ。そういう勉強も先日させていただいたところでもありますので、ここら辺を、視察も含めて、大いに深めていきたいというのが１つ。","respondent":"石田（秀）委員長","answer":"今、私も調べてくださいとお願いしているところもあったりして、文科省とかに行って勉強したいと思っている項目もあるので、そういうことも含めて、他区等視察に行って、一緒に勉強してくるということも取り入れていきたいと考えていますので、何しろ６月１８日。","voiceIndex":69,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":63050,"voices":72}},{"id":"h30-20180611-8","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"建設委員会","time":"午後 １時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"松永副委員長","kind":"意見","question":"お疲れさまです。建設委員会副委員長を務めします、国民民主党・無所属クラブの松永よしひろです。委員会運営にしっかりと取り組んでまいりますので、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"都市環境部と防災まちづくり部ともに事業も多いですし、あと性格も違いますので、できれば事務事業概要の冊子も分かれていることですので、説明と質疑はぜひそれぞれの部ごとに行っていただけないかなと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"この概要でしかなかなか質疑できないようなものですとか、概要的なものについて質問したいと思います。品川区としては、超高層によるさまざまな弊害、課題というのはどう考えているのかなと改めてお伺いしたいなと。風害ですね。そういったさまざまあるのですけれども、超高層による弊害、課題というのをどういうふうに考えているのか、課題はないと考えているのか、そこら辺をお伺いしたいと思います。","respondent":"鈴木都市計画課長、稲田都市開発課長","answer":"都市計画審議会における傍聴者への資料の配付、ならびに議事録の公開につきましては、内容に応じて適宜やっていかなければいけないなですが、基本的には都市計画審議会の中でご審議いただいて、区民の代表の方も含めて。広場におきましても、この地区で必要な広場、道路等々についてしっかりとした都市基盤を考えながら、そしてつくっていきながらまちづくりを進めているというところでございまして。","voiceIndex":54,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、区としてもしっかり事務局としても、そこら辺の問題意識を持って改善していただきたいのです。と思いますけれども、いかがでしょうか。私が伺ったのは弊害です。さまざま５点紹介しましたけれども、課題ばかりなわけではないですか。私はすごく大事な観点だと思うので、それぞれの事業でもしあればお伺いしたいというのが３点目です。そこら辺はいかがでしょうかというのが４点目です。","respondent":"鈴木都市計画課長、稲田都市開発課長、高梨木密整備推進課長、東野まちづくり立体化担当課長","answer":"再開発等の審議会での資料の配付、ひいては区民、地域への事業の内容の周知ですが、基本的には都市計画で進めている再開発事業等につきましては。そう進める中で、風に対しても検討いたしまして事後計測も行ったり、日照についても考えながら。中には忙しくてそういう検討会にも出られないのだけれどもという方もいらっしゃいますので。これまでも中央新幹線に関する説明会等につきましては、この委員会等でも事前に報告をさせていただきました。","voiceIndex":57,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう問題意識。ところが、ほとんどが分譲で、しかも買っている方は外国人の方も含めてすごくいろいろな方が入ってくる中で、しかも世帯数は１,０００世帯となってしまうと、どうやって建て替えするのだという問題を考えているのですかね。これは私は慎重であるべきだと思うし、もしどうしても入れたいというのであったら、入れるメリットは何なのですかというのを具体的に聞かせていただきたいです。","respondent":"鈴木都市計画課長、稲田都市開発課長、藤田防災まちづくり部長","answer":"都市計画、再開発事業など、そういった取り組みの情報の伝え方というものにつきましては、やはりその事業エリア内、あるいは周辺の方々、伝えるべき人々。例えば、大崎駅なのですけれども、大崎駅はまちも工場地帯からだんだんとこのようなオフィスとかそういった形に変わっては来ているのですけれども。総合的に勘案しての採用ということで考えてあります。","voiceIndex":62,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"メリットが全然具体的でないですよね。経験を通してなんて言われても、総合的になんて言われても、全然わからないので、そこら辺はちゃんとしっかりと、これだから自衛隊のＯＢが必要なのだというふうな理由はないということですか。そこら辺、目黒川の対策についての決定的なところはどういうふうに考えているのか、お伺いします。ですから、このソフト対策のみで十分なのか、課題を伺いたいと思います。","respondent":"たけうち委員長、藤田防災まちづくり部長、持田河川下水道課長、古巻防災課長","answer":"先ほどの人事の件は、基本的には総務委員会マターになりますが、建設委員会の中で可能な範囲でもしお答えがあればお願いいたします。最終的には、やはり国民保護というお仕事そのものが自衛隊のほうで、国民保護という観点で行われるような事象でありますので。この原因につきましては、過去にいろいろと検討がなされておりまして、川の下流、海水が流れ込むというのが一つ要因としてあって、もう一方で。","voiceIndex":66,"id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"これからの進め方についても確認したいので、まず一つは、ＥＣＯフェスはもう終わってしまったので来年度に向けてお願いしたいなと思っているのですが、先ほど拡張して３万５,０００人来場されたということなのですが、広がったのはわかるのですが、非常にわかりにくかったというご意見をいただいておりますし、実際にフードコートのエリアをまとめたというのはいいのですけれども。","respondent":"たけうち委員長、小林環境課長、今井土木管理課長","answer":"ただ、この後進めていく中で、所管事務調査はどうしますかという中で、例えばもし必要ならお出しいただいて。今年度から拡張してイベントを実施したところですが、それの対策として。実際には、初めてスタートしました区が中心になって、だんだん広げる形で進んでまいりましたので。","voiceIndex":71,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"羽田空港についてはいろいろな案件があってからというお話なのですけれども、所管事務調査の中に入るのかどうかわかりませんが、議論になっているときに経過報告をしていただきたいなと思います。行革での審査内容は、もちろん議事録を見て同じ情報は入手しますけれども、やはり皆様の情報の共有というのですか、そういうスタート時点での議論というのが必要になってくるかなと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-008"}]},{"id":"topic-03","title":"立会川雨水放流管工事（東京都下水道局施工）","agenda":"立会川雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１点だけお願いいたします。「立会川流域の浸水被害に対するさらなる安全性の向上を図る」とあるのですけれども、詳細はどのような形で安全性が向上されるのか教えてください。","respondent":"持田河川下水道課長","answer":"そういったことから、設計のほうは内容を少し変更しまして、より大きな施設をつくりたいと。このために工事期間が少し長くなってしまうといった説明が区のほうにあったです。","voiceIndex":83,"id":"exchange-009"}]},{"id":"topic-04","title":"「震災時火災における避難場所等の指定（第８回）」の公表","agenda":"「震災時火災における避難場所等の指定（第８回）」の公表","exchanges":[{"speaker":"西本委員","kind":"質問","question":"変更になっているところに対する告知というのはどういうふうにされますでしょうか。","respondent":"古巻防災課長","answer":"先ほどもご説明したとおり、まずホームページや広報でも掲載しますけれども、該当の町会の回覧板および掲示板で周知を行っているほかに、今現在既に行っておりますが、各町会の町会長会議等に出向きまして、防災課から直接説明をしています。","voiceIndex":91,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな手をこれから町会長も含めて町会とも相談しながらやられるのだろうと思うのですけれども、なかなか根づくためには非常に時間がかかるのではないかと思いますので、継続的な告知というかお願いを機会ごとにぜひしていただきたいですし、避難所訓練が毎年行われると思うのですね。ここはぜひ告知をしていただいて、認識度を高めていただきたいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"周知につきましては、確かに浸透するということが重要だと考えておりますので、十分に周知が進むように繰り返し周知を進めていきたいと考えています。","voiceIndex":93,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"今回８回目ということなのですけれども、これって何年に１回見直しとかそういったルールがあるのかどうか伺います。それと、あと決め方ですね、変更とかいう場合、実際住んでいる方からはいろいろご意見などをいただく機会があるのですが、区民の声の反映というのですか、地元の自治体としての意見というのはどのように変更に反映されていくのか、そこら辺をお伺いしたいと思います。","respondent":"古巻防災課長","answer":"見直しの間隔に関しましては、おおむね５年と東京都からは聞いております。前回が平成２５年でしたので、ほぼ５年たった平成３０年ということで見直しがかかったと認識をしております。","voiceIndex":95,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"いわゆる広域避難場所の考え方なのですけれども、大火のときに避難すると認識していますが、どのような状況のときに避難するという考えなのでしょうか。その際の地震の規模というのはどの程度のものを想定しているのか伺いたいと思います。伺いたいと思います。","respondent":"古巻防災課長","answer":"震災の規模等につきましては、基本的に東京都の被害想定に基づく震災の類型がありますので、そういった中で火災が起こる状況も勘案しながら、指定を進めていると考えております。","voiceIndex":97,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。一例を挙げますと、大井競馬場あたりに行くというところで、西大井のあたりとか戸越ですか、二葉とかちょっとこのエリアというのは現実的ではないのではないかという声も聞くのですけれども、そこら辺、大井競馬場、しながわ区民公園の広域避難場所については区としてはどういう課題を感じていらっしゃるのかお聞かせいただければと思います。","respondent":"古巻防災課長","answer":"ただ、今回東京都でもそういったところにつきましては、なるべく少しでも近い距離のところへ避難をできるような避難場所の指定の見直しですとか地区割りの見直し、そういったものも行っておりますので、一度に解消はしていかないとは思いますけれども。","voiceIndex":99,"id":"exchange-014"}]},{"id":"topic-05","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"中身なのですけれども、敷地の左下のほうでたしか第一三共から土地を買った部分で公園を広げて、そこで児童相談所というイメージがあったものですから、今回は上のほうにということなのですけれども、左下のところは区が買ったのかどうかということと、なぜそこの真ん中になったのかというのをお伺いしたいと思います。","respondent":"溝口公園課長","answer":"委員ご指摘の、今後無償で寄付をいただける土地を含めて計画・検討したところですが、ここにつきましてはこの後、以前建設委員会でもご報告しました下水道の工事が入ってくる関係がありますので。","voiceIndex":106,"id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"そういう中で、やはり理解していただくという面でも、よく利用者の方ですとか関係する団体、住民の方によく丁寧に説明しながらということは最低限必要だと思っているのですが、その点でどういう形でどういうふうな方法で周知をしていきながら進めていくお考えなのかというのをお聞かせいただければと思います。","respondent":"溝口公園課長","answer":"まだ所管のほうの児童相談所の設計につきましては今後基本設計等に入っていくところもありますので時期は明言できませんが、しっかりと住民説明会、そういったものも行いながら、そういったところを踏まえて区の考え、またそういったところでの区の計画に対する考え。","voiceIndex":108,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今の質疑の中にも出てきたのですけれども、子供の森公園、恐竜ですか、かいじゅう公園という愛称ですけれども、恐竜のオブジェがあって非常に、先ほどポスターにもあるという話がありましたが、シンボリックなもので、私も質問で何回か取り上げさせていただいたこともあります。先ほど再配置はやむを得ないだろうということはありました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"公園で新規にとなるとこれだけの時間がかかってしまうのだろうなという思いはあるものの、ニーズとすればもっと早くしないといけないのではないかという思いがあるし、また子供の森公園というのは今までのご質問にもあるように非常に親しまれている公園なので、それをなるべく維持した形でという思いもあるものですから、そこら辺は何かご存じであればお願いいたします。","respondent":"溝口公園課長","answer":"公園の用地、要は児童相談所という機能の性質を考えてなかなか複合でできない部分とかさまざまある中、どういう形で土地を取得していくのか、または土地を取得していかないのか、そういったところもいろいろさまざま検討していたと聞いているところです。","voiceIndex":111,"id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと確認といいますか伺いたいのですが、少年野球場もありますし、あと向かいが品川学園ということもあります。多くの子供が遊んでいるということで、今回基本設計ということで平成３０年度、今年度となっているわけですが、やはり大変いろいろ議論があるのではないかと思うのです。何か相談とかしたのかどうか、それぞれについて伺えればと思います。","respondent":"溝口公園課長","answer":"所管から聞いているところですと、やはりまずは議会のほうにしっかりご説明をしてから、それから地元町会ですとか公園の利用団体、また学校、そういったところにしっかり説明をしながら進めていきたいと聞いているところですので、今後。","voiceIndex":113,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特に、先ほどの事務事業の説明の中にもありましたが、避難所運営マニュアルを今年度徹底的にこれをしっかりと地域で策定していくということがあったものですから、防災対策というところを取り上げていただきたいということが一つです。これは自転車に限ったことではなく、地域に根差した交通、こういったところを取り上げていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"今あくつ委員より２点ありましたが、それにもう一つ加えていただきたいのは、水辺を活用したまちづくりでありまして、ここのところは今後２０２０を含めたインバウンド対策として重要な位置づけをなされるものではなかろうかと思いますので、水辺のまちづくりを自民党としてはそれにプラスをしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"羽田新ルートの問題は、やはり２０２０年の実施までにあと２年を切っているということですので、昨年は暗騒音の調査なども行ったという話もありましたけれども、これが実行されたときの影響ですとか、さまざまな問題が区民生活にかかわってきますので、やはりしっかり委員会としても調査をしていく必要があるのではないかというのが一つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"水辺活用、舟運の推進をやっていただきたいと考えております。東京都も水都東京の復活ということを掲げておりますし、先ほど別の委員の方からもご意見が出ましたとおり、２０２０オリンピックにあわせてそうした都市型観光、インバウンド対策としても品川区の水辺を活かしたまちづくりということをぜひやっていただきたいと考えております。以上、大きくこの３項目をぜひよろしく申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"防災対策はぜひ継続していただきたいと考えています。水辺の活用もぜひお願いしたいなと考えています。羽田空港の機能強化については、これはやはり継続的にいろいろと出てくるかと思いますので、行革からこちらのほうに移行されたということも含めますと、しっかり取り組んでいかなければならない項目ではないかと思いますので、この３つをお願したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-024"},{"speaker":"松永副委員長","kind":"意見","question":"私たちの会派では、一つは先ほど皆さんおっしゃっていた水辺のにぎわいの創出についてということをお願いしたいと思います。いろいろキッチンカーとかで五反田あたりで何かやられたかなと思うのですが、定期的にそういうのが行えるような形にしていただければなと思います。２つ目は、先ほどおっしゃっていたような防災対策についてお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-025"},{"speaker":"大沢委員","kind":"意見","question":"いいや。それはもうお任せです。３日の週は、できれば私じゃなくて、今アイコンタクトいただきましたけれども、あくつ委員からも意見が出ると思いますので、３日の週はどちらかといえば外していただければ。希望としては３日を外していただいたほうがいいと、私、自民党とあくつ委員はそういうふうに思っておりますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"私はよく視察内容も精査して、２泊３日ありきでなくて１泊２日でも私はいいのではないかと。どうしても調査しなければいけない事項がこれだけあるというのであれば慣例どおり２泊３日でもいいのかもしれませんが、私はそういったことも勘案すると、１泊２日ということもありなのではないかという意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"大阪市でございまして、先ほど自民党からも水辺の活用というお話がありましたが、もしかしたらこの中でも視察に行かれている方たちもたくさんいらっしゃるかもしれませんが、大阪市の北浜テラス、川と町の連続性というものを活かしながら、先ほど副委員長からもお話がありましたが、包括的に河川敷を占用して飲食店等を継続して行っているというところで非常に有名なところなものですから、ここが一つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"豊中市です。やはり羽田の関係でしっかり委員会としてもどういう実態なのかというのはきちんとさまざまな角度から調査したほうがいいと思いますので。大阪市も実は飛んでいますから、ただ、大阪側のほうも影響はあると思うのですが、豊中市ということでどうかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"防災対策について、神戸市を視察。なぜかというと、ここにもありますように、以前視察が中止になった経緯がありまして、当委員会でも台風の影響で視察が中止になった経緯があります。この神戸市の防災対策についてと、同じく兵庫県の加古川市の自助・共助による防災のまちづくりについて、これを２点入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-030"},{"speaker":"松永副委員長","kind":"意見","question":"私からは、水辺のことで先ほど大阪市の北浜テラスというところもあったのですが、もう一点屋台のほうで、福岡市の屋台文化はどうかな。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-031"},{"speaker":"松永副委員長","kind":"提案","question":"平成２５年７月に福岡市屋台基本条例というのが制定されまして、屋台に関しては悪臭とか騒音とかいうことがあって、年々減少傾向にあったのですけれども、この条例によって、屋台の指導員による巡回とか指導ルールの厳守とか、上下水道、電気整備など環境整備もその間とり行われて、今現在は年々増え続けているということで、ちょっとそういったところも含めて視察してはどうかということを提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4234#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":51678,"voices":140}},{"id":"h30-20180611-9","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"文教委員会","time":"午後 １時００分～午後 ４時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"南委員","kind":"意見","question":"日本共産党品川区議団の南恵子です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"幾つかあるのですけれども、３３ページの学校働き方改革は平成２９年度からなのですが、改めて、この内容を教えていただきたいことが１つ。ここはどういう状況か、改めてこの数字を伺いたいと思うのです。当然ながら、中学校は同じ横ばいで、合計では２１.２％、そんなに大きな数字の差ではないと思うのですけれども、落ちている状況がどういうことなのか教えていただきたい。","respondent":"熊谷指導課長、大関教育総合支援センター長、篠田学務課長","answer":"しながわ働き方ルネサンスについてですが、昨年度の９月５日に学校働き方改革。不登校に関するご質問ですが、国が毎年調査を行っております問題行動調査結果といたしまして、正式に公表されているものは。就学援助の受給率の関係です。小学校・義務教育学校、前期の課程が平成２９年度は１８.３％と落ちています。","voiceIndex":35,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれありがとうあります。小規模校、中規模校、具体的に報償費をつけるということは、一般的には勤務時間が多くなると、その分、残業代を出す、そういうイメージで伺っていいのかがわからなかったので、その辺を教えていただきたい。そういうところとの関係で、学校働き方改革をどう見たらいいのかと私は感じたので、その辺の評価を伺いたいのが１つです。その辺についての見解を伺いたいと思います。","respondent":"熊谷指導課長、大関教育総合支援センター長、篠田学務課長","answer":"ですので、必要に応じて、例えば、先ほど申し上げたように、用事等があるので、それに応じて学校がそれぞれアシスタントを募集して。それに次ぐ内容としては、例えば学業不振が２０％台で出てきている状況で、また、同じく２０％台では友人関係の悩みなども出てまいります。今のところ、特段変更するものではないものです。東京学芸大学との連携による学習支援事業ですが、学芸大学の学生、私ども事務局、東京学芸大学附属竹早中学校の教員で、直接。","voiceIndex":39,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大きく言うと３点、ご質問をさせていただきたいと思います。例えば４２ページのいじめ防止等の対策のところも、毎回同じような説明をいただいているのですが、せめて相談の電話の件数とかメール相談とかを始めたところにどのくらいアクセスがあったり、話が聞けているのか、そういうものも含めて、概要をもうちょっと膨らませていただきたいと思うのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長、有馬庶務課長","answer":"性的マイノリティの方への内容につきましては、基本方針、２ページの最初の１、人権教育の推進の(1)で示していますように、人権尊重の理念を広く定着させ、同和問題をはじめ、子ども、女性、高齢者、障害のある人など。中身について、各課で、そういう数字でもう少しあらわせるようなところも、全体を見ながら、来年に向けて、内部でも検討はしていきたいと思います。","voiceIndex":44,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"総務委員会の部分ともかかわるかもしれませんけれども、図書館で取り組める状況を一歩も二歩も進めていただきたいという思いがあるので、そこを１点、お願いしたいのが１つです。記載については、内部でいろいろ検討をしてくださるということなので、ぜひ検討をしていただきたいのですが、具体的にさっきの２点は質問をしたので、数字がわかっていたら教えてください。","respondent":"熊谷指導課長","answer":"教員の病休ですけれども、平成３０年２月１日の段階で、７名が病休に入っています。これは延べですので、同じ方が２回とっている場合もあります。最初は１２名おりまして、現在７名ということで、５人が復職しています。","voiceIndex":47,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一点は、いじめの相談とかメールとか、そういった具体的な数字がわかっているのだったら、状況を教えていただきたい。","respondent":"大関教育総合支援センター長","answer":"そのほか、実際の対応としてスクールソーシャル・ワーカーが学校に出向いていっている件数といたしましては、延べの件数となりますけれども、１人の方で何十回というケースも含めてですが、実際には２,０００件を超える学校への支援を行ってあります。","voiceIndex":49,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"すみません。私、まだそんなにやっていませんけれども。直近のことは人事課に聞かないとわからないですか。","respondent":"有馬庶務課長","answer":"事務局内の職員の時間外については、我々でも把握はしています。","voiceIndex":53,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"教職員の方ではなくて、教育委員会の事務局のところがわかれば教えていただけたらと思います。月８０時間以上の職員が何人中何人いるのかという割合でお願いします。","respondent":"熊谷指導課長、有馬庶務課長、篠田学務課長","answer":"指導課は２４名おりますけれども、４月分になりますが、８０時間超えが３名おりました。指導課は超勤が多い傾向があるのですけれども、ほかの課はそれほど多くないとは把握しています。庶務課は今、データがないのでわかりません。今は手元に今年度分の数字はないのですけれども、８０時間を超える職員はいなかったと記憶しています。","voiceIndex":55,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"総合教育会議は総務の扱いなのですが、教育委員会として、この仕組みがなかったころと、こういった形で行政との接点ができて、どのようにプラスの面があって、今後、どのような形が考えられるか、教育委員会としてのお考えを伺いたいと思います。今年度の結果については、何らかの形で教育委員会の会議で公表した内容を示すべきだと思いますが、いかがでしょうか。","respondent":"有馬庶務課長、熊谷指導課長","answer":"１点目の総合教育会議の件ですけれども、今まで教育委員会、委員内部が事務局との間で教育の施策についていろいろ検討してきたところに、区長との懇談会を交えて、一定程度の教育に関する考え方を確認しながら。その１つの大きな柱となるのが品川コミュニティ・スクールですので、校区教育協働委員会で協議しながら、そして、学校支援地域本部の力をかりながら進めていくことが重要なのではないかと考えています。","voiceIndex":59,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれありがとうあります。それから、学校働き方改革のところは、コミュニティ・スクールの役割が非常に大きいと思いますので、単純に何時間働いたら超勤かどうか、そういう話も必要ですけれども、今、根源的なお話があったように、果たして学校がやるべきことは何なのかを地域の方々とお話ししていく場面をつくることが大切だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"さっき質問させていただいて、答弁がなかったので。最初のセクシュアルマイノリティの生涯教育に関して、図書館について取組みをお伺いしたので、具体的に。生涯教育の分野で、性的マイノリティを含めて、多様性について区民の理解を進めていく立場で、どういう取組みがされているのか。書籍の選択なども影響してくると思うので、その辺の取組み、あと、イベントとか何かがあったら教えてください。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"人権といいますか、平和といいますか、事業として取り上げる項目はありますが、定例の中で特に取り上げてしているのではないのですが、トピックスとして、これからも検討してまいりたいと思います。先ほど答弁いたしましたＨＥＡＲＴＳのスクールソーシャル・ワーカーが年間２,０００件を超える支援に動いているのは、いじめだけではなく、不登校等、全ての課題への支援を行っている数値を合わせたものです。","voiceIndex":63,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に、今言っていただいた教職員の方々の研修はものすごく重要であるので、ぜひ力を入れていただきたいと思います。図書館のところも、本に出合うことで、実際に体験しなくても理解できる大人の方はいっぱいいらっしゃるので、ぜひ図書の充実とか取組みをいろいろやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"その辺を見抜く力をどうしたらいいのかを伺っておきたいと思うし、これ以上、どこの行政区に住んでいても、そういうことで命を落とす子どもをつくってはいけないという思いで質問をしたいと思います。ですから、そういう方向性も含めて、また、そういうこども冒険ひろばへの評価も、この際、改めて伺いたいし、方向性も含めて、考え方を教えていただきたい。とりわけこの２点、よろしくお願いします。","respondent":"高山子ども育成課長","answer":"１点目の親育ち支援事業に関連しての対応とか認識の部分、記載の親育ち支援事業につきましては、こちらに書かせていただいたように、保護者の方々、親御さんの仲間づくりということで、乳幼児家庭の孤立化の防止や育児不安の解消が主たる目的ですので。","voiceIndex":77,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"今の子どもたちは、ゲームとかＩＴ機器を活用した遊び、集団で群れて遊ぶことが本当に体験的に少ないだけに、そういう場面をたくさん提供しないと、今の子どもたちに手足あるいは体全体を使った心身機能の発達は促せないわけですから、そこは重点施策として位置付けていただくくらいの迫力で取り組んでいただきたいと考えています。そのことは要望としてお伝えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"幾つかあるのですけれども、１点目は、５ページの組織のところ、先ほどの教育委員会と同じなのですが、ここの場合、非正規も入っています等と何も書いていないので、職員の配置は正規という捉え方でいいのかどうか。非正規の職員がどのくらいいらっしゃるのかもまとめて教えてください。１点目です。超過勤務のところで、先ほどと同じ月８０時間超えの職員が何人中何人いらっしゃるのかを教えてください。","respondent":"福島子ども未来部長","answer":"病欠についても同様でございまして、事務事業の内容についてご説明申し上げておりますので、同じように、超勤８０時間超えにつきましても、今のところ、この場では用意してございませんので、よろしくお願いいたします。","voiceIndex":80,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかの場所で伺うこととします。続いて、７６ページなのですけれども、園別の在籍状況という一覧表がありますが、ここで定員と在籍児の関係を１点。定員以上に子どもを入れている弾力化の考えを教えてください。これが１点です。この差が多分、不承諾の方だと思うのですけれども、そこから何を何人ずつ引くと、この１９人の待機児数になるのか、基本的なところを教えていただきたいと思います。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"ただ、一方、今後、待機児童対策で私立保育園をつくっておりますので、その辺で一定、公立保育園の定員弾力化をどこかで縮小を図っていくところは、課内でも検討課題に上がっておりますので、今後。不承諾数と待機児童数の関係ですけれども、不承諾数７０６人から転園希望の方、求職活動を休止された方、認可以外の保育施設に入られた方、特定の保育所のみを希望している方、育休を延長された方を除いて、待機児童１９名となります。","voiceIndex":82,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"数はいいです。後で。最初の園の状況を見て、多分、面積とか職員の配置の状況によってだと思うのですけれども、１年間を通して、最初の４月と同じなのですか。私の認識と違うので、そこをもう一回、お伺いしたい。６月１日現在の申請状況はどうなっているのかもあわせて教えてください。基本的なところを教えてほしいのと、私は、人手が足りないのではないかと思っているのですが、いかがでしょうか。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"定員と在籍の割合が少し上がるところは、委員、ご指摘のとおりだと思いますが、最終的に、２月、３月末のパーセンテージに関しては、ここ数年、大きく変わっていないと認識しております。６月の申請者数は、今、数を持っていません。ただ、６月１日現在で、ゼロ歳から２歳児の認可、認証を含めて、空きが１７５人ありますので、一定、申し込みがあっても対応できる体制にはなってあります。","voiceIndex":85,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そろそろまとめます。６月１日現在の数字は、多分、すぐわかると思うので、ぜひ、後で教えていただきたいと思います。指導検査なのですけれども、職員はどのくらい増えたのか教えていただきたい。これだけでもすごい大変だと思うので、ぜひ、率直にご意見を聞かせていただきたいし、増やさなければいけなかったら、強力に応援をいたしたいと思っていますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"３点目といたしましては、研修部門に園長ＯＢが６名いますので、外部委託でできるところは、その辺を進めて、園長ＯＢ６名を指導検査、巡回指導に回していくことで、私としては、かなり体制としては拡充したと考えております。","voiceIndex":89,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"済みません。６月１日のは後で教えていただけるのでしょうか。","respondent":"佐藤保育課長","answer":"わかりました。","voiceIndex":91,"id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、委員長の説明があったので、それは了解だと思うのですけれども、公園用地の中というところが、もう少し適切な土地がなかったのかと思っているのです。これは文教委員会ではなくて行財政改革特別委員会なのだろうと思うのですけれども、改めて、この機会なのでできたら教えていただきたいのが１つです。例えばバス停が前にあるとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-020"},{"speaker":"渡部委員","kind":"質問","question":"細かくではなくて、すごく大くくりで２点、申し上げします。１つが、これも大タイトルとして、どういう言い方がいいのかわからないのですが、健康の教育。健康に対して全般的に捉えた所管事務調査、細かいところはこれからまた正副委員長等で打ち合わせいただいたり、私どもも、限られた時間での発言となってしまったものですから、まだ具体性に乏しいところがあるのですが、そのような点で１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"今、渡部委員からもありました。心の部分等ありましたけれども、フィジカルな部分とがん教育。だから、品川区は市民課の中でということがありましたから、このあたりが現状どうかというところと、もう一つはプログラミング教育です。今までは量的な部分の緊急性があったわけですから、拡大、拡大ときた中で、平成３０年度初めの数字を見ても、当然、今後、一定程度の数の拡大は必要だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"私的には、１つは、先ほども事務事業概要の中で質問させていただいた学校の不登校の問題です。品川区は、そんなに増えていないとおっしゃっていたけれども、それでも小学校、中学校を合わせて２００人近い子どもがいろいろな状況で学校に行けない、あるいは、マイスクール等に通っている、そういう状況です。そういう中で子どもの自己肯定感をしっかり持てる教育はどうあったらいいのか。私はそう思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"意見","question":"２つになってしまうのですが、健康という意味では、心の健康に通じると思うのですが、性の多様性を認めていく教育。心の健康にも通じるし、医療機関とのかかわりもあるし、教育機関的なかかわりもあることなので。そういった意味で、子どもたちの居場所をきちんとつくっていく意味においては、私は、とても遅れている分野だと思うので、議員みずからが学んでいくことが大事ではないかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-024"},{"speaker":"石田（し）委員","kind":"提案","question":"一応、我が会派としては用意しましたが、基本的には正副委員長で検討していただければと思うので、まず、その点は伝えします。私どもの会派からは、１つは次世代教育について。もう一つは子育て支援についてで、特に在宅の子育て支援についてと子どもの貧困について、ネウボラについて、このようなものがいいのではないかと提案をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"意見","question":"正副委員長での整理ということで結構だと思います。コミュニティ・スクールの中でも、先ほども働き方との関連でお話しさせていただきましたが、外部の人材や団体を活用していただくときの、具体的に、例えば大阪市などでは、もう１,０００万円ぐらい学校につけてみたいなのがあったりしますので、コミュニティ・スクールの財政的な面で進んでいるところの研究をと思ったりしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"私は、１つ、２つ、自分の中では、先ほど所管事務調査を申し上げた中で考えていて、保育といいましょうか、先ほど泥にまみれてというようなプレイパークのお話もあったのです。去年でしょうか、私も不勉強なのですけれども、「森と自然の育ちと学び自治体ネットワーク」というのは県レベルだったのですが、鳥取、広島、長野連名で出されているのです。鳥取、広島、長野でやっていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-027"},{"speaker":"渡部委員","kind":"意見","question":"それは兵庫教育大学。まだ確実に追いかけてはいないので、大学院の研究がおもしろいことをやっていると思って見ていました。基本的には、行きたいところというよりも、必要なところを探していただいて、ある程度、正副委員長にお任せしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"本を読んでいたら出てきたので、ノーテレビ・ノーゲーム運動というのを村で取り組んでいるというのです。ですから、別に遠方でなくてもいいわけで、そういうところも取り上げていただいて、そういう教育行政を学んでいきたいと思っています。そのことによって読書がすごく進む、そういう取組みもしているというのです。だから、学ぶところはあると思いますので、検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"意見","question":"先ほど兵庫県という県名が出たのですが、兵庫県の教育委員会で、人権教育及び啓発に関する総合推進指針をつくったと思うのです。文部科学省から平成２７年に「性同一性障害に係る児童生徒に対するきめ細かな対応の実施等について」という通知が出ているのですが、これに沿って、結構、あちこちの県段階で、その先の具体化が進んでいるところがあるのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4942#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":53350,"voices":116}},{"id":"h30-20180611-5","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"総務委員会","time":"午後 １時００分～午後 ２時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"多分予算額は出せると思いますが、中には予算額を掲載することができないような内容もあると思うので、その辺をどう考えているのか。載せないなら載せない、載せるなら載せるということを統一されたほうがよいと思いますし、できれば最低、これぐらいかかっていますということを示すためにも予算額は、事務事業概要に載せるべきだと私は思っていますので、その辺をどうお考えかということが１点です。","respondent":"榎本総務部長、木村報道・プロモーション担当課長、中元広報広聴課長、小林施設整備課長","answer":"総務部の事務事業概要の内容に統一がとれていなくて済みません。できる限り予算額等は記載していきたいと考えています。積極的に情報を出されるところと、比較的そうでもないところ、運用状況を見まして、実際にいい事例だとかを、共有をしながら。専門相談、法律相談等ありますので、そちらにおつなぎしたということで解決という表現を使っておりますけれども、その実際の例につきましては。事務事業概要の９ページについては、今後、単位を千円で統一するようにいたします。","voiceIndex":62,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ただ、これはどうしてもいろいろな予算がかかわっているので、なかなか載せられないという部分があると思いますが、プレス発表には必ず全部予算額が出ているわけですから、やはりしっかりと予算額を載せていただきたいという思いがあります。デジタルサイネージは、おそらく今後、技術革新の中で汎用性がすごく出てくるような気がします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年、策定を行う長期基本計画と、「マイセルフ品川プラン」について伺いたいと思います。長期基本計画ですけれども、今年が最終年ということと、あわせて策定に向けた策定委員会が始まると伺っていますけれども、最終年に当たって残された課題は何か、どのように考えているのか伺いたいのと、策定に向けたポイントは何なのか、それぞれ説明を伺いたいと思います。","respondent":"大野計画担当課長","answer":"今回につきましても、人数につきましては未定となっていますけれども、参画をいただくといった方向で検討を進めているところです。","voiceIndex":68,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、長期基本計画の策定委員会がつくられると思いますけれども、議会を含め、多様な民意が反映するような構成にしていただきたいと要望しておきたいと思います。続いて、マイセルフ品川プランについてですけれども、３つの計画の中で、第５次男女共同参画のための品川区行動計画について、今年の３月に、第１６期品川区行動計画推進会議報告書が発表されまして、その提言を読ませていただきました。","respondent":"島袋人権啓発課長","answer":"教育委員会とも連携をとりつつ、事業を発展させていきたいと考えているところですし、また、策定委員会の中からもいろいろなご意見等が上がってくるかと思います。そちらを生かしながら計画に反映させていきたいと思っているところです。","voiceIndex":70,"id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"先ほどのいながわ委員のご質問に重なるところがあると思うのですが、１つは、表記の問題で、概要ですから、全体を網羅するというのは難しいのかと思うのですけれども、他課との連携事業一覧に、理由がある課とない課があって、今気がついたのは一部だけですけれども、そうなると相互に矛盾が出てきてしまう。それだけ教えてください。","respondent":"立木経理課長、品川財政課長、黒田人事課長","answer":"他課との連携の部分です。工事の部分とか、いろいろ関係しているところがあります。予算書と事務事業概要の金額の違いというところですけれども、どうしても予算書は事業別、科目別などに分けて出しているということ。そのほかに、例えば健康相談などメンタルヘルスというところでは、職員厚生係に看護師を配置していますので、そちらのほうにご相談いただきまして。済みません、ちょっと混乱しておりまして、先ほど、答弁で誤った回答をしてございました。","voiceIndex":72,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"事務事業概要に書いていないのは、ここのところ事例がなかったからと理解していいのでしょうか。ごめんなさい、よく理解できていないのですけれども、貸出についても経理課というふうに思ってよろしいのですか。それだけ教えてください。","respondent":"立木経理課長","answer":"貸出に関しましては、こちらのほうに記載がございませんが、特になかったということではございません。記載がないだけです。","voiceIndex":79,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"済みません、よろしくお願いします。やっぱり私たちが普通に読むと、売却と購入、借入と貸出が常にセットというか、同じところに表記されていると大変わかりやすいので、ぜひ検討をお願いします。で教えていただければと思います。","respondent":"伊藤委員長、山本情報推進課長","answer":"ほかになければ、以上で事務事業概要を終了いたします。１０月に第３回ワークショップとして、第２回のアイデアを実現するためのアプリ開発を行い、１１月に第４回としてアプリの実証実験を行う予定です。平成３１年２月には、成果発表会を開催する計画としております。","voiceIndex":83,"id":"exchange-007"}]},{"id":"topic-02","title":"平成３０年度オープンデータ推進事業の実施","agenda":"平成３０年度オープンデータ推進事業の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどのご説明の中で、オープンデータを活用して６種類の試作アプリが完成したとおっしゃいましたでしょうか。オープンデータの活用が進んでいるというお話ですけれども、その６種類の試作アプリは、それぞれどういう内容のものなのか、ご説明いただきたいと思います。","respondent":"山本情報推進課長","answer":"もう１つが、品川ショップディスカバリーといいまして、商店街の個人商店単位で、なかなか取り組みが行いにくい店舗の魅力的な情報を発信するツールです。","voiceIndex":88,"id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、月見橋の家が仮移転しているということでありますが、同和相談員など同和事業は廃止し、解同品川支部への総務部分室の貸出をやめ、月見橋の家は建て替え後、もとに戻さず、同和生活相談は特別扱いせずに、区民相談の各種相談事業での対応に変えるべきだと思うのですけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"工事の移転後に、またもとの場所に戻るのが、今後の移転の計画です。今のところ聞いてありますのは、仮移転からまたもとに戻るという計画であるというふうに聞いております。","voiceIndex":95,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"人権啓発課が報告をするのであれば、内容は同和事業に関することにすべきだと私は思います。私が伺ったのは、戻ってくるときに、同和生活相談は、特別扱いせずに区民相談の各種相談事業での対応に変えるべきだと思うのですけれども、いかがでしょうか。","respondent":"榎本総務部長","answer":"今のところ、その考えはございません。前あったところに戻す予定です。","voiceIndex":98,"id":"exchange-010"},{"speaker":"中塚委員","kind":"提案","question":"先ほど、事務事業概要の中でも少し触れましたけれども、やはり今年は作成する行政計画として、長期基本計画とマイセルフ品川がありますので、その２つを提案したいと思います。もちろん策定委員会がそれぞれの進み具合の中で区から議会に報告がされるということは既に説明がありますけれども、ぜひ議論を深めていきたいと思い提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"そういう依頼があったので、委員会として今年も行う必要があるのかなと思いながらも、以前にも申しましたけれども、毎年確認をする必要性がそこまであるのかという疑問を持っております。それだけ述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"ただ、この時期は、台風があります。仮にどこか地方に視察に行くにしても、やはりそういう災害に見舞われる可能性が高い時期に、あえて行くことはないのではないかと、今回は見送ってもいいのではないかと思うのですが、皆さん、どう思われますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"この間、あまり総務委員会としては、私自身も含めて深められていなかったと思うので提案したいのですけれども、ＬＧＢＴなどセクシュアルマイノリティについてです。先ほども男女共同参画などの中で、品川区もいろいろ事業をやっていますとご説明がありましたけれども、品川区議会、そして委員会としても議論を深めて理解を深められたらと思いますので、提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-014"},{"speaker":"須貝委員","kind":"提案","question":"これから武蔵小山にタワーマンションが３棟建つ。だから、そういうところについて、我々が、近くで視察調査するということが、やはりすごく大事なことだと思うので、所管事務調査もそういうふうに提案しようと思うのです。大都市にある品川区の地域性を考えたら、これから大きな問題になりつつあることに対して、先々考えていくべきではないかと思うので、そういう視察を提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-015"},{"speaker":"吉田委員","kind":"提案","question":"新城市は市長提案なので、どうなのかなということはありますが、飯綱町は議長が提案してこの制度をつくったということです。新城市は課題や批判が出ているということも聞きましたし、そういう課題も含めて、ある程度、実施されているところの例を視察してみたいなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"提案","question":"やはり所管事務調査の調査項目を１８日までにというお話がありましたけれども、それと視察というのは極力絡めたほうがよろしいのでしょうか。全くかけ離れてもしようがないのかなという思いもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"意見","question":"そうですね。より深堀りをしていくか、それとも限られた期間の中で、あるテーマについてみんなで共有していくという考え方があるということで、また後日、意見を出しますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"所管事務調査との関係ですけれども、私はできれば所管事務調査を深める立場で現地を確認するというのが、この間の委員会活動の姿だったし、そこは基本に置くべきなのかと思います。ただ、テーマや場所によって、さまざま今、委員のご意見やご希望もありますから、そこは正副で調整をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-019"},{"speaker":"新妻副委員長","kind":"意見","question":"視察先といたしましては、ＬＧＢＴの取り組みが進んでいるところ、既にパートナーシップ制度が実質進んでいるところ、どこというふうに例示しませんけれども、いろいろありますが、那覇市もそうですし、札幌市もそうですし、そういうところを１つどうかなと思います。","respondent":"伊藤委員長","answer":"改めまして、これまで行ってきました行政視察の調査項目や視察先、それから今年度の所管事務調査項目、それから、今お話があったさまざまな指摘、そういうことも含めて、さまざまな観点から検討させていただきまして。","voiceIndex":116,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2108#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":35920,"voices":118}},{"id":"h30-20180612-14","meetingId":"h30-cm06","date":"2018年6月12日","dateIso":"2018-06-12","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"横山委員","kind":"質問","question":"何点かお伺いをします。都および近隣市の児童相談所へ職員を派遣というふうにあるのですけれども、近隣市というのはどのあたりに派遣をされていくということなのでしょうか。続いて、先行３区についてですが、大分状況が進んでいるかと思うのですけれども、そういったほかの区の状況をどういった形で品川区は把握されているのか教えてください。","respondent":"二ノ宮児童相談所移管担当課長","answer":"４点目の先行３区の協議状況ということなのですけれども、実際の詳細をなかなかつまびらかに知ることはできないのですが、特別区長会を通じての情報だと、大体先行３区は、今まで東京都と具体的に四。","voiceIndex":36,"id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"今後の委員会の進め方になってしまうのですけれども、昨年度、私は、こちらの委員会で児童相談所に視察で伺ったかと思うのですが、視察後にお時間がどうしてもとれなかったということで、議論ができませんでした。もう１点、これも要望なのですけれども、東京都の児童相談所。品川児童相談所が、品川区と大田区と目黒区が担当地域になっているかと思います。これは要望で終わらせていただきます。","respondent":"中塚委員長","answer":"委員会運営に関するご要望については、しっかりと正副で調整して進めていきたいと思いますので、よろしくお願いいたします。ほかに、ご質疑ありますでしょうか。","voiceIndex":38,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"それから一応地域の環境等を考えますと、もっと都心である東京都内のところに視察に行っていろいろ取り組みを聞いたほうがいいのではと思うのですが、なぜ、東京都内は視察を受け入れてくれなかったのですか。この金沢市、石川県のほうへ行く。福岡市、熊本市に行くということは、それなりの何か別の利点があったのですか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"熊本市の視察を本年度の実施予定なのですけれども、現在熊本市は政令指定都市になってありますが、実は児童相談所設置市に２年程なっておりまして、そういった経験があるというところも含めて熊本市としました。","voiceIndex":40,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"児童相談所を、身近な基礎自治体に移管して充実させることは大切なことだと考えています。改めて、区としてはなぜ児童相談所の移管を積極的に進めたいのか伺いたいと思います。区が運営することで区民にとってどんなサービスの向上をもたらすと考えていらっしゃるのか伺いたいと思います。そういったところについて都と協議はしていらっしゃるのか伺いたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"１点目の、なぜ区で児童相談所をつくることになったというところで、現時点でいわゆる東京都と各特別区でのいわゆる児童相談行政の二重行政というのが行われているという点と、基礎自治体で児童相談所を持つ意味は何かというところがあるのですけれども。","voiceIndex":44,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。場所については、検討中ということなのですけれども、先日、常任委員会でも具体的な場所が示されまして、建設委員会では、赤線の部分というのが、現在かいじゅう公園と言われていますけれども、１体の恐竜にかかってしまうという話もありました。なぜここを候補地として区は考えたのかを伺いたいというふうに思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"これまで、区内における用地の検討を行ってきたのですけれども、具体的には３点理由がございまして、これはもう正直に申し上げれば整備に必要な敷地面積を確保できる土地というのは、正直区内にほかにはあまり見込めないのではないかという点が１点目。","voiceIndex":46,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"こういった住民合意の仕組みというのをつくる必要があるのではないかと思うのですけれども、いかがでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"当然、ご指摘にもありますとおり、公園の敷地を活用するということになりますので、公園の利用者や住民の方に対して区へのご理解というのは丁寧に得ていく必要があると思っておりまして、こちらは機会を捉えて丁寧に説明していくという対応を考えております。","voiceIndex":48,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"今年度後半から基本設計もということなのですけれども、この場所ありきというふうに最初から決定するというよりは、私が伺ったのは、そういった場所のあり方などについて住民を含めた検討組織、そういう仕組みをつくって進めていくということが、結果はどうあれ必要だと思っていますので、ぜひつくったほうがいいと思うのでということを伺ったのですが、いかがでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"重ねてのお答えになってしまうのですけれども、まずは丁寧に説明するという所から始めてまいりたいと考えています。","voiceIndex":50,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"少し所管が違うところもあったということですが、まだ具体的に住民への説明などのスケジュール感はまだ今の段階では見えていないということでよろしいでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"言葉足らずで申し訳ございません。現時点で例えば何月に何をするというところまでは、まだ具体的な日程は決まっていない状況です。","voiceIndex":55,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問","question":"移管したときには一時保護所をつくろうとされたのか。それともまた検討会の中の流れでやっぱり必要というふうになって決めてきたことなのか。その辺の一時保護所についてと、平成２９年度、平成３０年度されてきた市や県の視察を踏まえて品川区にとっていわゆる利点となる点として何を持ち帰ってきたのか。どういったことが必要だなと感じて今移管の準備をされているのか、その点をお伺いしたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"２点目のお尋ねは、なかなか一言でご説明申し上げるの難しいのですけれども、まず金沢市は品川区とも人口規模も似通っている点もございまして、まず、一時保護業務というのは、当然区で今まで全くやっていなかった業務になりますので、どういった形の施設で。","voiceIndex":58,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"あるいは情報提供があったときに、それをどう処理をして、どういう人たちが動いていくのか、今回いろいろと報道されていることも検証していくということもありますので、そうしたことも含めて、今後この品川区だからこそここまで守れているのだということをつくっていくためにも、ぜひ視察をされるところだとか、研究をしているところで調査研究を重ねご準備をしていただきたいと思いますが。","respondent":"二ノ宮児童相談所移管担当課長","answer":"委員のご指摘も含めてしっかり対応してまいりたいと考えております。","voiceIndex":60,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、先ほども近くに都の児童相談所があるということを利点というふうに挙げられていましたけれども、やはりこの施設ができて「はい、即充実」というわけではないと思いますので、そういった連携といいますか。こういった体制をどう構築していくのかというのも建設とともに考える。もちろん考えていらっしゃるところだと思うのですけれども、そこについて今の段階でどう考えられているのか教えてください。","respondent":"二ノ宮児童相談所移管担当課長","answer":"先ほどもご紹介させていただいた東京都や横浜市への職員派遣を通じて、実際今、動いている業務の流れを習熟していただき、区に持ち帰っていただくというようなこともやりながら、人材育成を図っていきたいと考えております。","voiceIndex":63,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと職員の雇用形態もすごく重要だと思うのですが、心理面をケアする職員はすごく非常勤が多く、この品川区でも他区でもそうなのですが、身近な心理士の方から話を聞くと、正規雇用の枠がなかなかないという声もあるので、こうした施設での雇用形態も重要だと思うのですが、その辺は今どのようにお考えでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"お尋ねありました件ですけれども、児童相談所につきましては配置基準が決まっておりまして、委員が例に出されたような非常勤の方ばかりというようなことは現時点では想定していないところです。","voiceIndex":65,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですけれども、私はもう少し住民参加を位置づけた土地の利用ということを進めていただきたいなと思っているのです。これだけの土地を区は買おうとしています。これについて、どのような使い方を皆さん望んでいますかという問いを区民に投げているのです。そして説明会をしたもとでどういった施設をつくっていくかということをぜひ検討していただきたいなと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"今後具体的なもう少し施設の内容というものが見えたところで、形はどういう形にするかは別にしましても、説明会的なものも考えてはありますので、そういった意味ではさまざまなご意見を伺いながら進めたいと思っています。","voiceIndex":72,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"提案","question":"全く意見は聞いていないというふうには思っていませんし、区としての提案というのも必要なのだけれども、それをもみ合わせるというのですか。さらには地元だけではなくて、やはり広く多くの方が、区民が知って、そして、提案や意見を言える。具体的に見えてきたらというところもありましたので、ぜひ、今の段階からそういった住民参加を進めていっていただきたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。私は総合庁舎のことについて、質問します。効率的・経済的な改修方法という説明なのですけれども、これは平成元年ですか。３．２億かけてエレベーターの改修をやっております。この部品をかえるだけでも大丈夫だという検証が出た上で工事をやると思うのですけれども、本体の部分、かごの部分も実際に点検をして、安全確認がとれているのか。それを１点お聞きしたいと思います。","respondent":"立木経理課長","answer":"さらなる安全向上という面では、今回の更新によりさらにプラスされるというような形になっております。","voiceIndex":76,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。最後に、定期的に汚水とか雑排水は高圧洗浄をかけているのかどうか。それだけ教えていただきたいと思います。","respondent":"立木経理課長","answer":"委員おっしゃるとおり、そのような清掃を行ってあります。","voiceIndex":80,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、品川区が５,０００平米の取得、候補地ということで、交渉中ということでしたけれども、需要を考えればさらに取得していただきたいなというふうに考えています。国有地も取得したいという考えがあるので、そうした中で区は５,０００平米にとどまっているというような旨の説明があったと思うのです。こういう問題意識があるのですけれども、いかがでしょうかというのが１つです。","respondent":"柏原企画調整課長、立木経理課長","answer":"ただそれが例えば５,０００平米が１０,０００平米になるといったところはなかなか東京都の公園の計画であったりとかというところもありますので、なかなか一気にそういったところまでというのは、難しいかなと思ってあります。建物自体も、先ほど申し上げましたが適切なメンテナンスを行っており、例えば雑排水管、それから給排水等の設備機器を更新することによりまして、躯体と同程度それをきちんと延ばしていくことができるというふうに考えております。","voiceIndex":83,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、基準をクリアしたということで、林試の森のほうは切実な住民要望がたくさんあります。私たちとしましては、こうした手法というのは、自治体としてはやるべきではないと考えておりますけれども、いかがでしょうかというのが１点です。世田谷区では繰り返し繰り返し報告会、説明会も行われておりましたので、そういったものの実施を求めていきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですので、いきなり再開発の手法で物事を進めるというよりは、そういう土地の状況があるということを考えたときには、それは１つの考え方というところでそういったところを考えながら、検討素材の１つに上げるというのは考え方としてあると申し上げたところですので。","voiceIndex":86,"id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"多くの区民が使う施設でもありますし、防災拠点にもなるということですので、他自治体を参考にすることがあればということでしたけれども、非常に世田谷区の手法というのは、ほんとうに住民自治を大切にした、つくられた後も非常に愛される。そして、大変利用されるような施設になっていくような手法だと私は思っておりますので、ぜひ大いに参考にしていただければなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"企画調整課長の説明は、全くそのとおりでございまして、例えばこれだけの広大な敷地。それは、また後ほど進め方の中で正副のほうにお願いすることもあるんですが、これ例えばひろまち保育園というのは５年の約束で確か動いているはず。当然、その後の活用をどうしていくかというとき、例えばＪＲ東日本が何か行うというときには、そこには当然区が入っていないとおかしい話だと私たちは思います。","respondent":"柏原企画調整課長","answer":"ですので、こういったところを鑑みますと、ＪＲ東日本のほうの開発なり動きが出たときには、当然ながら区としても何らかの形で動きを合わせたりだとか、話をしたりだとかというのは当然出てこようかと思いますので、こういったものについても。","voiceIndex":90,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後のためにも１点まずわからないところといいますか。本来の趣旨を活かせるように、自治体の返礼品競争の過熱防止ですとか、富裕層優遇とならないよう仕組みの見直しなどの改善は必要だと思っておりまして、国にもそういったことを求めていくべきだと思うのですけれども、やっていらっしゃることとあわせて、区の考えを伺わせていただければと思います。","respondent":"品川財政課長、伊東税務課長","answer":"資料１番を見ていただきますと、平成２７年度に、人口の計算の配分を１２.５％か１５％にしている。それから従業員の配分を１２.５％から１０％に下げている。もちろん品川区は人口よりも従業員人口のほうが圧倒的に多いのです。どうしても都市部から地方に対しての寄附が多いという状況の中で、影響額として１５億円と書かせていただいておりますけれども、流出しているという状況で、もう少し緩やかに増えていくのかなというような気もしないではないところです。","voiceIndex":96,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"さらにこのふるさと納税を行っているわけですから、そっちでせっかく地方に配分しているのに、さらに配分するということは、私は根本的におかしいのかなと。大都市であるさまざまな自治体は、国に要望を出していますけれども、結局これに対する、ふるさと納税の返礼品に対して何ら罰則がないし、いろいろ政令というのですか。総務省から出ているけれども、全然実行されていかない。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"すみません。２点ほど、お伺いをします。","respondent":"伊東税務課長","answer":"平成３０年度の影響額ということで、これは予算的なところでの１５億円というふうに見ているところです。それで、区民への減収に伴って影響が出るということの周知ですけれども、現時点では積極的にこれだけの金額が出るという具体的な数字を使っての周知等はしていない状況です。","voiceIndex":102,"id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"国のほうも行っていると思いますし、特別区で連携していろいろと活動も行っていただいておりますけれども、品川区としてもきちんと制度のＰＲとどれだけ流出によっての影響が出るのかということを区民の方に区民感覚で伝えていただけるようなことを検討していただきたいと思いますし、これからこの行財政改革特別委員会のほうでも議論のほう進めていけたらなと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"となると、この新公会計制度というのは、企業の手法を導入するけれども、行政の特質も考慮すべきだよということなので、どういうふうに、どんな形になっていくのか、狙いや目的が何なのかを教えていただきたいのですが。","respondent":"齋藤会計管理者","answer":"その意味で言うと、民間と同じ様には議論できない。そういった中で活用を図っていきたい。ただ、活用のあり方については、まだ始まったばかりでありますけれども、各自治体も今検討をしているところであります。","voiceIndex":109,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"要は今度ははっきりこれだけ予算使って、これだけ使わなかった。だからこれだけ残った。それは一般企業、民間から見ればそれは収益ですよね。それで、また償却できないものもあるからそこは重々お考えくださいということなのでしょうけれども、我々が見ていくと、なぜお金がこれだけ残った。だからそういう収支を今度より明確に我々が見えるようになるというふうな考え方でよろしいのでしょうか。","respondent":"齋藤会計管理者","answer":"若干ご意見と相違している部分もあるかもしれませんけれども、お聞きのところにつきましては、委員のおっしゃるとおりです。","voiceIndex":112,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"資料の２の新公会計制度導入の意義の(2)のところですけれども、部や事業を単位に資産や負債、フルコストを把握することができると書かれておりますが、それは結局どういう効果につながっていくのかというのが気になってはいるのです。少し心配するのが、コストがわかると。その辺の疑問や心配については、どのような見解を区はお持ちでしょうか。","respondent":"齋藤会計管理者","answer":"総務省のほうから、各自治体がこういった財務諸表を、新公会計制度に基づいてつくりなさいというのは、委員がご指摘されたとおり、部や課、あるいは事業ごとに財源構成や利用者コスト、こういったものを理解して。","voiceIndex":115,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"説明責任を果たすというのはあるかもしれないのですけれども、それを議論の素地にするというのはいいのですが、自治体ですから住民福祉の向上が目的です。ですから、そこら辺はこの新公会計制度を導入するに当たっては、地方自治体の基本的な役割をしっかり見定めてちゃんと忘れないで議論していくことが必要だというふうに思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"１点だけ。Skype For Businessの検証を教育委員会と学校間で行っていくということなんですけれども、こちら、モデル実施した後なのですが、全庁的に取り入れていくというようなお考えですとか、今後のスケジュール感ですとかそういったところの見通しを教えていただけたらと思います。","respondent":"山本情報推進課長","answer":"その効果を見て、今後全庁展開をするかを判断していきたいというふうに思っておりますので、今後のスケジュールについては、まだ決まっていないのが現状です。","voiceIndex":122,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"内部事務の効率化に限ってはこういうことだと思うのですが、区民の個人情報さまざま多岐にわたってある中で、そういう情報などはソフトを更新したときには全部打ち直して入力するようになるのですか。それともそのままそっくり移すことができるのですか。その辺教えていただけますか。","respondent":"山本情報推進課長","answer":"機器を更新した場合の個人情報等の授受の方法なのですけれども、手打ち等ではございませんで、システム間でバッチ処理という形で情報をシステム同士で流して処理をするという形をとっております。","voiceIndex":124,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"その辺がわかるような、わからないような感じなので、要するにどういうことなのか教えてください。","respondent":"山本情報推進課長","answer":"経費に関しては、保守の費用という形で、サーバを仮想化しない場合は物理的サーバが何台もあるという形になりますけれども、仮想化をしますと、１台の物理的なサーバの上に、仮想で乗っているという形になりますので。","voiceIndex":128,"id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"何となくイメージができました。いわゆる区民サービスの電子化というのは、例えば直接職員の方が手書きしていたものが入力をされるものなのか、それとも仕事上がさらに効率化を図るため機能アップしていくものか、その辺はどうなのですか。","respondent":"山本情報推進課長","answer":"今回ご案内したＩＣＴ活用の取り組みに関しては、業務の効率化というところになっておりますので、入力作業自体は入力として残っている作業になりますので、その分に関しては職員の負担等は変わらないのですけれども、あくまで生産性が向上するという形になりますので。","voiceIndex":130,"id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"要望として、例えば区民が高齢者の方と、また役所に来なれていない方が、区役所の中でさまざまな手続をするに当たっては、非常に困難があるといいますか、難しいところもある中で、例えば今年の２月から、船橋市では書かない窓口というのがスタートをしておりまして、例えば転居者の方が、転入届、転居届を出す際に間違いが多くあるということで、あえて紙に書くのではなくて。","respondent":"柏原企画調整課長","answer":"ほかにも日進月歩でＡＩの技術だとかロボットの技術とかいろいろ進んでいます。そういったところを研究しながら、いかに区民サービスの向上につなげられるかというのは、常に研究をしながら行政として仕事を進めていきたいというふうに思ってあります。","voiceIndex":133,"id":"exchange-033"},{"speaker":"松永委員","kind":"質問・要望","question":"私から１点だけ、まず参考までに教えていただきたいのですけれども、ペーパレス会議システムの利活用の検証についてなのですが、ペーパレス会議システムを導入というのは、全庁的に行われるのかなと思うのですけれども、そうした中で費用に関してどのぐらい年間コストが減るのかという想定なのですが、もしわかりましたら教えていただきたいと思います。","respondent":"山本情報推進課長","answer":"使用できる職員が５０名という形をとっております。一部始めておりまして、効果を見まして来年度以降全庁展開するか検討していきたいというふうに考えております。費用の件なのですけれども、実際に、システムを導入することによって、効果といいますか。","voiceIndex":136,"id":"exchange-034"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"調査事項概要の中でいろいろ出させていただいたものと重複するかもしれませんが、私たち自民党・子ども未来といたしまして、今回実はこの調査事項概要の１、２、３番を出させていただいています。でないと比較ができないというところがあります。ただ、近いところでどこかと申し上げますと、横須賀市なのですよね。とりわけこの１、２、３に関しては、思うところございましたので、発言させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"そのタイミングは非常に大事かなと。それから、国有地等については、これは今さらなのですけれども、土地の取得がまだ明確に、最終的に決まっていない２つ、３つですか。それはもう用途については各常任委員会の当然所管になるのだよねというところの仕切りは、改めてといいますか、今まで議論したかなと不安になっていて、確認だけさせていただきたいと思います。","respondent":"中塚委員長","answer":"国有地についてですけれども、当然購入と用途というのは一体のものになりますので、ここでしっかりと議論していきたいと思いますが、一方で用途が決まった暁には、常任委員会のほうでその後の議論を深めていくものと思いますので。","voiceIndex":143,"id":"exchange-036"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほどのＩＣＴの活用の件なのですけれども、これも「など」というのも、私たちはＡＩを含めて今後どういうふうな形で展開していくのかということも含めて書かせていただきました。基礎自治体のあり方の児童相談所移管についてですけれども、移管にあたり、都や国から、補助金等があるのかどうかというのも調べていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-037"},{"speaker":"須貝委員","kind":"意見","question":"ただ、さっき児童相談所の話もありましたけれども、現実論それぞれ児童相談所のそこの場所、地域においても職員も相当忙しいというお話も聞いていますし、多忙であるということで、果たして我々が行っていいものかどうなのかというのはわかりませんけれども、相手方の状況もありますので、これから区として立ち上げていくならば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"未利用国有地に関してですけれども、先ほどの質疑の中でも石田ちひろ委員も言ったのですが、用途は、もちろんこの区民代表である議会、この委員会で議論されるというのは当然だと思うのですが、スケジュールなどの関係もやはりあると思うので、相手もあることですし、タイミングを適切に図って、区民の意見をどう反映させていくかという仕組みというのですか。そういったことも含めて議論できるようなあり方。","respondent":"中塚委員長","answer":"さまざまご意見ありがとうございました。ご意見につきましては、正副で十分調整させていただき、可能な限り今後の委員会運営に活かしてまいりたいと考えております。その他何かありますでしょうか。","voiceIndex":149,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":39380,"voices":151}},{"id":"h30-20180613-18","meetingId":"h30-cm06","date":"2018年6月13日","dateIso":"2018-06-13","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"もしそういう人がいるのであれば、例えばどういう人を何人ぐらいお願いしている、ただというのもあるのかもしれないけれども、そういう全体を捉えてこういうのをつくるときに、どういう体制で区が今取り組んで、事前から、それから事後まで継続して品川区の中でそういうのを維持しながら、例えばマイナーなものからメジャーになれるまで品川区が中心にやっていけるよというぐらいのものがつくれるほうが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと、ホッケー協会やビーチバレーボールのほうも含めまして、そちらの協会の会長・副会長も含めまして、いつも情報交換をしながら事業は実施していて、先を見据えてやっているです。","voiceIndex":29,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"それはそれでいいのですけれども、私の感覚は、やはりやれているところは、どういう雇用契約と言うか、マンパワーだと思っているのです。最後は電通というのは誰でもわかっていて、こういうことをやれるのは電通しかないと、どういう事業者の方に聞いても電通しかないと言うのですけれども、そこで、では誰が来ているのというのが非常に問われるよということが言われます。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、委員ご指摘のとおり、やはりいろいろな項目、いろいろな仕事が錯綜していまして、一定程度、こちらからアプローチを投げかけないと返ってこないところもありますので、そこはきちんと私が言ったり、部長のほうから言っていただいたりしながら。","voiceIndex":31,"id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"オリンピック・パラリンピックを品川区内から盛り上げるため、品川区にゆかりのある３名のアスリートをスポーツ大使に任命ということで、これはうちの会派からスポーツ大使もそうですし、観光大使もそうですし、人材登用ということで盛んに主張してきましたので、非常にうれしく思うのですけれども、品川区にゆかりのある３名を今回任命されるわけですけれども、品川区にゆかりのあるアスリート、まだまだ。","respondent":"辻オリンピック・パラリンピック準備課長、池田スポーツ推進課長","answer":"大使という形での任命はこの３名だけとなる予定です。しかしながら、ほかにもオリンピアンとかスポーツ選手がいるということであれば、それは個別にでも情報をいただければ、ご一緒できるときがあるとまたいいかなとは思います。事業の内容です。こちらは開始年度順に記載をしています。今、ご説明しましたように、１番目としまして障害者スポーツ教室を行いました。","voiceIndex":33,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"４番のその他のところなのですけれども、今、荏原第六中学校校庭を日本代表選手たちの練習会場に提供しているということでした。具体的に教えてほしいのですけれども、なぜ荏原第六中学校が選ばれたのかということと、練習会場として週どのくらい貸しているのかなど、そういう詳細を教えてください。","respondent":"池田スポーツ推進課長","answer":"利用があまり競合していない曜日などを全部調べまして、たまたま荏原第六中学校が人工芝の工事を行った後でして、ちょうど利用する団体がなかったという点、それと西小山駅と学校との立地条件、とても駅から近いという条件がございまして。","voiceIndex":38,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"２点伺います。１点は、私も大変不勉強なので、パラリンピックの２２競技が、できればどういう競技でどういうルールがあるかという、何かそういう資料、もちろん１個１個調べればわかるのだろうけれども、せっかくなら学びたいなというのが、委員長にもお願いなのかわからないけれども、それは学んでおくべき。ブラインドサッカー協会と。１回見てくださいと言うので、水元体育館。非常に微妙ですよね。","respondent":"池田スポーツ推進課長","answer":"もう１つの、少し人気のないようなスポーツが、今後区のほうでの応援ですけれども、これは確かに会場が一番大事なことですので、会場と相談というのはやはり私どもスポーツの担当課、それから実際に会場がある教育委員会等と、そして実際によく使われているスポーツクラブ。","voiceIndex":41,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう部分があったりするので、今度も今おっしゃったバレーボールのようなものもあると、健常者がどうのというのもあるから、そういうのも含めて少し知ることができるとありがたいかなと、これは委員長にもお願いしておいて、勉強するときに何かそういうことがあれば、我々が応援していくにしても何にしても、いろいろな形がとれるのではないかなと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今年初めてやるというフライングディスク教室というのがありますけれども、これをやることになった経緯を教えていただければと思います。合わせてこの障害者スポーツチャレンジデーというのも今年から始めるということでこれも先ほどからお話もありますけれども、障害の有無に関係なく楽しめるイベントということで、どういった形になっていくのか伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"内容につきましてもどなたでもできるようなボッチャとかフライングディスクとか、そういったものを考えているところです。","voiceIndex":45,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、障害者スポーツチャレンジデーのほうは体験的なものを行っていくということでよろしいですかね。","respondent":"池田スポーツ推進課長","answer":"基本的には体験していただいて、スポーツを楽しんでいただくということ。は１つ、車いすテニスにつきましては、きちんとしたプレーヤーをお呼びしましてエキシビションマッチを考えているところではあります。","voiceIndex":47,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"新しくこの２つのものが始まるということで、先ほどもありましたけれども、大井地区でスポーツ教室がなかったということで、やはりいろいろな場所で行っていくことで障害者の方のスポーツをやる環境を整えていくというのも必要だと思いますので、さらに、障害を持っている方でもスポーツが気軽にできるよう進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"先ほどの荏原第六中学校のお話の続きなのですけれども、協定が結ばれたのが２０１６年４月ということだったのですけれども、いつから練習会場として提供しているのかということを聞きたいのと、あとは芝の使い心地について選手の方たちはどんな感想を持っているかというのと、ほかの学校の人工芝とこちらの人工芝、荏原第六中学校の人工芝はブラインドサッカー用にそのような人工芝を選んでいるのか。","respondent":"池田スポーツ推進課長","answer":"実際に選手たちが活動しての感想ですけれども、とても静かな環境で芝もきれいでよいと、そしてなおかつ駅から中学校まで曲がり角が１、２カ所しかない、信号も１個しかないと、これも安全に来られるということで評判は大変いいところです。","voiceIndex":50,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"いつというのが抜けていたのですが、いつごろかわからないですかね。練習会場を提供しているのかというのを。","respondent":"池田スポーツ推進課長、辻オリンピック・パラリンピック準備課長","answer":"実際には、パートナーシップ協定を結んだ翌年の８月からになります。事業概要につきましては、下に(1)、(2)、(3)と載せているところですが、現在１３事業にとどまっておりますので、今年度は文化観光課ともさらに連携をして盛り上げていく予定になっております。","voiceIndex":52,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"確認","question":"そこで、周りで文化プログラムなり、イベントでもコンサートでも、そういう文化的なものを、周りにどれだけ会場がとれるか別だけれども、基本的には組織委員会がそういうふうに考えてくるのだろうけれども、組織委員会としてあまりそれをやらないとするならば、区がその場所をお借りして、そういう区民参加のイベントなりそういうものを、私はやるのだろうと信じているけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それともう１点、その後の継続のお話です。確かに補助金を出しても次にどうなるのという話ですとなかなか厳しい面もあると思います。","voiceIndex":57,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお願いだけしておきます。もしお考えがあれば教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"地続きで、品川区民、大田区民にとっては、どちらがやるかというのは関係なく、そこが盛り上がることが一番大事なことですので、今後大田区とは連携をとりながら、ホッケー協会も交えていろいろな事業を展開していきたいと思います。","voiceIndex":59,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"提案","question":"区民委員会の今回の委員会の中で、品川区文化芸術フォーラムの開催についてという報告があったようなのですけれども、これを見ると、東京２０２０オリンピック・パラリンピック競技大会開催を契機として、オール品川で文化芸術の振興に取り組むためのキックオフイベントとするということで、品川区内のさまざまな関連の文化芸術団体であるとか、芸術家の方、文化人の方を結集していくという。","respondent":"立川文化観光課長","answer":"３つ目ですが、品川区の文化芸術の方向性の検討ということで、２０２０年までの取り組みを踏まえ、文化芸術にかかるプラン等の策定等を視野に入れたレガシーの活用方針の検討を行う。この３つを柱として協議会を進めていく考えです。","voiceIndex":62,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのときには、なかなかアスリートのようにああいうスポーツの場では活躍はできなくても、文化プログラムであれば皆が、例えば一体感を持って、そのとき例示してあったのは、一斉にその時間に同じ曲を皆でピアノで弾くとか、それは１つの例示ですけれども、そういったことも品川区で取り組んでいただければと、ぜひお願いしたいと思うのですが、その辺についてご意見を伺いたいと思います。","respondent":"立川文化観光課長","answer":"文化芸術振興協議会の設置目的、また文化プログラムの実施につきましては、文化芸術の裾野を広げ、多くの区民が文化芸術に触れ親しむ機会をつくり、東京２０２０大会に向けた機運の醸成を図るですので、実際にどういう内容になるかは今後協議していくことになりますが。","voiceIndex":64,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"しながわ文化プログラムについて１３事業だという説明が先ほどあったのですけれども、そことの関係と、明日実施される文化芸術振興協議会の今後のいろいろな検討との関係がどういうふうにリンクしていくのかがわからないので教えていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"わりと個別だったのですけれども、今後は文化観光課の文化芸術振興協議会と文化芸術フォーラムのほうと連携をしながら、もう少し大きな枠組みでこの文化プログラムというのを広げていくということで、今までは個別だったのですけれども。","voiceIndex":66,"id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"そういう点で、今のご説明だと区が後援する事業だというところが、あまりよくわからないので、とにかく１３事業も含めて、この４番目に書いてあるしながわ文化プログラムについては大枠しか書いていないので、それがこれからもう少し具体化されていくのだろうと思うのですけれども、そのあたりを少し説明いただきながら、文化振興、それから区民に定着していける品川区としての文化への支援。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"先ほどご説明申し上げました１３事業というのは、去年立ち上げまして手探り状態で始めたところもございました。","voiceIndex":68,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"大枠は理解しました。したがって、オリンピックが終わって終わりだよということにはもちろんしないという思いだと思いますけれども、改めてその点もお願いとし、大事に育成をしていただきたいと。あらゆるそういう点でのさまざまな各界の方々のお知恵とか、力を借りながら育てていただけるようにお願いしたいということも申し上げておきたいと思います。","respondent":"熊谷指導課長","answer":"続きまして、ブラインドサッカー、ホッケー、ビーチバレーボール、区内開催そして応援３競技体験教室の実施ですけれども、既に平成２８年度から本区の開催競技であるブラインドサッカーとホッケー、そして応援競技であるビーチバレーボールの体験教室を行ってまいりまして。","voiceIndex":70,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"質問します。前にも確認したのですけれども、ようい、ドン！の授業が今現在３５時間程度確保されていましたけれども、要はオリンピック後はこの３５時間というのが確保されるのでしょうかということが１点。ですから、区内の小学校・中学校の子どもたちに対して３競技だけでいいのかというところの確認をしたいのですが、まずその２つの確認をお願いいたします。","respondent":"熊谷指導課長","answer":"ゴールボール、それからパラリンピック競技の陸上競技であったり、車いすバスケ、こういったものも取り組んでいるところですので、３競技を中心にほかのオリンピック・パラリンピックの種目にも各学校で取り組んでいるところです。","voiceIndex":74,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"特に３競技だけに限らず拡大していくことも必要だと考えていますので、検討をよろしくお願いいたします。ですから、独自教材「ようい、ドン！しながわ」もこれからずっと使い続けていくと思うので、例えばオリンピックは東京の後もずっと続いていくわけではないですか。ですから、そういうこともこの「ようい、ドン！しながわ」の中で取り組んでいくべきだと思うのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"しながわ」を残せるかということについては、検討していきたいと思っているのですけれども、冊子という形で配布するのがいいのか、また、別の形で子どもたちに伝えるのがいいのか、それにつきましては引き続き検討してまいりたいと考えています。","voiceIndex":76,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"この「ようい、ドン！しながわ」の内容が、私個人の思いですけれども、やはりこれから子どもたちにずっと続けて伝えていってほしいと思うのです。だからこそ、この２０２０年大会の詳細についてはできれば品川区の子どもたちに引き続き伝えていっていただくような、どういう教材になるかは別問題としても、その精神は引き継いでいってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"品川区としてのオリンピック・パラリンピック教育の目標というものが、３点にわたってここに掲げられておりますけれども、これはオリンピック・パラリンピック教育、東京都全体としてもこういったものに取り組んでいるということだと思うのですけれども、東京都にも似たような目標のようなものがあるのかどうかということと、あるとすればそれと品川区の目標との関係性と言うか。","respondent":"熊谷指導課長","answer":"ただ、この重点的に育てる資質のところで言い方を変えておりまして、東京都はボランティアマインド、障害者理解、スポーツ志向、日本人としての自覚と誇り、豊かな国際感覚という５つ、同じ５つなのですが。","voiceIndex":80,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"そういう意味では、東京都とほぼ同じという中で、品川区独自の取り組みというか、先ほども質疑がありましたけれども、区独自教材でありますとか、あるいはアワード校についても品川区は大変にたくさんの学校がアワード校として選ばれているというところでの１つの成果と言うか、これまでの推進の１つの結果というものが出てきているわけですけれども、今後に向けて。","respondent":"熊谷指導課長","answer":"一番これを取り組んでいきたいというところは、子どもたちへのオリンピック・パラリンピック教育を通して心を育てていくということはとても重要だと思っているのですが、子どもたちを通して。","voiceIndex":82,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"幾つか質問させてください。研修を受けた教員の受け持つ学年などは特に指定などがあったのでしょうか。それとも、どのような学年の先生でも、どの教員でも参加ができるという形だったのかというのと、あとは参加された人数などの詳細も教えていただきたいのと、あとはスクールアクション「もったいない」大作戦の給食の残菜を減らす取り組みについて具体的に教えてください。","respondent":"熊谷指導課長","answer":"自分たちでできるだけ残菜をなくすにはどうしようということで、好き嫌いをなくそうとか、子どもたちが考えて取り組んでいるところです。","voiceIndex":85,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"オリンピック・パラリンピック学習、「ようい、ドン！保護者からそういう声が上がっていて、ずっと給食が残ったままの机、その状況というのはどうなのかなという声があるのですけれども、その辺はどうお考えでしょうか。","respondent":"いながわ委員長、熊谷指導課長","answer":"田中委員、大変申しわけないのですが、概要説明ですので、そこまで深く行かずに、それであれば、その他でご提案をしていただいて、正副で検討してまいりたいと思いますので、答えられる範囲でご答弁いただければと思います。後段の給食の残菜の件ですけれども、これはオリンピック・パラリンピック教育とは関係なく、先生方の指導だと思いますが、ただ、そういった指導につきましては、私どものほうでもそうした子どもたちの負担となる指導にならないよう。","voiceIndex":87,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"友好都市もそうなのだけれども。私は、ここはスポーツ交流も含めて非常に大切だと思っているのだけれども、教育委員会としてはどう捉えられているのかというのをまずお聞きしたい。私は非常にいいことだと思っているけれども、そのことだけをまず聞きたい。","respondent":"熊谷指導課長","answer":"私自身も、教育委員会としましても、姉妹都市・友好都市との連携、そして交流と、非常に重要だと考えています。「ようい、ドン！","voiceIndex":91,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"」というものが始まって、オリンピックを契機にと言ったらスポーツ交流をこういうふうにしていくべきで、もっと強化していこう、終わった後も中学生の子どもたちがそれを目標にできるようなものにしていこうというような機運が私が見ている限りまるっきりないように見えていて、何か先細りのように見えてしようがないので、その辺を、せっかくこういう契機があったのだから。","respondent":"柏原企画調整課長","answer":"相手の事情といったところもありますので、現在の国際交流の考え方というのは大切にしながらも、今後のあり方、それから相手の動向とか考えも鑑みながら、どのような形がよろしいかというのは引き続き検討、考えていかなければいけないだろうというところです。","voiceIndex":93,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"意見","question":"それがスポーツであっても、オークランドみたいな形でもいいけれども、それは非常にいいことだと思っているので、やはりそういうものを今の中で、今のところ、相手があることというのは非常にわかって言っているつもりなのだけれども、それで先細りと思っているのだけれども、そうしたら相手を変えるぐらいのことだって模索していいと私は思っていて、中学生にそういうことを体験していただくということが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"今日は概要説明ということなので、今後の議論の参考に、まず確認で、オリンピアン・パラリンピアン等との交流、それから今回、昨年度ブラインドサッカーの国際大会があって、そこでボールパーソン、選手誘導、ここには海外とのことを言っていますけれども、している中で、これまで海外のオリンピック・パラリンピックの選手と学校、地域を含めて何か交流の機会、先ほど冒頭のさまざまな取り組み。","respondent":"熊谷指導課長","answer":"は今年度、外国人のオリンピアンが延山小学校に来る予定で、これは都から派遣になりますので、どなたがいらっしゃるか、まだ未定ですけれども、わかり次第ご連絡したいと考えています。","voiceIndex":97,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"今のワイナイナさんについても都からの派遣ですか。","respondent":"熊谷指導課長","answer":"都からの派遣です。","voiceIndex":99,"id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"そうすると、概要なので、今、都からの派遣ということになりましたが、予算の関係などもあるのかも含めてなのですけれども、例えば、今後ずっと、今自治体によっては事前キャンプなどの関係もあるとは思うのですけれども、例えば海外の、なおかつパラリンピアンになると、日本のブラインドサッカーというのは品川区内で結構交流があって、障害のある方でもスポーツをしてすごいね。","respondent":"熊谷指導課長、安藤文化スポーツ振興部長","answer":"今年度も引き続き海外の選手との交流、選手が事前に東京都を訪ねて、さまざまな練習試合等を行っていく際には、子どもたちを参加させたいと考えているところです。情報ですけれども、２年前にブラインドサッカーのブラジルの選手が品川区に来て練習をしたり、品川歴史館に行って茶道文化協会の方々がお茶をたててお茶を振る舞って、そこでまた皆様が品川音頭をかけて私も踊りましたけれども。","voiceIndex":101,"id":"exchange-031"},{"speaker":"つる委員","kind":"提案","question":"ということは、これまでもいろいろやっていただいている中で、あとの残り２年の中でも今後そういう企画、検討、当然相手との交渉も含めてあるということで理解をしましたので、また次の機会にいろいろ提案していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-032"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"お伺いしたいのですけれども、ここの調査日程（案）にも載っているスポル品川大井町のことで聞きたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特にパラリンピックと文化というところの象徴的なアール・ブリュット展等の視察もぜひご検討いただければと思いますが、いかがでしょうか。","respondent":"いながわ委員長","answer":"ご意見として賜らせていただき、正副でしっかりと協議して検討していきたいと思いますので、また次の委員会でご報告させていただきたいと思います。","voiceIndex":112,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"意見","question":"は区長選挙の絡みで、もしかするとこの委員会がそもそもこの時期にないのかなということもあるかもしれないです。私もイベント自体の日程がいつなのかというのを把握していないので、秋ごろと聞いたのですけれども、もし無理のない範囲で可能であるならばということで、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"意見","question":"この文化プログラムのオリンピック・パラリンピック推進特別委員会の部分の文化プログラムと、厚生委員会の部分の障害者の部分と、これは去年はまさに厚生委員会では所管事務調査に基づいて視察まで行って、いろいろそういう障害者の文化、もうご存じだからあれだけれども、そういうものもあるので、これはどうするというのが、今のこちらを中心に行くと、今のでオーケーだし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"このスポル品川大井町のことなのですけれども、突然報道で知ったというか、区との関係性と言うか、そのあたりを少し教えてほしいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"そうなのですね。確かオリンピックの期間だけ営業、２０２０年には閉まる予定ということなのですけれども、その辺などで、このオリンピック・パラリンピック推進特別委員会とも何か関係と言うか、情報が入ってきているのかと思って今伺ったのですけれども、では、ないということでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-038"},{"speaker":"本多委員","kind":"質問・要望","question":"国籍問わず、年齢問わず、性別問わず、障害のある方もない方も、誰でも応募できるわけで、その辺で１人でも多くの区民の方が聖火ランナー、聖火リレーに参画できるために情報提供をいただきたいし、区がどこまでものを言えるかというのも正副でぜひ検討していただければと思います。","respondent":"いながわ委員長","answer":"改めて正副で検討をしていきたいと思いますので、よろしくお願いいたします。","voiceIndex":126,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"すみません。先ほどのことです。スポル品川大井町のことで、いつ知ったかだけ、具体的に教えてほしいのですけれども。その会見の後ということ、いつということを教えてください。","respondent":"池田スポーツ推進課長","answer":"それが私の一番最初に知った内容です。その前には、地域の方には説明があったかもしれませんけれども、私が正式に得た情報というのはこの５月９日ということになります。","voiceIndex":128,"id":"exchange-040"},{"speaker":"田中委員","kind":"確認","question":"私がと言うか、区が把握したのはいつかということを今聞いていて、区として把握したのもこのＪＲの発表の後ということになるのか確認させてください。","respondent":"池田スポーツ推進課長","answer":"それは実際には４月ごろにもう地域のほうにＪＲから説明がありましたので、そこからは知っております。","voiceIndex":130,"id":"exchange-041"},{"speaker":"田中委員","kind":"確認","question":"その地域への説明があったのが２０１８年、今年の４月ということで、その後、そのときに地域の方からの情報を得ていたということでの確認です。いいですか。","respondent":"池田スポーツ推進課長","answer":"そのとおりです。","voiceIndex":132,"id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"組織委員会と検討事項の話を去年もしたのだけれども、もちろんやるのはいいのだけれども、もう少し何か、無理かもしれないけれども地域のこととかを含めて、もう少し情報開示をしてほしいと言うか、我々の要望したものに対してしっかりした返答をある程度してもらわないと、ただ我々がこういう要望を出したものを聞き置くだけで、あとは新聞紙上にぱーんと出てきて、ああ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":41425,"voices":139}},{"id":"h30-20180615-10","meetingId":"h30-cm06","date":"2018年6月15日","dateIso":"2018-06-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"始まる前に一つ確認したいのですが、よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":2,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"先日、５月２９日の臨時会におきまして、議長に対する不信任動議が可決されました。改めて議長にお伺いしたいのですが、約７０年の歴史を持つ品川区議会初めてのことです。改めて議会の可決についての重みをどう考えているかということをお伺いしたいのですが、いかがでしょうか。","respondent":"松澤議長","answer":"重みでしょうか。","voiceIndex":4,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"議決の重みについては重く感じていらっしゃるかもしれませんけれども、まあ重く感じていらっしゃるということですね。我々としては、はっきりとしたものを求めたのですけれども、そのことに対する見解はいかがですか。松澤議長のもとでは、議会は開けませんということを求めたわけでありますけれども、そのことに関しての思いはいかがでしょうか。","respondent":"松澤議長","answer":"議会が開けませんということでしょうか。","voiceIndex":10,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"改めて確認しますけれども、議会で可決された内容ですよ。そのことを重く感じていらっしゃる。このことに対して、議長の今の発言としては、開いてくれればありがたい。他人事ではないですか。議会で可決された内容ですよ。","respondent":"松澤議長","answer":"可決された内容をはっきり言っていただかないと、私としては答えようがありません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"５月２９日の品川区議会の臨時会において、松澤利行議長に対する不信任動議が可決されました。このことについて可決された重みは重いと感じていらっしゃる。それに対して、私としては速やかに辞任を求めたのですけれども、そのことに対してのお考えはいかがでしょうか。","respondent":"松澤議長","answer":"今初めて不信任動議のことについて言われたので、その前段、議会をどう思うかというのは、私はこれと一緒になっているのかどうかわかりませんでしたのでお答えをいたしませんでした。今不信任動議の話が出ましたのでお答えをしたいと思います。","voiceIndex":16,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"法的な拘束力がないことは我々も理解はしております。ただ、今の話を聞くと、議長の不信任が可決されたという議会意思よりも、議長個人の意思が優先されると感じるのですよ。だから、法的な拘束力がないことは理解しますけれども、議会の公人としての立場からどうお考えなのですか。","respondent":"松澤議長","answer":"この新聞を見る限り、動議は法的拘束力はないというふうにも書かれております。任期は４年、議会の許可を得て辞職することはできるとしており、議長がみずから辞意を表明しない限り任期は４年ということですので、私は辞意を表明はいたしません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"提案","question":"あのとき、私たち自民党・子ども未来会派として動議を提案し、読み上げさせていただきました。そのことに関することも含めて議会で可決されました。このことに対して、議長はどうお考えなのですか、改めてお伺いします。","respondent":"松澤議長","answer":"私はその場に同席しておりませんので、控室で場内の様子をテレビで見ておりました。その様子は承知しておりますが、今述べましたとおり、何回言われましても第１０８条の中で、議長がみずから辞意を表明しない限り任期は４年と書かれております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これも混乱を招いている。その混乱を招いている。その重みを考えるのであれば、ご自分から辞表を書く、これが我々は普通の流れだと思って、今伊藤委員も質問をしているわけでありまして、その態度、それをしっかり辞表を出す、これを鮮明にしていただきたいということを今言っているわけでありまして、それについてのお答えをしていただきたい。こういうところについての明確なお答えをしていただきたい。","respondent":"松澤議長","answer":"地方自治法第１０８条では、「普通地方公共団体の議会の議長及び副議長は、議会の許可を得て辞職することができる」としており、議長がみずから辞意を表明しない限り、任期は４年というふうに新聞記事にも書かれております。私も法律を調べましたら、そのとおりでございました。","voiceIndex":24,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の話は、さっきから伊藤委員が言って、今私が話したことの答弁にはなっていないと思いますので、しっかりもう一回答弁をしていただきたい。","respondent":"松澤議長","answer":"私も法律書を見ましたが、そのとおりでございました。私は、みずから辞意を表明する気はございません。４年間、４年間といいますけれども、残り１年間しっかりと議長として職責を全うしてまいりたいと思います。","voiceIndex":26,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"改めて伺います。では、議決の重みはどこに行ってしまったのですか。その中で、品川区政始まって以来のこういうことが起きている。それは副議長進行でやっていただいたということも事実起きているわけでありまして、そういうことを踏まえて、そのときの責任、またその後の辞意を、辞表を書く、こういうことについての答弁をしっかりしていただきたいと思う。","respondent":"松澤議長","answer":"先ほど重く感じるのかということは、前段のときにお答えをしています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういうことが今後も起きる可能性があるとするならば、そこに議決が起きたわけですから、それに対応する、そこは明確に私は辞表を書くべきだと考えていますが、それについての副議長進行を含めて、そういうとき、こういう混乱が起きた、それはどうお考えなのか、また辞表をそれに対応して書く、これが私は３２年間議員をお務めになってきた、また区政史上初めてこういうことが起きた。","respondent":"松澤議長","answer":"何回も同じ質問をされており、オウム返しになりますが、地方自治法第１０８条では、「普通地方公共団体の議会の議長及び副議長は、議会の許可を得て辞職することができる」としており、議長がみずから辞意を表明しない限り、任期は４年と書かれております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"確認","question":"確認だけしますが、先ほど来、我々の質問に対して明確なお答えがない。議事録ももちろんこれは出るわけでありますけれども、誰が見ても質問していることと今答弁をされていることは、全く違うことをお答えになっている。混乱を招いたこと、副議長進行でやってきたこと、議長進行では、それはできませんと言ったこと、そういうことの責任はどうお考えなのですか、そこをお聞かせ願いたい。","respondent":"松澤議長","answer":"地方自治法第１０８条では、「普通地方公共団体の議会の議長及び副議長は、議会の許可を得て辞職することができる」としており、議長がみずから辞意を表明しない限り、任期は４年、私は残る任期をしっかりと議会正常化に向けて頑張ってまいりたいと思います。","voiceIndex":32,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"全く議論になっていないので。我々も質問をさせていただいていて、こんな状況が続くのはいいことではないと考えています。それだけはお伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"私も関連して発言をします。５月２９日の本会議で不信任動議を我々会派から出しました。そういう議決が出たということで、我々の会派はこのように主張していますので、ぜひほかの会派からもそれぞれ議決の重みということについて意見をいただければというふうに思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"ああいった形で不信任動議が提出をされたということで、今自民党のほうから議決の重みということについて他会派の意見を伺いたいと、このような申し出がありましたので、私どもは内容を検討させていただきまして、これは賛成も反対もできない、このように判断をさせていただきまして、棄権という態度をとらせていただきました。それが全てです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"共産党としては、この議会運営委員会の中でも申し上げたとおり、松澤議長に対しての不信任動議に対して反対をしました。それに対して、議会の中で１９人ということで、ぎりぎり可決ということになりましたけれども、それを踏まえた上で松澤議長がこの法律に基づいて辞任をしないという表明をしているということに対しては、それを尊重すべきだというのが私たち共産党の考え方です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"本多委員からお尋ねがあったので、そのことに対してお答えしますが、我々としては、今なぜ議決がそうやってされた中で議長が辞意を表明されないのか、このまま議長の職を続けていくというふうにおっしゃっておりますが、なぜ議長をそのまま続けるおつもりなのか、まずそのお気持ちを、ぜひ意思を表明していただきたいのと、議決がされて、今正直、議会が混乱をしております。","respondent":"松澤議長","answer":"残された１年弱の任期ですけれども、しっかりと頑張ってまいりたいと思っているところです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、法的根拠といいますが、私が聞いたのは、なぜ議決がされたにもかかわらず、お辞めにならないのか、お辞めにならないのであれば、しっかりとその意思をどのように、では、この議会の健全化も含めて自分の中で意思を持っているのかという、その意思の確認をしているわけであって、しっかりと頑張りますと言われても、このまま、最後に法的根拠をおっしゃって、拘束力がないから続けるのだというのは。","respondent":"松澤議長","answer":"おっしゃったとおり、今の幹事長の理解で、いいと思います。これから正常化に向けては、各幹事長とお話をしながら正常化に向けて頑張ってまいりたいと思っています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"今お話があって、議決をしました。２週間何をされていたのですか。では、この２週間何もしていないのですかと逆にお伺いします。一番自民党と今こういう混乱を招いているのであれば、幹事長等にアプローチがあってもよかったと思いますが、我々はないと思って今理解をしておりますが、これからまたやっていきますというお話だけれども、では今までの２週間どうされていたのですか、伺います。","respondent":"松澤議長","answer":"第一会派の幹事長に話すべきではないかというお話を今いただきましたけれども、おとなしく向こうからアプローチするまで待っていなさいというお言葉もいただいておりますので、私はそちらのほうを尊重したところです。","voiceIndex":45,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"それがわかっていらっしゃって混乱を招いているのであれば、今法的なこと、議長を私は辞めない、そうおっしゃっているのは構いませんが、政情的に正常化、健全化するには、ご自身から動いてやる、これが私は議長職だと思いますが、この２週間やらない、それは待っていたほうがいいというほかからの意見があったからというお話だけれども、そのほかの意見をどう捉えて、どうしてお待ちになっていたのか。","respondent":"松澤議長","answer":"今お話を伺いましたので、これから…。おかしいですか。〔「おかしいです」と呼ぶ者あり〕自民党の幹事長に正式に申し入れて、お話をする会を開いていきたいというふうに思っているところです。","voiceIndex":47,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほども言いましたけれども、こういうふうに混乱を招いたり、皆さんから言われた中で、はい、これから次は幹事長の皆さんといろいろ話をして、それで頑張っていきます、いろいろな会をしていきます、毎回その話で、いつもそういう話をここでされるのは構いませんが、それが一つも履行されていないということだけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-021"}]},{"id":"topic-02","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"その裏側を見ていただければと思います。(1)特別養護老人ホーム開設のための用地確保、(2)高齢者施設で働く介護従事者の処遇改善、(3)外国人介護人材確保のための規制緩和というところで、なかなか要望はしていますが、前に進んでいないというところで要望させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"その差し押さえの交付金制度の廃止を求める要望ということで、差し押さえをやればやるほど交付金はとれますということで、１００件以上やれば８００万円、３００件以上で１,５００万円、５００件以上差し押さえをすると３,０００万円の補助金が出るという仕組みなのですけれども、こういう形でやはり区民を本当に追い詰めることになるので、この交付金を廃止してほしいという要望を提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々の会派からは、４点お出しをさせていただきました。待機児童解消に向けた保育施策等のさらなる充実ですが、要望内容に書いてあるとおりであります。ここでちょっと書き漏れといいますか、児童相談所を含めて、これはしっかりと要望していかなければいけないと思っていますので、その点ここにちょっと書き漏れておりますが、それも含めた権限と財源の移譲であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"提案","question":"我が会派は、今回この要望を提出期限までに提出することを差し控えました。その中でこれを議論していく。そういう意味合いがあって、もちろん我々もいろいろ会派の中で議論をさせていただいたので、項目等のことはありますが、改めて我々が提案をするというのはルール違反になるので、それはしません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-025"},{"speaker":"若林副委員長","kind":"質問","question":"したがって、会派としてと問われれば、これまでの議会運営委員会の流れの中で、この議会運営委員会の中でしっかりと議論をして、最終的に議長会に出す、これは紛れもなく時の議長がやられるわけですから、そういう意味でいけば、現議長が出されるわけですから、今までどおり議会運営委員会の中でしっかりと議論をした上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"提案","question":"今回私たちは提案をさせていただきましたが、前回、いつもと同じ流れという受けとめ方でしていますし、提案をした後、議会運営委員会で、議論をこれからもすると思います。そういった意味において、今までどおり議長に最終的にはお任せしてよろしいかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜなら、議会が正常な状況ではない中、慣例というものは基本的には通じないものでありますので、我々としては、この異常な状態を何とかクリアするべく、しかしながら一方で、しっかり要望はしていかなければいけないといった中で、この議会運営委員会の場で議論をし、そして判断をしていくのが今の区議会の中ではベストな判断なのかなというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の各会派から出た意見としては、もちろん議会運営委員会の中でしっかり議論するというふうなことは大事なことですし、それは当然やるべきだけれども、最終的には議長という今までの流れでいいのではないかというところのほうが多いわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ああ、そういうことなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-030"},{"speaker":"横山委員","kind":"意見","question":"先ほど石田しんご委員のほうからお話がありましたけれども、児童相談所も含めて権限と財源の移譲をということで、こちらは今のタイミングで必ず品川区としても入れていくべきだと考えておりますので、ぜひお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうしないと、２３区共通で出していくわけですから、もし用地の確保をというのであれば、明確に都有地なり、国有地なりをやはりしっかり各区に向かって、そういうのをやってくれというのも一つだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかも２０２０年には実施に移したいというふうに言われている問題なので、いよいよ迫ってきている中では、これは本当に羽田に最も近い品川区としては、全会一致で出した意見書の中身に沿ったもので、今回２会派で出していますけれども、ぜひ羽田新ルート問題についての要望というのは出していきたいと強く要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"羽田は、それこそ全会一致でやったものについては、前回出したのだよ。〔「前々回」と呼ぶ者あり〕前々回か。前回、前々回に出したのだよね。ただ、〔「ここでは出していないです。意見書で言っているだけです」と呼ぶ者あり〕いやいや、違う、議長会要望で。〔「たぶん出していると思う」と呼ぶ者あり〕１回出したではないか。１回出したの。そうしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１回出したと思う。間違ったらごめんなさい。私は出したと思っていて、ごめんなさい、ちょっと正確でなかったら謝ります。出したと思っているけれども、２３区要望、特別区要望としては、そのときははねられた。賛同する区が少ないというか、少なくてはねられた。たしか、それは出したこともあるし、というのが私の記憶、間違っていたらごめんなさい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、落下物となれば、この間の熊本もルートから７kmも離れたところに落ちたというふうなところでは、やはり全区にかかる問題だというふうなところになってきているし、都心の、本当にこの都心のルートですから、やはり２３区共通の課題に私は値するのではないかと思いますので、ぜひ、そういった意味では、ちょっと皆さんの全体の認識も、２３区の全体の認識もだんだん変わってきて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは、どこかで我々も議決をして、落下物とかそういうことがあるのであれば、それぐらいはちゃんと、落下物とかいろいろ連携してしっかりやってくれというぐらいの、それはやはりちゃんと区民に理解を求めるような形でしっかりやってくれというぐらいは、私はあってもいいような気がするけれどもな。それは、はねられるかどうかはわからないけれども、それはあってもいいと思うよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その資産価値の低下ということについては、行財政改革特別委員会の中でいろいろ議論があって、ちょっとこれを取り上げるかどうかというところ、ここの部分ですね、これ全体を取り上げる、取り上げないはちょっと置いといて、これは全く一緒ではないということ、これはちょっと確認をさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それはちょっと追加させていただいた部分なので、だから、一番なのは、全会一致で意見書については一致しているので、そこの部分というのであれば、たぶん全会一致というところでできるのではないかと思いますので、私はそれでいいと思います。〔「そこは抜いてもいいということですか」と呼ぶ者あり〕そうです。私は抜いてもかまいません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":21535,"voices":102}},{"id":"h30-20180627-10","meetingId":"h30-cm06","date":"2018年6月27日","dateIso":"2018-06-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"突然でどういうふうに判断したらいいかよくわからないのですけれども、委員長にお聞きしたいのですが、今までもテレビ撮影とかが頭撮りで入ったことというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ちょっとそこら辺のところが。今までどおりということだったので、今までの事例がどういうふうになっていたのかを。今日なぜそういうふうにテレビとかが入るのかというのがよくわからなかったので。そういう部分が……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"ちょっとその発言は違っていて、私が申し上げたのは、今までは写真撮影は慣例として頭撮りは認めていたと。それに準じて結構ではないのですかと申し上げたのです。今までどおりとは言っておりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"私の記憶する限り、いろいろ事前の話があったときに、廊下で委員会室に入る撮影は許可したことがあると記憶しています。委員会に入ったときには写真撮影、もちろん録音もあったと記憶しています。こういう形で今日テレビクルーも入っているということであれば、それはやはり冒頭で写真と同様にその場面を許可してはどうかということを言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私たちとしては、写真撮影とかも別に冒頭に限らずに、開かれた議会というところでいつでも写真撮影は許可すべきだという立場にしておりますので、テレビ撮影もそういう形で言えば許可をしてもいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-005"}]},{"id":"topic-02","title":"平成３０年第２回定例会","agenda":"平成３０年第２回定例会","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"審議に入る前に確認したいことがありまして、質問いたします。松澤議長に対してでありますけれども、平成３０年５月２９日品川区議会臨時会本会議において議長に対する不信任動議が可決されました。前回の議運でも聞きましたけれども、改めて議長にこの議決のことをどう感じているかお聞かせください。お願いをいたします。","respondent":"松澤議長","answer":"しかしながら、私といたしましては、その不信任動議に至る理由が私は何も不信任動議提出に当たらないと考えていますので、私は残る任期、しっかりと議会改革に向けて頑張っていきたいと思っているところです。","voiceIndex":31,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、議長としては、つまり議会で示された意思があります。このことについて、ご自分の意向としてはその内容は十分相応しくないと思っていらっしゃるということですよね。とすれば、公人、公の立場としての、議長の立場としてのお考えはどうでしょうかということを改めてお伺いいたします。議長としての立場をどうお考えなのですか。","respondent":"松澤議長","answer":"今私が申し述べたことの繰り返しになりますけれども、私はその理由というものが果たして議長解任決議にふさわしいのかどうか、大変に疑問に思っておりますので、しっかりと残る任期、議長として頑張ってまいりたいと思います。","voiceIndex":33,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"解任決議は出しておりませんので、改めて訂正をお願いいたします。それから、今の話を聞いて改めて思うのですけれども、議長の思いとしては、品川区議会が公的な立場で決めた議決よりも、自分のお考えが上だということなのでしょうか。改めてお聞かせください。お願いいたします。","respondent":"松澤議長","answer":"先ほど申し述べさせていただきました。私はその理由そのものが私にとっては何でこれが議長不信任に当たるのかということを大変に疑問に感じておりますので、残る期間しっかりと議長として頑張ってまいりたいと思っているところです。","voiceIndex":35,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"議長の思いはわかるところもありますけれども、ただ、議決した背景には品川区議会議員の過半数が賛成した事実もあるわけでありますから、やはりその重みといいましょうか、品川区議会で、公的な場において議決されたことに対して改めて公人の立場として、どうなのでしょうか。改めてお聞かせください。お願いいたします。","respondent":"松澤議長","answer":"何回も繰り返しになりますけれども、議決というものを私は議会人として重く感じておりますけれども、その議決された理由そのものが私にとっては大変に不本意なものであり、それが議長の不信任に至るものではないと感じておりますので。","voiceIndex":37,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"確認","question":"つまり、議長の意思としては、我々が議会で示して可決されたあの内容については承服できないと。その理由で自分は議長は辞めないとお考えなのでしょうか。そこだけ確認をお願いいたします。","respondent":"松澤議長","answer":"いろいろ私も弁明いたしましたけれども、どう考えてもそれが議長不信任動議に足る問題ではないと考えておりますので、議会意思として通ったということは重く受けとめますけれども、議長としてはしっかりと残る任期、頑張ってまいりたいと考えています。","voiceIndex":39,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"確認","question":"幾つか確認をします。今、議決は重く受けとめられているというご発言であります。それでご本人、今確認ですけれども、値しないということは、ご自身が今まで不信任動議が２度も出て今度は可決をされているわけでありますけれども、ここに至るまで、その理由が不信任に値しないとご本人はそうお考えだと。それをまず２つ目伺います。そのことによって、信頼関係が今崩壊をしてこういう形になっている。","respondent":"松澤議長","answer":"何を言っても、議長、辞めろ、辞めろの一点張りでは何も信頼関係が構築できないだろうと思っていますし、自民党除名だ、今度は自民党の支部も除名だ、都連に対して除名だという、いわれもないことを言われることに対しては。","voiceIndex":41,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それ以降も議運があり、またこれを聞くのは議運の中では２度目ですけれども、こういう形でまた我々もこういうふうにお聞きをしなくてはならない。それを、全くそういうこともなく唐突に出されたとおっしゃっていましたけれども、そこら辺の経緯はどうお考えになっているのかということも改めて伺いたいと思います。","respondent":"松澤議長","answer":"一番最後の、「唐突に」というのは、まさに私はそう感じているところです。それと、約束を反故にするのはどうかということを言われましたけれども、どういう約束が反故されたのか。改めてこちらのほうからお聞きしたいと思います。","voiceIndex":43,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つ１つ伺います。それがいきなり不信任動議が出たのは唐突とおっしゃるけれども、そこら辺のところの交渉をずっといろいろな形でやってきた、自民党の幹事長がそういう交渉をされてきたことについてはどうお考えで、それは交渉したけれどもそんなの不信任動議が出るとは思わなくて余りに唐突だとおっしゃるのか、そこら辺の点を改めてお伺いします。","respondent":"松澤議長","answer":"今いろいろ聞きましたけれども、約束、何が約束なのかというのを私は改めて聞いている。やはりそこを今おっしゃっていただかないと話が進まないです。","voiceIndex":49,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"消防団長もその消防団の荏原の団長であれば荏原の責任者になる、それを兼務することは、我々自民党の中ではそれはご自身も定年が１年後にあるのでというのであれば、では１年後に議長をされてもいいのではないですか、そういう話もさせていただいたけれども、ご本人は今やりたいのだというお話があったから、それでは１年任期はあるけれども、ここで団長を辞めてくださいと、それが条件ですよと。","respondent":"松澤議長","answer":"ありがとうございました。長々とお話を伺わせていただきました。１点目、消防団長に関してですが、私は辞めるつもりでそのようなお話をいたしました。それは確かです。しかし、５月３日に筆頭副団長が倒れまして、後任の団長の選出が全く大変に難しくなってまいりました。","voiceIndex":51,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうことがあって、我々との信頼関係が、我々が発言したことではない、ご自身が辞めると、辞めるにはどうしたらいいのだ、そういうことをお考えになるのに、我々のほうが辞めるにはどうしたらいいのだということを指導しなければいけない議長なのですか。そういうことをお聞きしたい。１期１年、２期２年の話もご自身がされて、除名なったからその約束は全部反故。〔「それは違う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"私がしゃべっているので。それはもう全部反故にするのであれば、それは構わないけれども、反故にされたという事実はあるわけですね。ご自身の発言で我々がやって、その中で我々も推薦をさせていただいた責任はある。混乱を招いたその後、それも含めて、ではどういうことを行動されたのか。それであるならば、これからまたやりますと。それに対してどうお考えかということを、最後伺ってやめます。","respondent":"松澤議長","answer":"ちょっと資料を広げますけれどもよろしいでしょうか。","voiceIndex":54,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"提案","question":"それについても、今また別の話をされているけれども、政務活動費なのか何なのか、それは別のところでいろいろなあり方検討会、この前の西本議員の話のときもさせていただいたけれども、それはそれできちんとそれなら議会としていろいろな対応をとって。","respondent":"松澤議長","answer":"今、政務活動費にかかわるあり方検討会というお話がございました。この件につきましても、幹事長にあり方検討会、そういう話が議運で出たので検討したいと思うがどうでしょうかというお話はさせていただきました。","voiceIndex":58,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"こういう混乱を招いている中で、幹事長からそういう発言もあった。それは、ではここまで第三者委員会は何をどうしようと思われていたのか。何もないわけなかった。こういうことがあって今日ご説明があるということなので、それはそれでいいですが、それを急に対応をされた。これだけ混乱を招いた中で、では改めてやりますよって、それをいまさら言うことかなというのは申し伝えておきます。","respondent":"渡部委員長","answer":"後ほど議長を指名して、先ほど今日話すということをおっしゃったので、相当詳しい説明があると思いますので。","voiceIndex":63,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回の議運でも４０分以上かけてやったのではないでしょうか。それを全く同じこういうふうな形で出されるということに対して、私はこういうふうなやり方はやめていただきたいと申し上げたいと思います。それをさらに同じこういうふうな形でこの場に持ち出して、これだけ、今日だってもう１時間近くですよ、同じことの繰り返しをやるということはぜひやめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"提案","question":"何度もやっていて、我々もこのことに関して時間を費やすのは正直勘弁してほしいなと思いますが、前回も我々から質問をさせていただいて、その回答がはっきりとした明確な回答を示していただいていないので、改めてここでお聞きをしますが、まず１点は、議決がされて、しかしながら議長はそのまま議長の職を全うしていきたいと言っている中で。","respondent":"松澤議長","answer":"難しい問題をいただきました。１回目、その後どのようにしたのかということですけれども、大変に難しい答えだと思います。その間、私は議長の就任パーティーを行ったのですが、それも自民党の方に皆さん反故にされました。","voiceIndex":68,"id":"exchange-020"},{"speaker":"石田（し）委員","kind":"提案","question":"いわゆる不信任動議が出される前の議運でも私はいろいろと議長に対して意思確認も含めてこの場で質問させていただいて、我々の判断材料の一つとしてその機会の場をこの場で議長に与えていたわけであります。これは３回目です。１問目にその質問をさせていただきました。３点目の提案も含めてですが、質問に関してもそういった提案を受けてなるほどなとは思いましたが、今そのことに対してやるつもりはないと。","respondent":"松澤議長","answer":"何と言ったらいいのでしょうか、答えは一つだと考えています。議長というものは議会を代表する立場。そういうような意味では、不信任動議がたびたび出されてそのたびに議会が混乱するのでは、正常な議会運営、正常な判断ができなくなってしまう。","voiceIndex":70,"id":"exchange-021"},{"speaker":"石田（し）委員","kind":"提案","question":"なので提案をさせていただきましたが、一度お辞めになって新たに信任を問うべきではないか。なので、ぜひそこはお考えをいただければなと思います。これを私は再三議長には質問をし、お話もさせていただきましたが、今日も結局のところ何のお話もいただいておりませんので、このまま正常化されることはないのではないかなと非常に心配でありますが、最後に意見として述べします。","respondent":"松澤議長","answer":"マスコミの方がどのように報道されるかはわかりませんけれども、私はそれも世論ではないかと思って、その報道の仕方を注視していきたいと思いますし、また今後いろいろなほかの新聞社なんかも来るかと思いますけれども。","voiceIndex":72,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"意見","question":"最後にしますけれども、不信任が出されて、その理由が私にはわからないという議長のご発言ですが、では先ほど私もお話をしましたが、問題提起がなされたわけですよね。なので、私は何度もこの間そういった取り組みをしてほしいとお願いをしている中で、何のアクションも見られないと、やっぱり不信任の可決というのは非常に重く受けとめざるを得ないのかなと思いますので、最後に意見だけ申し述べます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"今まで各委員発言されたことと重なる部分もありますけれども、まず、この現状ですね、議会の混乱。５月２９日の臨時会の進行も副議長のもとで進行されました。やはり本当に健全化していただきたいと思うのですね。ぜひ区民目線で。１０８条の話はされるのはここにいる議員だったら全員が理解しております。ただ、求心力ですとか政治判断というのはやはり求められると思うのですね。要望して終わります。","respondent":"久保田区議会事務局長","answer":"その後、日程の第３０の第４４号議案、一般会計補正予算につきまして副区長から説明がありまして、歳出審査は各常任委員会に、また、総合審査は総務委員会に付託する予定です。","voiceIndex":75,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":25050,"voices":96}},{"id":"h30-20180629-10","meetingId":"h30-cm06","date":"2018年6月29日","dateIso":"2018-06-29","committee":"議会運営委員会","time":"午前 ９時３０分～午後 １時２４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"今日の議事日程、今から議運が開かれるということでありますけれども、昨日一日、会が開かれなかった。それから皆さんからお話を伺うと、いろいろな意見をお持ちの方がたくさんいらっしゃるようにも伺えます。それを皆さんに諮っていただいて、議運の中で、副議長進行と、あと、全員でというところを皆さんにご意見を伺って、ぜひそういう打開に向けた形をとっていただければと思って、提案をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":2,"id":"exchange-001"},{"speaker":"石田（し）委員","kind":"提案","question":"それと、今ご提案があった全員協議会ですが、これは基本的に議長の招集のもとになるのかなと認識しているのですが、今、こういった状況で、議会が空転する中で、やはり全議員が各々の思いを述べられるような機会の提供が必要だと思うので、これは議長にお願いしますが、ぜひ速やかに全員協議会の招集をかけていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それが１点です。それと今の、自民党、石田秀男委員の提案ですけれども、全員協議会というのは、申し合わせ事項のところでも、議長が必要に応じて全員協議会を招集して会議を主催するということになっておりますので、議長がどう考えられるのかということをお聞かせいただきたいと思います。そういうところでは、きちんとそこに対しての説明が必要だったのではないかということが１点。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いや、昨日の時点での説明が必要だったのではないかということが１点です。それと、議会というのは、区民のために、私たちも質問をつくりながら、みんなで議論する場というところでは、議会を開かないというところは本当に問題だと感じておりますので、そこのことについても申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"誰がどうのということではありません。ただ、もう１点、今、全員協議会のお申し出が２つの会派があったと思います。共産党と一緒で、これは議長が決めることだと思いますので、議長のご意見を伺いたいと思いますし、私どもとしては別にこれを遮る必要はないのかなとは思っております。これについても議長のご判断だと思いますので、ご判断はお任せしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-005"},{"speaker":"渡部委員長","kind":"質問・要望","question":"それぞれありがとうございました。鈴木ひろ子委員から私に問い合わせがあった件につきましては、大変申し訳なかったと。すみませんでした。今、話を一通り伺った中で、全員協議会に関しては議長のご意見ということなのですが、改めてこのような話が出てきた中で、議運の委員長といたしましても、この際、全員協議会の開催を議長に求めてまいりますが、議長、いかがでしょうか。","respondent":"松澤議長","answer":"今、全員協議会というお話がありましたけれども、全員協議会を開くのはまだ早いのかなと思っているところです。","voiceIndex":8,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"提案","question":"１０件程度だったと思います。だけど、これぐらいだと思っておりまして、今、それが普通だというお話だったので、もし普通だとおっしゃるのであれば、どれぐらいあったのか教えていただきたいのが１つ。早いというのは、どういうことなのか。我々は少しでも早く打開をして正常化をしようと思って提案させていただいているので、そこら辺をもう一度、改めてお伺いできればと思います。","respondent":"松澤議長","answer":"テレビのインタビューも受けさせていただきました。私としては何としても会を開いていただきたいということで、各会派を回らせていただきました。自民党・子ども未来は、議長が辞めなければ開会できないというお話やに私は受け取りました。","voiceIndex":11,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"提案","question":"何としても議会を開いていこうという思いで全員協議会も含めてご提案させていただいているので、もし第２回定例会を開催したいという思いがあるのであれば、速やかに全員協議会の招集をかけていただきたいと再度お願いしますし、我々としては、できるのであれば副議長で進行というのは昨日からずっと求めていて、それも会議を開くためにどういったことが打開策となるのかといった中で、結論が出たのが。","respondent":"松澤議長","answer":"そんな意味では、伏してお願いを申し上げますけれども、やはり議会をまず開催していただいて、全員協議会を開く要求等々がありましたら、議会を開いていただいて、その後に、終わってから全員協議会を開くなりというのが手順ではないかなと私としては思っているところですので。","voiceIndex":15,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"順番は、議会を開いてからではなくて、議会を開くために全員協議会をと我々は要望しているので、ぜひそこは理解していただきたいと思いますし、もし議長がそのまま全員協議会を開かないというのであれば、我々としては、議運の委員長に、議運の委員長の立場として、非公式であれ、何らかの形で全員集まる場を設けていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"全員協議会、私も議員になって７年ですけれども、まだ経験をしたことがないのですが、今、２つの会派からそういうご要望があって、議会を開会するために、今のこの閉塞した状況を打開したいとおっしゃっています。ですので、私どもとしては、私どもは別に開催を求めているわけではございませんが、これを否定するというのは、逆に議長のお立場が悪くなるのではないかなという感想を持っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"最後に１点だけ議長にお伺いしますが、我々は今この場でも主に２点要望させていただきました。これはなぜ要望したかというと、議会を開催するためにどういったことができるのかといった意味で要望させていただきましたが、両方ともその要望には応えることができないというお話ですが、それであれば、議長は、今回、第２回定例会を閉会しても構わないという考えを持っているのかだけ、教えてください。","respondent":"松澤議長","answer":"大変にたくさんの議案がありますので、何としても開かせていただいて、皆さん方のご協力を得たいと思います。","voiceIndex":23,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"提案","question":"それからもう１つは、全員で集まるということを議会運営委員会として、議長のもとで全員協議会が開けないのであれば、全員の懇談会みたいなこと、先ほど鈴木ひろ子委員もいろいろな思いがおありでしょうから、そういうことも、我々に対しても意見がおありだろうし、また、皆さんの前でもいろいろ意見があれば、ここはこういうふうにしていこうよというお考えもあるのであれば、１回全員で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本会議というのは、本当にとても重い〔「議決もそうだよ」と呼ぶ者あり〕ものですから、やはり出席して本会議を開催するというのは、議員としての義務だと思うのですね。それともう１つお聞かせいただきたいのは、委員会もそうなのですけれども、本会議とかを欠席する場合は、届出をして欠席しますよね。今回、そういう届出はあったのかということについてもお聞かせいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今の出席の捉え方が今ひとつわからなかったのですけれども、ボタンを押しただけで出席と認められて、本会議場にはいなくても出席ということで。〔「違う違う。","respondent":"久保田区議会事務局長","answer":"私が出席と申しましたのは、時間を追って説明しますと、１時の段階で本会議を開こうとして、ブザーを押して、放送を入れて、お集まりいただいたのですけれども、人数が定足数に達していませんので、その段階では本会議は開かれておらず、出席も欠席もないということです。","voiceIndex":31,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１時から始まるということで決まっていた本会議に、その場に来ていないというところで、それに対して、何の届出もなく本会議に来ていないということはあり得るのですか。","respondent":"久保田区議会事務局長、松澤議長","answer":"本会議にどこのタイミングで出席したかということになると思うのですけれども、１時から始まったのですけれども、１時の呼びかけには本会議場には来られなかったということですので。発言する前に、オブザーバーであるので云々という話がありましたけれども、これは大変に失礼な話ですので、オブザーバーだから後回しになったり、オブザーバーだから発言できないというふうにしては。","voiceIndex":33,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、議長からもお話があって、先ほどもそういうお話があったから、それを踏まえて我々は打開策を今日はお話しさせていただいているわけで、ではこういう状況で開くためにはどうしたらいいのですかと。議運として諮ってください。議運で決定をして、それで議長に申し入れをしてください。議長は今のこの状況を打開するためにはどういう考えがおありなのですかということも伺いました。","respondent":"松澤議長","answer":"そんな意味でも、議長の権限を縛ることを話し合うのだというような会議を開くのは、私は反対です。","voiceIndex":38,"id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"提案","question":"委員長の提案が幾つかあったのですけれども、私は今の議長の発言はとても重いと思うのです。議決が重いとおっしゃったけれども、その議決が、中身が不当であるということでとめるためにも、やはり地方自治法の中で、結論でいうと第１０８条で示されているといった意味においては、議長の権限を超えて、ここで決めることは許されないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは議長の権限として本会議を取り仕切るということになっているわけですから、その権限を議運で決めることはできないということが１つです。それと、先ほどから申し上げているように、１９人の賛成で可決されたことは事実ですけれども、それを踏まえた上で、議長の任期は議員の任期によるという地方自治法に基づいての法律があるわけですから。法律なのですから。混乱しているのは自民党です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"打開をするために全員協議会もどうですかという話をしているわけでありまして、それも今開く気がないというお言葉だから、では、会議を開く気はないのですねという質問にもお答えにならない、ただ出てきてくださいというだけのお答えだから、そういう形だから、それでは全員で集まる、名前はよくわからないけれども懇談会とか、そういうことを議運の委員長として仕切っていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。議長が本会議を取り仕切ることになっているのに、議運でそれを副議長にしていくと話し合うことそのものもおかしいですし、それを決めて議長に申し入れていくということは、やり方としても反対だし、おかしいと思います。決をとることもおかしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"自民党と国民民主党からの、〔「一方的って何ですか。一方的な発言も伺いました。だから、歩み寄りがないから進まないという話をしているわけですから、それで、ご提案についても、これは可能だとは思うのです。ただ、時間がかかって申し訳ないですが、この場で議運で申し入れにするかどうか、私どもの会派としては、これに賛成とか反対とか、１回持ち帰らせてもらいたいのです。技術的には可能だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-021"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"副議長進行につきましては、私どももこれは、はっきり申し上げて、議長職の進退云々ということではなく、ただ第２回定例会を何とかして開催をしたいという思いから、副議長進行やむなしということは前々から申してきたことなので、これに関しては、こういうことを議運で決定されるということであるならば、それは賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"共産党としての見解を申し上げたいと思います。今回の議会は、昨日、本会議に定刻に出席したのは議長と共産党と生活者ネットワークの１０名のみで、定刻に開催がされませんでした。共産党としては、混乱したときこそ、議会のルール、申し合わせ事項ですとか地方自治法、議員必携など、これまで確認されてきたルールに基づいて打開することが大事だと考えています。同時に、地方自治法も重いものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":18318,"voices":72}}]);
